-- 행 수: 107 · dev/local extract 2026-06-22
-- ============================================================

DELETE FROM SCM_MGR.SCM_ADM_DQ_LIST;

INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (1, '40', '2MKT FCST Adjust Report', 'MKT FCST Adjust Report', 'SELECT DIVISION_ID      , C.DEPT_NAME_KO   , B.USER_NAME      , PROJECT_CODE      , A.CREATED_BY      , COUNT(1) COUNTS   , TO_CHAR(A.LAST_UPDATE_DATE, ''YYYYMMDD'')  MODIFY_DATE   , ( select x.iso_yyyyww from SCM_SYS_CALENDAR_M x where x.BASIS_YYYYMMDD = TO_CHAR(A.LAST_UPDATE_DATE, ''YYYYMMDD'') ) yyyyww   , case TO_NUMBER(TO_CHAR(A.LAST_UPDATE_DATE, ''D'')) when 1 then ''SUN''                                          when 2 then ''MON''            when 3 then ''TUE''            when 4 then ''WED''            when 5 then ''THU''            when 6 then ''FRI''            when 7 then ''SAT'' end day_of_week   , TO_NUMBER(TO_CHAR(A.LAST_UPDATE_DATE, ''HH24'')) hour      , TO_CHAR(MAX(A.LAST_UPDATE_DATE), ''YYYY-MM-DD HH24:MI:SS'')  LAST_UPDATE_DATE FROM DM_PLN_MKT_FCST_H            A    ,SCM_MST_SSO_USER_INFO B    ,SCM_MST_SSO_DEPT_INFO C WHERE A.CREATED_BY = B.USER_ID   AND B.DEPT_ID = C.DEPT_ID   AND A.last_update_date > SYSDATE - 14  GROUP BY DIVISION_ID      , C.DEPT_NAME_KO   , B.USER_NAME      , PROJECT_CODE      , A.CREATED_BY   , TO_CHAR(A.LAST_UPDATE_DATE, ''YYYYMMDD'')   , TO_NUMBER(TO_CHAR(A.LAST_UPDATE_DATE, ''D''))   , TO_NUMBER(TO_CHAR(A.LAST_UPDATE_DATE, ''HH24''))  ', 'Y', 'Y', 'zytchoi', TO_DATE('2018-03-30 16:01:00','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:16:23','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (2, '40', 'User Access Count Planner', 'User Access Count Planner', 'select         CASE a.MenuID WHEN ''Sales Site Project M'' THEN ''Sales Site Project Model''                   WHEN ''Customer Model Mappi'' THEN ''Customer Model Mapping''       ELSE a.MenuID END MENU_ID    ,a.UserID       ,us.USER_NAME    , max( (case when dept.DEPT_NAME_KO is not null then dept.DEPT_NAME_KO else us.WORKING_NAME end ) ) DEPT_NAME_KO    ,TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') LOGIN_DATE    ,count(1) counts       --,COUNT(1) OVER(ORDER BY a.UserID) sum_count
from TB_FX_MenuConnectLog a       left outer join SCM_MST_SSO_USER_INFO us    on (a.UserID = us.USER_ID)       left outer join SCM_MST_SSO_DEPT_INFO dept    on (us.DEPT_ID = dept.DEPT_ID)  where 1=1    and a.UserID = us.USER_ID    and dept.DEPT_NAME_KO not like ''LG CNS%''    and TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') >= ''20180330''    and a.menuid IS NOT NULL    and (    select count(1)      from TB_FX_User z     where defaultgroupid in ( ''DM ADMIN'',''DM Planner'' )       and z.UserID = a.UserID        ) > 0 group by a.MenuID    ,a.UserID       ,us.USER_NAME    ,TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') ', 'Y', 'Y', 'zytchoi', TO_DATE('2018-04-02 09:49:00','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (27, '-', 'ESS CEG Sales Result', 'ESS CEG Sales Result', 'select A.COMPANY_ID
      ,DIVISION_ID
      ,A.RESULT_YYYYMM
      ,SALES_POSTING_DATE
      ,ITEM_TYPE
      ,CUSTOMER_CODE
      ,CUSTOMER_NAME
      ,CURRENCY
      ,SALES_AMOUNT_FOR AS AMT_LOCAL
      ,SALES_AMOUNT_SUM AS AMT_KRW
      ,UOM
      ,SALES_QTY
      ,ITEM_ID
      ,SHIPTO_CODE
      ,SHIPTO_DESCRIPTION
      ,COUNTRY
      ,COUNTRY_NAME
      ,SHIPTO_CITY_NAME
      ,SHIPTO_ZONE_CODE
      ,SHIPTO_ZONE_NAME
      ,RBU_CUSTOMER
      ,INCOTERMS
  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R a
      ,(
		select COMPANY_ID, RESULT_YYYYMM, max(ifseqno) ifseqno
		  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R
		 where DIVISION_ID = ''82''
		   and COMPANY_ID = ''G690''
		 group by COMPANY_ID, RESULT_YYYYMM
	   ) b
 where a.IFSEQNO = b.ifseqno
   and a.RESULT_YYYYMM = b.RESULT_YYYYMM
   and a.COMPANY_ID = b.COMPANY_ID
   and a.SHIPTO_CODE <> ''G690''
   and a.RESULT_YYYYMM = :PARAM1
   and a.DIVISION_ID = ''82''
--   and a.COST_ITEM = ''''', 'Y', 'Y', 'zytchoi', TO_DATE('2018-07-03 18:45:40','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (28, '-', 'Final Item BOM Query', 'Final Item BOM Query', 'SELECT /* TODO: add WHERE ROWNUM <= 10000 or FETCH FIRST 10000 ROWS ONLY */ a.DIVISION_ID,a.PLANT_ID,a.MODEL_ID,a.CHILD_ITEM_ID,a.OPERATION_GROUP_ID,a.ELECTRODE_TYPE,a.ACCUMULATED_CHILD_QTY
  FROM SCM_MST_MODEL_FINAL_ITEM_BOM_V a

       INNER JOIN ( SELECT DISTINCT MODEL_ID
                       FROM SCM_MST_MODEL_FINAL_ITEM_BOM_V
                      WHERE CHILD_ITEM_ID = :PARAM_CHILD_ITEM
                        OR MODEL_ID =:PARAM_CHILD_ITEM ) b
       ON a.MODEL_ID = b.MODEL_ID

 WHERE a.MODEL_ID <> a.CHILD_ITEM_ID
ORDER BY a.DIVISION_ID, a.PLANT_ID,a.MODEL_ID,a.OPERATION_SORT_NO', 'Y', 'Y', 'yydok', TO_DATE('2018-07-05 16:47:12','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:02:37','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (29, '-', '소형 Conversion 누락 대상', '소형 Conversion 누락 대상', 'select distinct ''DP'' SOURCE, SUBSTR( CUST_NM ,  INSTR(CUST_NM, ''>'')+1, LENGTH(CUST_NM )) "고객군"
      ,CUST_STORE_NM  "판매처"
	  ,cell_pack_model_cd
	  ,( select count(1) from scm_mst_item_sn w where w.division_id = ''40'' and case when SUBSTR(w.item_id,1,2) = ''MP'' THEN SUBSTR(w.item_id,1,11) else item_id end  = A.cell_pack_model_cd  )  ITEM_MASTER_EXIST
 FROM LGCE_SCMPROD.TEMP_DM_MST_MB_VIEW_V200_V$ A
 where (
				SELECT count(1)
				  FROM scm_mst_site_item B
				 where B.attribute2 = SUBSTR( CUST_NM ,  INSTR(CUST_NM, ''>'')+1, LENGTH(CUST_NM ))
				   AND B.attribute1 = CUST_STORE_NM 
				   and case when SUBSTR(b.item_id,1,2) = ''MP'' THEN SUBSTR(b.item_id,1,11) else item_id end  = A.cell_pack_model_cd 
       ) = 0 
UNION ALL
select distinct ''SALES'' SOURCE,SUBSTR( CUST_NM ,  INSTR(CUST_NM, ''>'')+1, LENGTH(CUST_NM )) "고객군"
      ,CUST_STORE_NM  "판매처"
	  ,cell_pack_model_cd
	  ,( select count(1) from scm_mst_item_sn w where w.division_id = ''40'' and case when SUBSTR(w.item_id,1,2) = ''MP'' THEN SUBSTR(w.item_id,1,11) else item_id end  = A.cell_pack_model_cd  )  ITEM_MASTER_EXIST
   FROM LGCE_SCMPROD.TEMP_DM_MOBILE_RTF_V$ A
 where (
				SELECT count(1)
				  FROM scm_mst_site_item B
				 where B.attribute2 = SUBSTR( CUST_NM ,  INSTR(CUST_NM, ''>'')+1, LENGTH(CUST_NM ))
				   AND B.attribute1 = CUST_STORE_NM 
				   and case when SUBSTR(b.item_id,1,2) = ''MP'' THEN SUBSTR(b.item_id,1,11) else item_id end  = A.cell_pack_model_cd 
       ) = 0 
	and A.YYYYMM >= ''2018-07''
    and pack_qty is not null
UNION ALL
select distinct ''CUST_FCST'' SOURCE,SUBSTR( CUST_NM ,  INSTR(CUST_NM, ''>'')+1, LENGTH(CUST_NM )) "고객군"
      ,CUST_STORE_NM  "판매처"
	  ,cell_pack_model_cd
	  ,( select count(1) from scm_mst_item_sn w where w.division_id = ''40'' and case when SUBSTR(w.item_id,1,2) = ''MP'' THEN SUBSTR(w.item_id,1,11) else item_id end  = A.cell_pack_model_cd  )  ITEM_MASTER_EXIST
   FROM LGCE_SCMPROD.TEMP_DM_MOBILE_CUST_FCST_V$ A
 where (
				SELECT count(1)
				  FROM scm_mst_site_item B
				 where B.attribute2 = SUBSTR( CUST_NM ,  INSTR(CUST_NM, ''>'')+1, LENGTH(CUST_NM ))
				   AND B.attribute1 = CUST_STORE_NM 
				   and case when SUBSTR(b.item_id,1,2) = ''MP'' THEN SUBSTR(b.item_id,1,11) else item_id end  = A.cell_pack_model_cd 
       ) = 0 
	and A.YYYYMM >= ''2018-07''
', 'N', 'Y', 'zytchoi', TO_DATE('2018-07-19 16:45:42','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:08:17','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (30, '-', '소형 실적 Mapping 시 누락 Soldto, Shipto', '소형 실적 Mapping 시 누락 Soldto, Shipto', ' SELECT DISTINCT SALES_YYYYMM,  A.DIVISION_ID, COMPANY_ID,  CUSTOMER_CODE, CUSTOMER_NAME,  SHIPTO_CODE, SHIPTO_DESCRIPTION,SALES_WORK_PLACE,SALES_WORK_PLACE_NAME
      ,CURRENCY
      ,MAT_GROUP
      ,MAT_GROUP_DESC
	  ,LGS_ROUTE_NAME
	  ,ITEM_ID
	  ,(
	    SELECT ''Y''
		  FROM SCM_MST_CUSTOMER  Z
		 WHERE Z.DIVISION_ID = A.DIVISION_ID
		   AND Z.SOLDTO_CODE = A.CUSTOMER_CODE
		   AND Z.SHIPTO_CODE = A.SHIPTO_CODE
	    ) MDM_EXIST
      ,COST_ITEM_NAME 
  FROM DM_DNM_SALES_RESULT_IF A
 WHERE 1=1
   --AND A.COST_ITEM_NAME = ''''
   AND A.LGS_ROUTE_NAME IN (''내수'',''직수출'')
   AND LENGTH(A.CUSTOMER_CODE) > 4 
   AND A.DIVISION_ID = :PARAM_DIVSION_ID
  --  AND SALES_YYYYMM >= ''201811''
   AND A.SALES_SITE_ID IN ( '''',''-'',''N'')
   AND (
	    SELECT COUNT(1)
		  FROM SCM_MST_SITE_CUSTOMER  Z
		      ,SCM_MST_SITE Y
		 WHERE Z.DIVISION_ID = A.DIVISION_ID
		   AND Z.SOLDTO_CODE = A.CUSTOMER_CODE
		   AND Z.SHIPTO_CODE = A.SHIPTO_CODE
		   AND Z.VALID_YN = ''Y''
		   AND Z.DIVISION_ID = Y.DIVISION_ID
		   AND Z.SCM_SITE_ID = Y.SCM_SITE_ID
		   AND Y.SITE_TYPE = ''SALES''
	    ) = 0

GROUP BY SALES_YYYYMM, A.DIVISION_ID, COMPANY_ID, CUSTOMER_CODE, CUSTOMER_NAME,  SHIPTO_CODE, SHIPTO_DESCRIPTION,SALES_WORK_PLACE,SALES_WORK_PLACE_NAME
      ,CURRENCY
      ,MAT_GROUP
      ,MAT_GROUP_DESC
	  ,LGS_ROUTE_NAME
	  ,ITEM_ID
      ,COST_ITEM_NAME 
HAVING SUM(SALES_QTY) <> 0

/*
 SELECT DISTINCT COMPANY_ID, A.DIVISION_ID, CUSTOMER_CODE, CUSTOMER_NAME,  SHIPTO_CODE, SHIPTO_DESCRIPTION,SALES_WORK_PLACE,SALES_WORK_PLACE_NAME
      ,CURRENCY
      ,MAT_GROUP
      ,MAT_GROUP_DESC
	  ,LGS_ROUTE_NAME
	  ,ITEM_ID
	  ,(
	    SELECT ''Y''
		  FROM SCM_MST_CUSTOMER  Z
		 WHERE Z.DIVISION_ID = A.DIVISION_ID
		   AND Z.SOLDTO_CODE = A.CUSTOMER_CODE
		   AND Z.SHIPTO_CODE = A.SHIPTO_CODE
	    ) MDM_EXIST
  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R A
      ,(
	     SELECT DIVISION_ID, MAX(IFSEQNO) MAX_IFSEQNO
		   FROM LGCE_INF.XIF_ERP_SALES_RESULT_R
		--
WHERE DIVISION_ID  = ''40'' 
                          WHERE  DIVISION_ID   = :PARAM_DIVSION_ID
         GROUP BY DIVISION_ID 
	   ) B
 WHERE IFSEQNO = B.MAX_IFSEQNO
   AND A.IFSEQNO = B.MAX_IFSEQNO
   AND TRANSFER_FLAG = ''X''
   AND A.DIVISION_ID = B.DIVISION_ID
   AND A.COST_ITEM_NAME = ''''
   AND A.LGS_ROUTE_NAME IN (''내수'',''직수출'')
   AND LENGTH(A.CUSTOMER_CODE) > 4 

UNION 

  SELECT DISTINCT COMPANY_ID, A.DIVISION_ID, CUSTOMER_CODE, CUSTOMER_NAME,  A.SHIPTO_CODE, SHIPTO_DESCRIPTION,SALES_WORK_PLACE,SALES_WORK_PLACE_NAME
      ,CURRENCY
      ,MAT_GROUP
      ,MAT_GROUP_DESC
	  ,LGS_ROUTE_NAME
	  ,ITEM_ID
	  ,(
	    SELECT ''Y''
		  FROM SCM_MST_CUSTOMER  Z
		 WHERE Z.DIVISION_ID = A.DIVISION_ID
		   AND Z.SOLDTO_CODE = A.CUSTOMER_CODE
		   AND Z.SHIPTO_CODE = A.SHIPTO_CODE
	    ) MDM_EXIST
  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R A
      ,(
	     SELECT DIVISION_ID, MAX(IFSEQNO) MAX_IFSEQNO
		   FROM LGCE_INF.XIF_ERP_SALES_RESULT_R
		  --
WHERE DIVISION_ID  = ''40'' 
                           WHERE DIVISION_ID = :PARAM_DIVSION_ID
         GROUP BY DIVISION_ID 
	   ) B
	  ,(
			SELECT DISTINCT A.DIVISION_ID, SOLDTO_CODE,  SHIPTO_CODE
			  FROM DM_DNM_SALES_RESULT A
			 WHERE DIVISION_ID = ''40''
			   AND SALES_SITE_ID = ''N''
			   AND YYYYMMDD >= ''20180801''
	   ) C
 WHERE IFSEQNO = B.MAX_IFSEQNO
   AND A.IFSEQNO = B.MAX_IFSEQNO
   AND A.DIVISION_ID = B.DIVISION_ID
   AND A.COST_ITEM_NAME = ''''
   AND A.LGS_ROUTE_NAME IN (''내수'',''직수출'')
   AND LENGTH(A.CUSTOMER_CODE) > 4 

   AND A.CUSTOMER_CODE = C.SOLDTO_CODE
   AND A.SHIPTO_CODE = C.SHIPTO_CODE
   AND A.DIVISION_ID = C.DIVISION_ID
*/
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-07-23 10:41:37','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (31, '-', 'GSCM(DM) to Mobile DMS key 누락 건', 'GSCM(DM) to Mobile DMS key 누락 건', 'SELECT DISTINCT D.DEPT_NAME_KO,  B.OWNER, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.MEASURE, T.NICK_NAME, B.ATTRIBUTE1, B.ATTRIBUTE2, B.ROUTE, B.CURRENCY,B.APPLICATION, A.CURRENCY "SALESPLAN_CURRENCY"
        ,B.CUST_GROUP, B.CUST_GROUP_DTL
  FROM LGCE_SCMPROD.DM_PLN_SALES_PLAN_C A
  --INNER JOIN ( SELECT Q.DIVISION_ID, MAX(VERSION_NO) VERSION_NO
FROM LGCE_SCMPROD.DM_PLN_SALES_PLAN_C Q WHERE Q.DIVISION_ID = ''40'' GROUP BY DIVISION_ID) X
  --ON A.VERSION_NO = X.VERSION_NO
  --AND A.DIVISION_ID = X.DIVISION_ID
  INNER JOIN LGCE_SCMPROD.SCM_MST_SITE_ITEM  B
    ON A.DIVISION_ID = ''40''
   AND A.DIVISION_ID = B.DIVISION_ID
   AND A.SCM_SITE_ID = B.SCM_SITE_ID
   AND A.PROJECT_CODE = B.PROJECT_CODE
   AND A.ITEM_ID = B.ITEM_ID
   AND A.MEASURE IN ( ''MKT_FCST'',''RTF''/*,, ''SALESAMT_KRW'' , ''SALESAMT_LOC''*/ )  -- 20181210 KHSONG RTF -> MKT_FCST 판가로 변경요청(주석처리) -> 20190104 KHSONG MKT_FCST -> RTF 판가로 재 변경요청
   --AND A.MEASURE IN ( ''MKT_FCST''/*,, ''SALESAMT_KRW'' , ''SALESAMT_LOC''*/ )  -- 20181210 KHSONG RTF -> MKT_FCST 판가로 변경요청(반영)
   AND B.VALID_YN = ''Y''
  INNER JOIN SCM_MST_SSO_USER_INFO E
    ON SUBSTR(B.OWNER, 1, case when INSTR(B.OWNER, '','') = 0 then LENGTH(B.OWNER)+1 else INSTR(B.OWNER, '','') end ) = E.USER_ID  -- 여러 OWNER인경우 1건만사용
  INNER JOIN SCM_MST_SSO_DEPT_INFO D
    ON E.DEPT_ID = D.DEPT_ID
   LEFT JOIN(  SELECT X.*, ROW_NUMBER() OVER ( PARTITION BY CUST_NM, CELL_PACK_MODEL_CD, CUST_STORE_NM,CURR_CD ORDER BY SALE_KEY  DESC ) ROW_NUM
	        FROM LN_DFPRD.DFPRD.MB_VIEW_V100 X
           ) C
    ON C.ROW_NUM = 1
   AND B.ATTRIBUTE1 = C.CUST_STORE_NM 
   AND B.ATTRIBUTE2 = C.CUST_NM 
   AND CASE WHEN SUBSTR( A.ITEM_ID,1,2) =''MP'' THEN SUBSTR( A.ITEM_ID,1,11) ELSE A.ITEM_ID END   = C.CELL_PACK_MODEL_CD 
   AND A.CURRENCY = CASE WHEN C.CURR_CD = ''CNY'' THEN ''RMB'' ELSE C.CURR_CD END 

  LEFT JOIN DM_MST_ITEM_SINGLE_V     T
	   ON A.DIVISION_ID  = T.DIVISION_ID AND    A.ITEM_ID      = T.ITEM_ID

WHERE 1=1
  AND C.CUST_NM IS NULL
  AND A.QTY <> 0 
  AND A.VERSION_NO = :PARAM1
  


UNION ALL

SELECT DISTINCT D.DEPT_NAME_KO,  B.OWNER, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.MEASURE, T.NICK_NAME, B.ATTRIBUTE1, B.ATTRIBUTE2, B.ROUTE, B.CURRENCY,B.APPLICATION
			, CASE WHEN A.CURRENCY = ''CNY'' THEN ''RMB'' ELSE A.CURRENCY END  "SALESPLAN_CURRENCY"
			,B.CUST_GROUP, B.CUST_GROUP_DTL
  FROM LGCE_SCMPROD.DM_PLN_SALES_PLAN_RESULT_C A
  --INNER JOIN ( SELECT Q.DIVISION_ID, MAX(VERSION_NO) VERSION_NO
FROM LGCE_SCMPROD.DM_PLN_SALES_PLAN_C Q WHERE Q.DIVISION_ID = ''40'' GROUP BY DIVISION_ID) X
  --ON A.VERSION_NO = X.VERSION_NO
  --AND A.DIVISION_ID = X.DIVISION_ID
  INNER JOIN LGCE_SCMPROD.SCM_MST_SITE_ITEM  B
    ON A.DIVISION_ID = ''40''
   AND A.DIVISION_ID = B.DIVISION_ID
   AND A.SCM_SITE_ID = B.SCM_SITE_ID
   AND A.PROJECT_CODE = B.PROJECT_CODE
   AND A.ITEM_ID = B.ITEM_ID
   AND A.MEASURE IN ( ''MKT_FCST'',''RTF''/*,, ''SALESAMT_KRW'' , ''SALESAMT_LOC''*/ )
   AND B.VALID_YN = ''Y''
  INNER JOIN SCM_MST_SSO_USER_INFO E
    ON SUBSTR(B.OWNER, 1, case when INSTR(B.OWNER, '','') = 0 then LENGTH(B.OWNER)+1 else INSTR(B.OWNER, '','') end ) = E.USER_ID  -- 여러 OWNER인경우 1건만사용
  INNER JOIN SCM_MST_SSO_DEPT_INFO D
    ON E.DEPT_ID = D.DEPT_ID
   LEFT JOIN(  SELECT X.*, ROW_NUMBER() OVER ( PARTITION BY CUST_NM, CELL_PACK_MODEL_CD, CUST_STORE_NM,CURR_CD ORDER BY SALE_KEY  DESC ) ROW_NUM
	        FROM LN_DFPRD.DFPRD.MB_VIEW_V100 X
           ) C
    ON C.ROW_NUM = 1
   AND B.ATTRIBUTE1 = C.CUST_STORE_NM 
   AND B.ATTRIBUTE2 = C.CUST_NM 
   AND CASE WHEN SUBSTR( A.ITEM_ID,1,2) =''MP'' THEN SUBSTR( A.ITEM_ID,1,11) ELSE A.ITEM_ID END   = C.CELL_PACK_MODEL_CD 
   AND A.CURRENCY = CASE WHEN C.CURR_CD = ''CNY'' THEN ''RMB'' ELSE C.CURR_CD END 

  LEFT JOIN DM_MST_ITEM_SINGLE_V     T
	   ON A.DIVISION_ID  = T.DIVISION_ID AND    A.ITEM_ID      = T.ITEM_ID

WHERE 1=1
  AND C.CUST_NM IS NULL
  AND A.QTY <> 0 
  AND A.VERSION_NO = :PARAM1
  AND A.YYYYMMDD >= SUBSTR(A.CUTOFF_YYYYMMDD, 1,6) + ''01''
', 'Y', 'Y', 'songkeeho', TO_DATE('2018-07-30 17:49:50','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:02:37','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (32, '-', 'SITE Customer Mapping', 'SITE Customer Mapping', 'SELECT DIVISION_ID
      ,SCM_SITE_ID
      ,SOLDTO_CODE
      ,SHIPTO_CODE
      ,REP_YN
      ,VALID_YN
