      ,ATTRIBUTE7
      ,ATTRIBUTE8
      ,ATTRIBUTE9
      ,ATTRIBUTE10
  FROM LGCE_SCMPROD.SCM_MST_SITE_CUSTOMER
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-07-31 10:59:16','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (33, '-', '(MDM) Soldto-Shipto Mapping', '(MDM) Soldto-Shipto Mapping', 'SELECT DIVISION_ID
      ,SOLDTO_CODE
      ,SHIPTO_CODE
      ,SOLDTO_DESCRIPTION
      ,SOLDTO_ADDRESS
      ,SOLDTO_COUNTRY
      ,SOLDTO_REGION
      ,SOLDTO_REGION_NAME
      ,SOLDTO_CITY_NAME
      ,SHIPTO_DESCRIPTION
      ,SHIPTO_ADDRESS
      ,SHIPTO_COUNTRY
      ,SHIPTO_REGION
      ,SHIPTO_REGION_NAME
      ,SHIPTO_CITY_NAME
      ,VALID_YN
      ,CITY
  FROM LGCE_SCMPROD.SCM_MST_CUSTOMER
 where VALID_YN = ''Y''
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-07-31 11:14:36','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (34, '-', '소형 End Customer Lookup 미 존재건', '소형 End Customer Lookup 미 존재건', 'select distinct (
  select ATTRIBUTE1
  FROM LGCE_SCMPROD.SCM_ADM_LOOKUP_MASTER_DETAIL b
 where LOOKUP_TYPE = ''MTRL_GRP3_MAPPING''           
   and a.MAT_GROUP = b.SEGMENT3
   and a.COMPANY_ID = b.SEGMENT2
   and a.DIVISION_ID = b.segment1
       ) End_customer , a.MAT_GROUP, a.mat_group_desc , a.COMPANY_ID, a.CUSTOMER_CODE, a.customer_name, a.shipto_code, a.SHIPTO_DESCRIPTION, a.ITEM_ID, a.COST_ITEM, a.COST_ITEM_NAME, a.item_type, a.sales_work_place_name
  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R a
      ,(
			select max(ifseqno) max_ifseqno  
			  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R a
			 where division_id = ''40''
	   ) seq
 where division_id = ''40'' 
   and ifseqno = seq.max_ifseqno
   and a.MAT_GROUP IS NOT NULL
   AND (
		  SELECT ATTRIBUTE1
		  FROM LGCE_SCMPROD.SCM_ADM_LOOKUP_MASTER_DETAIL B
		 WHERE LOOKUP_TYPE = ''MTRL_GRP3_MAPPING''           
		   AND A.MAT_GROUP = B.SEGMENT3
		   AND A.COMPANY_ID = B.SEGMENT2
		   AND A.DIVISION_ID = B.SEGMENT1
	    ) IS NULL

', 'Y', 'Y', 'zytchoi', TO_DATE('2018-09-05 09:00:07','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (42, '-', 'Company 정보 불일치 건', 'Company 정보 불일치 건', 'SELECT distinct 
        COMPANY_ID,DIVISION_ID,CUSTOMER_CODE,CUSTOMER_NAME,SHIPTO_CODE,SHIPTO_DESCRIPTION,SALES_SITE_ID
	   ,(
	      select b.COMPANY_ID
		    from scm_mst_site b
		   where a.division_id = b.division_id
		     and a.SALES_SITE_ID = b.scm_site_id
	    ) SALES_SITE_COMPANY_ID
	   ,CASE WHEN COMPANY_ID =  (
	      select b.COMPANY_ID
		    from scm_mst_site b
		   where a.division_id = b.division_id
		     and a.SALES_SITE_ID = b.scm_site_id
	    ) THEN ''SAME'' ELSE ''DIFF'' END DIFF

      ,(
					 SELECT distinct  (SELECT LISTAGG(DISTINCT z.dept_name_ko, '','') WITHIN GROUP (ORDER BY z.dept_name_ko) from scm_mst_site_item x
												  ,SCM_MST_SSO_USER_INFO y
												  ,SCM_MST_SSO_DEPT_INFO z
											 where x.division_id = a.division_id
											   and x.scm_site_id = a.SALES_SITE_ID
											   and x.owner = y.user_id
											   and y.dept_id = z.dept_id 
											   and x.valid_yn = ''Y'') 
	   ) TEAM
      ,(
					 SELECT distinct  (SELECT LISTAGG(DISTINCT y.user_name || '''' || y.job_name, '','') WITHIN GROUP (ORDER BY y.user_name || '''' || y.job_name) from scm_mst_site_item x
												  ,SCM_MST_SSO_USER_INFO y
												  ,SCM_MST_SSO_DEPT_INFO z
											 where x.division_id = a.division_id
											   and x.scm_site_id = a.SALES_SITE_ID
											   and x.owner = y.user_id
											   and y.dept_id = z.dept_id 
											   and x.valid_yn = ''Y'') 
	   ) OWNER

  FROM DM_DNM_SALES_RESULT_IF a
 WHERE 1=1
   and division_id = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN division_id ELSE :PARAM_DIVSION_ID END )
   AND COST_ITEM_NAME = ''''
   and LENGTH(CUSTOMER_CODE) > 4
AND A.LGS_ROUTE_NAME IN (''내수'',''직수출'')
   and sales_yyyymm >= SUBSTR( TO_CHAR(ADD_MONTHS(SYSDATE, -1), ''YYYYMMDD'') , 1,6)', 'Y', 'Y', 'zytchoi', TO_DATE('2018-11-05 14:30:48','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:23:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (43, '-', 'SITE-SHIPTO 도시 비교', 'SITE-SHIPTO 도시 비교', '
select b.division_id, b.scm_site_id, b.city SITE_CITY , (
                                  select city_name
								    from scm_mst_city c 
								  where b.city = c.city
                               ) city_name
							,a.soldto_code
							,a.shipto_code
							 ,(
							     select shipto_city_name
                                   from scm_mst_customer d
								  where a.soldto_code  = d.soldto_code
								    and a.shipto_code  = d.shipto_code
									and a.division_id  = d.division_id
							  ) shipto_city_name
  from scm_mst_site_customer a
      ,scm_mst_site b
 where a.division_id = b.division_id
   and a.scm_site_id = b.scm_site_id
   and b.site_type = ''SALES''
   and a.valid_yn = ''Y''
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-11-05 17:07:45','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:41','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (35, '-', 'FCST 구간별 변동율 조회 리포트', 'FCST 구간별 변동율 조회 리포트', 'SELECT DIVISION_ID
      ,VERSION_NO
      ,PROJECT_CODE
      ,SCM_SITE_ID
      ,ITEM_ID
      ,DOM_EXP
      ,FCST_TYPE
      ,INCOTERMS
      ,PLANT_SITE_ID
      ,S1_BF_WK_FCST
      ,S1_NOW_WK_FCST
      ,S1_CO_FCST
      ,S1_NEW_FCST
      ,S1_DEL_FCST
      ,S2_BF_WK_FCST
      ,S2_NOW_WK_FCST
      ,S2_CO_FCST
      ,S2_NEW_FCST
      ,S2_DEL_FCST
      ,S3_BF_WK_FCST
      ,S3_NOW_WK_FCST
      ,S3_CO_FCST
      ,S3_NEW_FCST
      ,S3_DEL_FCST
  FROM LGCE_SCMPROD.DM_PLN_DEMAND_CHANGE_STATUS
 where division_id = CASE WHEN :PARAM_DIVSION_ID = '''' THEN  division_id ELSE :PARAM_DIVSION_ID END
   and version_no =  CASE WHEN :PARAM_VERSION_NO = '''' THEN  version_no ELSE :PARAM_VERSION_NO END
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-10-04 10:18:09','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (36, '-', 'Sales Result Query Detail', '매출 Raw', 'SELECT * FROM
		(

SELECT a.*, b.owner, c.dept_name_ko, c.USER_NAME || '' '' || c.job_name USER_NAME
           ,/*DATEDIFF_NEEDS_UNIT_SPECIFIC_CALC*/DATEDIFF(dd,a.sales_posting_date,a.system_input_date) SALES_LT
  FROM DM_DNM_SALES_RESULT_IF a
  left join scm_mst_site_item b
    on a.division_id = b.division_id
	and a.project_code = b.project_code
	and a.sales_site_id = b.scm_site_id
	and a.item_id = b.item_id
  left join (
			SELECT B.USER_ID, B.USER_NAME, B.USER_NAME_EN, B.DEPT_ID, C.DEPT_NAME_KO , c.upper_dept_id , b.JOB_NAME
			FROM SCM_MST_SSO_USER_INFO B
			INNER JOIN SCM_MST_SSO_DEPT_INFO C
			ON B.DEPT_ID = C.DEPT_ID
	        ) c
     on c.USER_ID   IN (SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ token FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT(b.owner, '',''))
 WHERE a.DIVISION_ID = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN a.DIVISION_ID ELSE :PARAM_DIVSION_ID END )
   AND a.SALES_YYYYMM = ( CASE WHEN :PARAM_SALES_YYYYMM = '''' THEN a.SALES_YYYYMM ELSE :PARAM_SALES_YYYYMM END )
   AND a.SALES_SITE_ID = ( CASE WHEN :PARAM_SALES_SITE_ID = '''' THEN a.SALES_SITE_ID ELSE :PARAM_SALES_SITE_ID END )
   AND a.ITEM_ID = ( CASE WHEN :PARAM_ITEM_ID = '''' THEN a.ITEM_ID ELSE :PARAM_ITEM_ID END )
		) AA

', 'Y', 'Y', 'zytchoi', TO_DATE('2018-10-17 11:52:29','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:18','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (37, '-', '소형 원통형 미사용 모델중 FCST나 RTF 존재건', '소형 원통형 미사용 모델중 FCST나 RTF 존재건', '
select a.*, ( select valid_yn from scm_mst_site_item x where x.division_id = a.division_id and a.scm_site_id = x.scm_site_id and a.item_id = x.item_id and a.project_code = x.project_code) SITE_ITEM_VALID
          , ( select owner from scm_mst_site_item x where x.division_id = a.division_id and a.scm_site_id = x.scm_site_id and a.item_id = x.item_id and a.project_code = x.project_code) OWNER
