			 where division_id = ''40''
			   and ITEM_CLASS_NAME = ''[MCC]Cylindrical''
	   ) b
 where a.division_id = ''40''
   and a.item_id = b.item_id
   and a.yyyymmdd >= ''20181015''
   and a.qty <> 0 
   and a.measure in (''MKT_FCST'',''RTF'',''CUST_FCST'')
   and a.item_id not in (
 ''MCCM346010A1''
