', 'N', 'Y', 'zytchoi', TO_DATE('2018-10-18 16:13:00','YYYY-MM-DD HH24:MI:SS'), 'zytchoi', TO_DATE('2019-02-22 17:55:46','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (38, '-', 'KPI_매출계획적확도', 'KPI_매출계획적확도', TO_CLOB('
SELECT *
  FROM (
  SELECT DIVISION_ID,'''' DEPT_NAME,'''' TEAM_NAME,'''' END_CUSTOMER,'''' PROJECT_NAME, '''' SCM_SITE_ID, '''' ITEM_ID, '''' NICK_NAME, ''M'' || YYYYMM as YYYYMM , SUM ( KPI_RATE * ( WEIGHT/ ACCUM_QTY ) )*100  KPI
   FROM (
    SELECT * ,  SUM(WEIGHT) OVER ( PARTITION BY DIVISION_ID,YYYYMM ) ACCUM_QTY
     FROM (
SELECT A.WORK_YYYYMMDD
      ,A.DIVISION_ID
      ,A.DEPT_ID
   ,DEPT.DEPT_NAME
   ,DEPT.TEAM_NAME
      ,END_CUSTOMER
      ,SCM_SITE_ID
      ,A.PROJECT_CODE
   ,PROJECT.PROJECT_NAME
      ,ITEM_ID
   ,(
      SELECT DISTINCT NICK_NAME FROM SCM_MST_ITEM_SN  ITEM WHERE ITEM.DIVISION_ID = A.DIVISION_ID AND ITEM.ITEM_ID = A.ITEM_ID  
    ) NICK_NAME
   ,(
      SELECT CASE  MIN( CASE WHEN ITEM.ITEM_TYPE = ''P'' THEN 1     --타입이 사이트와 사업부, 법인에 따라 다양하게 존재 하므로 하나로 통일
           WHEN ITEM.ITEM_TYPE = ''H'' THEN 2     --또한 가장 완성된 상태의 자재 타입을 판매한다고 가정, 해당 자재타입을 사용함
           WHEN ITEM.ITEM_TYPE = ''Q'' THEN 3
           ELSE 4 END )  
               WHEN 1 THEN ''P'' 
               WHEN 2 THEN ''H''
               WHEN 3 THEN ''Q''
               ELSE ''R'' END 
    FROM SCM_MST_ITEM_SN  ITEM WHERE ITEM.DIVISION_ID = A.DIVISION_ID AND ITEM.ITEM_ID = A.ITEM_ID  
    ) ITEM_TYPE
   ,A.FCST_TYPE
      ,CASE SUBSTR( A.FCST_TYPE, 1,1) WHEN ''S'' THEN ''SAMPLE'' 
                                      WHEN ''M'' THEN ''MASS''
           WHEN ''T'' THEN ''TEST''
           WHEN ''A'' THEN ''A/S''
     ELSE A.FCST_TYPE END  FCST_TYPE_NAME
      ,YYYYMM
      ,RESULT_QTY
      ,MEASURE
      ,WEIGHT
      ,KPI_RATE
  FROM LGCE_SCMPROD.DM_ANL_KPI_SALES_ACCURACY A
      ,(
      SELECT DIVISION_ID, MAX(WORK_YYYYMMDD) WORK_YYYYMMDD
     FROM LGCE_SCMPROD.DM_ANL_KPI_SALES_ACCURACY B
    GROUP BY DIVISION_ID
    ) X
   ,(
  SELECT X.DEPT_NAME_KO TEAM_NAME, Y.DEPT_NAME_KO DEPT_NAME, X.DEPT_ID
   FROM LGCE_SCMPROD.SCM_MST_SSO_DEPT_INFO X
    ,LGCE_SCMPROD.SCM_MST_SSO_DEPT_INFO Y
   WHERE X.UPPER_DEPT_ID = Y.DEPT_ID
    ) DEPT
   ,SCM_MST_PROJECT PROJECT 
 WHERE A.DIVISION_ID = X.DIVISION_ID
   AND A.WORK_YYYYMMDD = X.WORK_YYYYMMDD
   AND A.DEPT_ID = DEPT.DEPT_ID
   AND A.PROJECT_CODE = PROJECT.PROJECT_CODE
   AND A.DIVISION_ID = PROJECT.DIVISION_ID
) A
     WHERE MEASURE = ''RTF''
     AND FCST_TYPE_NAME IN ( ''MASS'' )
     AND ITEM_TYPE IN ( ''P'' )
     AND YYYYMM BETWEEN ''201807'' AND ''201811''
    ) U 
  GROUP BY DIVISION_ID,YYYYMM
  UNION ALL
  SELECT DIVISION_ID,DEPT_NAME,'''' TEAM_NAME,'''' END_CUSTOMER,'''' PROJECT_NAME,'''' SCM_SITE_ID,'''' ITEM_ID,'''' NICK_NAME, ''M'' || YYYYMM as YYYYMM, SUM ( KPI_RATE * ( WEIGHT/ ACCUM_QTY ) )*100  KPI
   FROM (
    SELECT * ,  SUM(WEIGHT) OVER ( PARTITION BY DIVISION_ID, DEPT_NAME,YYYYMM ) ACCUM_QTY
     FROM (
SELECT A.WORK_YYYYMMDD
      ,A.DIVISION_ID
      ,A.DEPT_ID
   ,DEPT.DEPT_NAME
   ,DEPT.TEAM_NAME
      ,END_CUSTOMER
      ,SCM_SITE_ID
      ,A.PROJECT_CODE
   ,PROJECT.PROJECT_NAME
      ,ITEM_ID
   ,(
