   FROM (
					SELECT * ,  SUM(WEIGHT) OVER ( PARTITION BY DIVISION_ID,YYYYMM ) ACCUM_QTY
					 FROM (
								SELECT A.WORK_YYYYMMDD
									  ,A.DIVISION_ID
									  ,A.DEPT_ID
								   ,DEPT.DEPT_NAME
								   ,DEPT.TEAM_NAME
