INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (40, '-', 'MKT FCST Base amount', 'MKT FCST에 Price를 곱한 금액 조회', TO_CLOB('-- DQ parameter insert 
SELECT   W.DIVISION_ID,W.PROJECT_CODE,PROJECT.PROJECT_NAME,DEPT.DEPT_NAME_KO,SITE.END_CUSTOMER,W.SCM_SITE_ID
		,W.ITEM_ID,ITEM.ITEM_NAME,W.DOM_EXP,W.FCST_TYPE,W.INCOTERMS,''MKT_FCST'' MEASURE
		,W.PLANT_SITE_ID,W.YYYYMMDD,W.CURRENCY
		,W.QTY -- 20180404 SONGKH NUMERIC->NUMERIC(30,10)으로 수정
FROM DM_PLN_SALES_PLAN_RESULT_C W
	INNER JOIN SCM_SYS_CALENDAR_M CAL
	ON   BASIS_YYYYMMDD = W.YYYYMMDD
	INNER JOIN DM_MST_ITEM_SINGLE_V ITEM
	ON   W.DIVISION_ID = ITEM.DIVISION_ID
	AND  W.ITEM_ID = ITEM.ITEM_ID
	LEFT  JOIN SCM_MST_SITE SITE
	ON   W.DIVISION_ID = SITE.DIVISION_ID
	AND  W.SCM_SITE_ID = SITE.SCM_SITE_ID
	LEFT JOIN SCM_MST_SSO_DEPT_INFO DEPT
	ON   SITE.DEPT_ID = DEPT.DEPT_ID
	LEFT JOIN SCM_MST_PROJECT PROJECT
	ON   W.DIVISION_ID = PROJECT.DIVISION_ID
	AND  W.PROJECT_CODE = PROJECT.PROJECT_CODE
	WHERE W.MEASURE = ''RTF''
	AND W.DIVISION_ID = :PARAM_DIVISION 
	AND W.VERSION_NO = :PARAM_VERSION   
	AND W.YYYYMMDD   >= CASE WHEN :PARAM_FROM  = '''' THEN W.YYYYMMDD ELSE  :PARAM_FROM  END
	AND W.YYYYMMDD   <= CASE WHEN :PARAM_TO    = '''' THEN W.YYYYMMDD ELSE  :PARAM_TO    END
	AND W.QTY <> 0
UNION ALL
SELECT   W.DIVISION_ID,W.PROJECT_CODE,PROJECT.PROJECT_NAME,DEPT.DEPT_NAME_KO,SITE.END_CUSTOMER
		,W.SCM_SITE_ID,W.ITEM_ID,ITEM.ITEM_NAME,W.DOM_EXP,W.FCST_TYPE,W.INCOTERMS
		,''SalesAmt_KRW'' MEASURE	,W.PLANT_SITE_ID,W.YYYYMMDD	,W.CURRENCY
		,W.QTY -- 20180404 SONGKH NUMERIC->NUMERIC(30,10)으로 수정
FROM DM_PLN_SALES_PLAN_RESULT_C W
	INNER JOIN SCM_SYS_CALENDAR_M CAL
	ON   BASIS_YYYYMMDD = W.YYYYMMDD
