	INNER JOIN SCM_SYS_CALENDAR_M CAL
	ON   BASIS_YYYYMMDD = W.YYYYMMDD
	INNER JOIN DM_MST_ITEM_SINGLE_V ITEM
	ON   W.DIVISION_ID = ITEM.DIVISION_ID
	AND  W.ITEM_ID = ITEM.ITEM_ID
	INNER JOIN SCM_MST_SITE SITE
	ON   W.DIVISION_ID = SITE.DIVISION_ID
	AND  W.SCM_SITE_ID = SITE.SCM_SITE_ID
	LEFT JOIN SCM_MST_SSO_DEPT_INFO DEPT
	ON   SITE.DEPT_ID = DEPT.DEPT_ID
	LEFT JOIN SCM_MST_PROJECT PROJECT
	ON   W.DIVISION_ID = PROJECT.DIVISION_ID
	AND  W.PROJECT_CODE = PROJECT.PROJECT_CODE
	LEFT MERGE JOIN (SELECT * FROM  SCM_MST_FUTURE_PRICE_C WHERE DIVISION_ID = :PARAM_DIVISION  AND VERSION_NO = :PARAM_VERSION   ) FP 
	ON (    FP.DIVISION_ID   = W.DIVISION_ID
		AND FP.PROJECT_CODE  = W.PROJECT_CODE') || TO_CLOB('
		AND FP.SCM_SITE_ID   = W.SCM_SITE_ID
		AND FP.ITEM_ID       = W.ITEM_ID
		AND FP.DOM_EXP       = W.DOM_EXP
		AND FP.FCST_TYPE     = W.FCST_TYPE
		AND FP.INCOTERMS     = W.INCOTERMS
		AND FP.PLANT_SITE_ID = W.PLANT_SITE_ID
		AND CAL.BASIS_START_DATE     = FP.YYYYMMDD
		AND FP.MEASURE = ''USD'' 
	   )
     INNER JOIN SCM_MST_SITE_ITEM SI
	  ON  W.DIVISION_ID = SI.DIVISION_ID
	  AND W.SCM_SITE_ID  = SI.SCM_SITE_ID
	  AND W.PROJECT_CODE = SI.PROJECT_CODE
	  AND W.ITEM_ID      = SI.ITEM_ID
	  AND SI.SALES_PLAN_ADJUST_YN <> ''N''
	WHERE W.MEASURE = ''MKT_FCST''
	AND W.DIVISION_ID = :PARAM_DIVISION 
	AND W.VERSION_NO = :PARAM_VERSION   
	AND W.YYYYMMDD   >= CASE WHEN :PARAM_FROM  = '''' THEN W.YYYYMMDD ELSE  :PARAM_FROM  END
	AND W.YYYYMMDD   <= CASE WHEN :PARAM_TO    = '''' THEN W.YYYYMMDD ELSE  :PARAM_TO    END
	UNION ALL 
SELECT   W.DIVISION_ID,W.PROJECT_CODE,PROJECT.PROJECT_NAME,DEPT.DEPT_NAME_KO,SITE.END_CUSTOMER,W.SCM_SITE_ID
		,W.ITEM_ID,ITEM.ITEM_NAME,W.DOM_EXP,W.FCST_TYPE,W.INCOTERMS,''SalesAmt_LOC'' MEASURE
		,W.PLANT_SITE_ID,W.YYYYMMDD,FP.CURRENCY
		,CAST( STR( W.QTY * NVL(FP.PRICE , 0) , 20, 5 ) AS NUMERIC(30, 10))  -- 20180404 SONGKH NUMERIC->NUMERIC(30,10)으로 수정
FROM DM_PLN_SALES_PLAN_C W
	INNER JOIN SCM_SYS_CALENDAR_M CAL
	ON   BASIS_YYYYMMDD = W.YYYYMMDD
	INNER JOIN DM_MST_ITEM_SINGLE_V ITEM
	ON   W.DIVISION_ID = ITEM.DIVISION_ID
	AND  W.ITEM_ID = ITEM.ITEM_ID
	INNER JOIN SCM_MST_SITE SITE
	ON   W.DIVISION_ID = SITE.DIVISION_ID
	AND  W.SCM_SITE_ID = SITE.SCM_SITE_ID
	LEFT JOIN SCM_MST_SSO_DEPT_INFO DEPT
	ON   SITE.DEPT_ID = DEPT.DEPT_ID
	LEFT JOIN SCM_MST_PROJECT PROJECT
	ON   W.DIVISION_ID = PROJECT.DIVISION_ID
	AND  W.PROJECT_CODE = PROJECT.PROJECT_CODE
	--LEFT JOIN (SELECT *
FROM  SCM_MST_FUTURE_PRICE_C WITH( index(IX01_SCM_MST_FUTURE_PRICE_C), NOLOCK) WHERE DIVISION_ID = :PARAM_DIVISION  AND VERSION_NO = :PARAM_VERSION   ) FP 
	LEFT MERGE JOIN SCM_MST_FUTURE_PRICE_C FP WITH( index(IX01_SCM_MST_FUTURE_PRICE_C), NOLOCK)
	ON (    FP.division_id = :PARAM_DIVISION
		and FP.version_no = :PARAM_VERSION 
		AND FP.CUTOFF_TYPE = SUBSTR(:PARAM_VERSION,1,4)
	    AND FP.DIVISION_ID   = W.DIVISION_ID
		AND FP.PROJECT_CODE  = W.PROJECT_CODE
		AND FP.SCM_SITE_ID   = W.SCM_SITE_ID
		AND FP.ITEM_ID       = W.ITEM_ID
		AND FP.DOM_EXP       = W.DOM_EXP
		AND FP.FCST_TYPE     = W.FCST_TYPE
		AND FP.INCOTERMS     = W.INCOTERMS
		AND FP.PLANT_SITE_ID = W.PLANT_SITE_ID
		AND CAL.BASIS_START_DATE = FP.YYYYMMDD

		AND FP.MEASURE = ''LOC'' 
	   )
     INNER JOIN SCM_MST_SITE_ITEM SI
	  ON  W.DIVISION_ID = SI.DIVISION_ID
	  AND W.SCM_SITE_ID  = SI.SCM_SITE_ID
	  AND W.PROJECT_CODE = SI.PROJECT_CODE
	  AND W.ITEM_ID      = SI.ITEM_ID
	  AND SI.SALES_PLAN_ADJUST_YN <> ''N''
	WHERE W.MEASURE = ''MKT_FCST''
	AND W.DIVISION_ID = :PARAM_DIVISION 
	AND W.VERSION_NO = :PARAM_VERSION   
	AND W.YYYYMMDD   >= CASE WHEN :PARAM_FROM  = '''' THEN W.YYYYMMDD ELSE  :PARAM_FROM  END
	AND W.YYYYMMDD   <= CASE WHEN :PARAM_TO    = '''' THEN W.YYYYMMDD ELSE  :PARAM_TO    END

    UNION ALL 

