-- 20181221 DM_PLN_MDF_RESULT 추가
SELECT   DIVISION_ID,'''' AS PROJECT_CODE,ITEM_TEXT AS PROJECT_NAME,'''' AS DEPT_NAME_KO,'''' AS END_CUSTOMER
		,CUSTOMER_NAME AS SCM_SITE_ID,''MDF'' AS ITEM_ID,''MDF'' AS ITEM_ID,'''' AS DOM_EXP,'''' AS FCST_TYPE') || TO_CLOB(','''' AS INCOTERMS,'''' AS MEASURE
		,'''' AS PLANT_SITE_ID,REPLACE(SALES_POSTING_DATE,''-'','''')
		,CURRENCY
		,SUM(CAST(AMOUNT AS numeric(20,10)) )
 FROM LGCE_SCMPROD.DM_PLN_MDF_RESULT W
 WHERE DIVISION_ID = :PARAM_DIVISION
	AND REPLACE(SALES_POSTING_DATE,''-'','''')   >= CASE WHEN :PARAM_FROM  = '''' THEN REPLACE(SALES_POSTING_DATE,''-'','''') ELSE  :PARAM_FROM  END
	AND REPLACE(SALES_POSTING_DATE,''-'','''')   <= CASE WHEN :PARAM_TO    = '''' THEN REPLACE(SALES_POSTING_DATE,''-'','''') ELSE  :PARAM_TO    END
 GROUP BY DIVISION_ID,ITEM_TEXT,SALES_POSTING_DATE,CURRENCY,CUSTOMER_NAME,ACCOUNTING_DOC_NO
'), 'Y', 'Y', 'zytchoi', TO_DATE('2018-10-25 11:44:25','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (41, '-', '소형사업부 Incoterms 계획/실적 비교', '소형사업부 Incoterms 계획/실적 비교', 'SELECT DISTINCT FCST_RAW.*, SALES_RESULT.INCOTERMS RESULT_INCOTERMS, CASE WHEN FCST_RAW.INCOTERMS = SALES_RESULT.INCOTERMS THEN '''' ELSE ''DIFF'' END DIFF
  FROM (
			SELECT DISTINCT A.DIVISION_ID, D.DEPT_NAME_KO, B.OWNER, C.user_name, C.job_name, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.INCOTERMS
			  FROM DM_PLN_MKT_FCST A
				  ,SCM_MST_SITE_ITEM B
				  ,SCM_MST_SSO_USER_INFO C
				  ,SCM_MST_SSO_DEPT_INFO D
			 WHERE A.DIVISION_ID = ''40''
			   AND A.MEASURE = ''MKT_FCST''
			   AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY( SYSDATE -7, ''MON''), ''YYYYMMDD'')
			   AND A.QTY > 0 
			   AND A.DIVISION_ID = B.DIVISION_ID
			   AND A.SCM_SITE_ID = B.SCM_SITE_ID
			   AND A.PROJECT_CODE = B.PROJECT_CODE
			   AND A.ITEM_ID = B.ITEM_ID
			   AND B.VALID_YN = ''Y''
			   AND B.OWNER = C.USER_ID
			   AND C.DEPT_ID = D.DEPT_ID
        ) FCST_RAW
	 LEFT OUTER JOIN DM_DNM_SALES_RESULT_IF SALES_RESULT
	 ON FCST_RAW.DIVISION_ID   = SALES_RESULT.DIVISION_ID
	 AND FCST_RAW.PROJECT_CODE = SALES_RESULT.PROJECT_CODE
	 AND FCST_RAW.SCM_SITE_ID  = SALES_RESULT.SALES_SITE_ID
	 AND FCST_RAW.ITEM_ID      = SALES_RESULT.ITEM_ID
             AND SALES_RESULT.sales_posting_date >= TO_CHAR(ADD_MONTHS(SYSDATE, -2), ''YYYYMMDD'')
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-10-29 17:03:34','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
