        STOCK.COMPANY_ID
       ,STOCK.DIVISION_ID
       ,STOCK.SCM_SITE_ID
       ,STOCK.PLANT_ID
       ,STOCK.FACTORY_ID
       ,FN_GET_ITEM_OPERATION_GROUP(STOCK.DIVISION_ID, STOCK.ITEM_ID) OPERATION_GROUP
       ,STOCK.ITEM_ID
       ,STOCK.STOCK_TYPE
       ,STOCK.STORAGE_ID
       ,MS.STORAGE_DESCRIPTION	
       ,STOCK.OPERATION_ID
       ,STOCK.MES_MAP_SLOC
       ,NVL(STOCK.SCM_QTY, 0) SCM_QTY
       ,STOCK.QTY2
       ,STOCK.MOVING_QTY
       ,STOCK.DEFECT_QTY
       ,STOCK.MODIFY_FP_APPLY_WIPQTY
       ,STOCK.FP_APPLY_WIPQTY
       ,STOCK.CAL_QTY
       ,STOCK.QTY_UOM
       ,NVL(STOCK.WIPHOLD_YN,''N'') WIPHOLD_YN
       ,NVL(STOCK.QMS_HOLD_YN,''N'') QMS_HOLD_YN
       ,NVL(STOCK.MES_HOLD_YN,''N'') MES_HOLD_YN      
       ,STOCK.WIP_TYPE_CODE
       ,STOCK.AVAILABLE_DATE
       ,STOCK.HOLDING_DATE
       ,STOCK.UNHOLD_EXP_DATE
       ,STOCK.MES_UNHOLD_DATE
       ,STOCK.QMS_HOLD_DATE
       ,STOCK.QMS_UNHOLD_EXP_DATE
       ,STOCK.QMS_UNHOLD_DATE
       ,STOCK.OUTSOURCING_FLAG
       ,STOCK.OUTSOURCING_FACTORY
FROM    SCM_DNM_STOCK STOCK 
LEFT JOIN   SCM_MST_SLOC MS
ON    STOCK.DIVISION_ID           = MS.DIVISION_ID	
AND   STOCK.PLANT_ID              = MS.PLANT_ID
AND   STOCK.STORAGE_ID            = MS.STORAGE_ID
WHERE STOCK.DIVISION_ID = :PARAM_DIVSION_ID
AND   STOCK.CUTOFF_DATE = :PARAM_CUTOFF_DATE
AND  (:PARAM_ITEM_ID = '''' OR STOCK.ITEM_ID LIKE :PARAM_ITEM_ID)
AND  (:PARAM_PLANT_ID = '''' OR STOCK.PLANT_ID = :PARAM_PLANT_ID)
AND  (:PARAM_OPERATION_GROUP = '''' OR FN_GET_ITEM_OPERATION_GROUP(STOCK.DIVISION_ID, STOCK.ITEM_ID) = :PARAM_OPERATION_GROUP)
AND  (:PARAM_STORAGE_ID LIKE '''' OR STOCK.STORAGE_ID LIKE :PARAM_STORAGE_ID)
AND  (:PARAM_STOCK_TYPE = '''' OR STOCK.STOCK_TYPE = :PARAM_STOCK_TYPE)

', 'Y', 'Y', 'blueeos', TO_DATE('2018-05-16 18:40:20','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (18, '-', 'Sales Result Query', 'ERP 매출실적 site_mapping 후 정보 조회', 'SELECT *
  FROM DM_DNM_SALES_RESULT A
WHERE A.DIVISION_ID = CASE WHEN :PARAM1 = '''' THEN A.DIVISION_ID ELSE :PARAM1 END
  AND A.SALES_SITE_ID = CASE WHEN :PARAM2 = '''' THEN A.SALES_SITE_ID ELSE :PARAM2 END
  AND A.PROJECT_CODE = CASE WHEN :PARAM3 = '''' THEN A.PROJECT_CODE ELSE :PARAM3 END
  AND A.ITEM_ID = CASE WHEN :PARAM4 = '''' THEN A.ITEM_ID ELSE :PARAM4 END
  AND A.MEASURE  = ''SALES_RESULT''
', 'N', 'Y', 'zytchoi', TO_DATE('2018-05-17 10:58:09','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:40','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (19, '-', 'Stock Check', 'Production Plan BOH 대비 재고 데이타 점검', 'SELECT /* TODO: add WHERE ROWNUM <= 10000 or FETCH FIRST 10000 ROWS ONLY */ PP.DIVISION_ID
       ,PP.OPERATION_GROUP
       ,PP.SCM_SITE_ID PLAN_SCM_SITE_ID
       ,PP.ITEM_ID
       ,PP.BOH
       ,PP.REQUIREMENT_QTY
       ,SV.SCM_SITE_ID STOCK_SCM_SITE_ID
       ,SV.STOCK_TYPE
       ,SV.STORAGE_ID
       ,MS.STORAGE_DESCRIPTION
       ,SV.OPERATION_ID
       ,SV.SCM_QTY
       ,SV.QTY2
       ,SV.MODIFY_FP_APPLY_WIPQTY
       ,SV.FP_APPLY_WIPQTY
       ,SV.CAL_QTY
FROM  (SELECT PP.DIVISION_ID
             ,PP.PLAN_START_YYYYMMDD
             ,PP.PLAN_TYPE
             ,PP.SEQ
             ,PP.OPERATION_GROUP
             ,PP.SCM_SITE_ID
             ,PP.ITEM_ID
             ,FN_GET_SCP_ANL_BOH_QTY(PP.DIVISION_ID, PP.PLAN_START_YYYYMMDD, PP.PLAN_TYPE, PP.SEQ, PP.SCM_SITE_ID, PP.ITEM_ID, :PARAM_PLAN_DATE) BOH
             ,SUM(QTY) REQUIREMENT_QTY
       FROM   SCP_ANL_PRODUCTION_PLAN PP      
       WHERE  PP.DIVISION_ID         = :PARAM_DIVISION_ID
       AND    PP.PLAN_START_YYYYMMDD = :PARAM_PLAN_DATE
       AND    PP.PLAN_TYPE           = :PARAM_PLAN_TYPE
       AND    PP.SEQ                 = :PARAM_PLAN_SEQ
       AND    PP.MEASURE             = ''REQUIREMENT''
       AND    PP.YYYYMMDD            >= :PARAM_PLAN_DATE
       AND    PP.YYYYMMDD            < CONVERT(CHAR(8), (:PARAM_PLAN_DATE) + (30), 112)
       GROUP BY PP.DIVISION_ID, PP.PLAN_START_YYYYMMDD, PP.PLAN_TYPE, PP.SEQ, PP.OPERATION_GROUP, PP.SCM_SITE_ID, PP.ITEM_ID) PP	
LEFT JOIN 
(SELECT SV.SCM_SITE_ID
      ,SV.COMPANY_ID
	  ,SV.DIVISION_ID
	  ,SV.PLANT_ID
	  ,SV.STORAGE_ID
	  ,SV.STOCK_TYPE
	  ,SV.ITEM_ID
	  ,SV.SCM_QTY
	  ,SV.OPERATION_ID
	  ,SV.QTY2
      ,SV.MODIFY_FP_APPLY_WIPQTY
      ,SV.FP_APPLY_WIPQTY
      ,SV.CAL_QTY
	  ,SV.CUTOFF_DATE
FROM   SCM_DNM_STOCK SV
WHERE  CUTOFF_DATE = :PARAM_STOCK_DATE
/*UNION
SELECT AV.SCM_SITE_ID
      ,AV.COMPANY_ID
	  ,AV.DIVISION_ID
	  ,AV.PLANT_ID
	  ,''-'' STORAGE_ID
	  ,''AGING'' STOCK_TYPE
	  ,AV.ITEM_ID
	  ,SUM(AV.QTY)
	  ,''-'' OPERATION_ID
	  ,0 QTY2
      ,0 MODIFY_FP_APPLY_WIPQTY
      ,0 FP_APPLY_WIPQTY
      ,0 CAL_QTY
	  ,AV.CUTOFF_DATE
FROM   SCM_DNM_STOCK_AGING_V AV
WHERE  CUTOFF_DATE = :PARAM_STOCK_DATE
AND   wiphold_yn = ''N''
--AND    AV.AVAILABLE_DATE <= :PARAM_STOCK_DATE
GROUP BY  AV.SCM_SITE_ID
      ,AV.COMPANY_ID
	  ,AV.DIVISION_ID
	  ,AV.PLANT_ID
	  ,AV.ITEM_ID
	  ,AV.CUTOFF_DATE*/) SV
ON    PP.DIVISION_ID           = SV.DIVISION_ID	
AND   PP.ITEM_ID               = SV.ITEM_ID
AND   (SUBSTR(PP.SCM_SITE_ID, 1, 4) = SV.PLANT_ID OR PP.SCM_SITE_ID = SV.SCM_SITE_ID)
LEFT JOIN   SCM_MST_SLOC MS
ON    SV.DIVISION_ID           = MS.DIVISION_ID	
AND   SV.PLANT_ID              = MS.PLANT_ID
AND   SV.STORAGE_ID            = MS.STORAGE_ID
WHERE (:PARAM_OPERATION_GROUP = '''' OR PP.OPERATION_GROUP = :PARAM_OPERATION_GROUP)
AND   (:PARAM_ITEM_ID = '''' OR PP.ITEM_ID = :PARAM_ITEM_ID)
ORDER BY pp.division_id, pp.operation_group, pp.scm_site_id, pp.item_id, sv.stock_type, sv.storage_id, sv.operation_id', 'Y', 'Y', 'wisdomena', TO_DATE('2018-05-17 17:42:56','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:02:37','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (20, '-', 'Stock - Aging', '활성화 재고', 'SELECT COMPANY_ID
      ,DIVISION_ID
	  ,SCM_SITE_ID
	  ,PLANT_ID
	  ,FACTORY_ID
	  ,ITEM_ID
      ,NICK_NAME
	  ,LOT_ID
	  ,LINE_ID
	  ,AVAILABLE_DATE
	  ,REMAIN_LEAD_TIME
	  ,WIPHOLD_YN
	  ,SPECIAL_YN
	  ,HOLDING_DATE
      ,UNHOLD_EXP_DATE
	  ,INPUT_QTY
	  ,QTY
	  ,QTY_UOM
FROM   SCM_DNM_STOCK_AGING_V
WHERE  CUTOFF_DATE = :PARAM_CUTOFF_DATE
AND        DIVISION_ID = :PARAM_DIVISION_ID
AND  (:PARAM_ITEM_ID = '''' OR ITEM_ID LIKE :PARAM_ITEM_ID)', 'Y', 'Y', 'blueeos', TO_DATE('2018-05-17 17:48:07','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:40','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (21, '-', 'Batch Job Monitoring', 'Batch Job Monitoring', 'SELECT -- TOP 10000
       program_name
      ,batch_type
      ,log_type
      ,log_count
      ,log_message
      ,description
      ,TO_CHAR(creation_date, ''YYYY-MM-DD HH24:MI:SS'') creation_date
      ,batch_period
FROM (SELECT md.segment1 program_name
            ,md.segment2 batch_type
            ,log_type
            ,log_count
            ,lb.log_message
            ,lb.description
            ,lb.creation_date
            ,md.description batch_period            
            ,1 display_order
      FROM   scm_adm_lookup_master_detail md
      LEFT JOIN   scm_sys_log_batch lb
      ON     lb.program_name = md.segment1
      AND    TO_CHAR(lb.creation_date, ''YYYYMMDD'') = FN_SCM_SYS_NVL(:PARAM_YYYYMMDD, TO_CHAR(SYSDATE, ''YYYYMMDD''))
      AND    (log_type= ''ERROR'' OR SUBSTR(log_type, 1, 3) = ''END'')
      WHERE  md.lookup_type = ''SCM_SYS_LOG_BATCH_ANL''
      AND    md.segment2 = ''RFC''
      AND    md.valid_yn = ''Y''
      UNION
      SELECT md.segment1 program_name
            ,md.segment2 batch_type
            ,log_type
            ,log_count
            ,lb.log_message
            ,lb.description
            ,lb.creation_date
            ,md.description batch_period
            ,2 display_order
      FROM   scm_adm_lookup_master_detail md
      LEFT JOIN   scm_sys_log_batch lb
      ON     lb.program_name = md.segment1
      AND    TO_CHAR(lb.creation_date, ''YYYYMMDD'') = FN_SCM_SYS_NVL(:PARAM_YYYYMMDD, TO_CHAR(SYSDATE, ''YYYYMMDD''))
      AND    log_type IN (''ERROR'', ''APPEND'')
      WHERE  md.lookup_type = ''SCM_SYS_LOG_BATCH_ANL''
      AND    md.segment2 = ''INF''
      AND    md.valid_yn = ''Y''
      UNION
      SELECT md.segment1 program_name
            ,md.segment2 batch_type
            ,log_type
            ,log_count
            ,lb.log_message
            ,lb.description
            ,lb.creation_date
            ,md.description batch_period
            ,3 display_order
      FROM   scm_adm_lookup_master_detail md
      LEFT JOIN   scm_sys_log_batch lb
      ON     lb.program_name = md.segment1
      AND    TO_CHAR(lb.creation_date, ''YYYYMMDD'') = FN_SCM_SYS_NVL(:PARAM_YYYYMMDD, TO_CHAR(SYSDATE, ''YYYYMMDD''))
      WHERE  md.lookup_type = ''SCM_SYS_LOG_BATCH_ANL''
      AND    md.segment2 = ''BAT''
      AND    md.valid_yn = ''Y'') A
WHERE (:PARAM_CHECK_NEEDED = '''' OR (:PARAM_CHECK_NEEDED = ''Y'' AND log_type = ''ERROR'' OR log_type IS NULL))
AND   (:PARAM_BATCH_TYPE = '''' OR :PARAM_BATCH_TYPE = batch_type)
AND   (:PARAM_PROGRAM_NAME = '''' OR :PARAM_PROGRAM_NAME = program_name)
--ORDER BY display_order, program_name, creation_date', 'Y', 'Y', 'wisdomena', TO_DATE('2018-05-22 15:37:07','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (25, '-', 'NO_BOM MKT_FCST', 'BOM 정보가 없는 MKT_FCST 정보', ' select distinct a.division_id, project_code, scm_site_id, a.item_id, fcst_type, a.incoterms, a.plant_site_id, c.item_type, a.measure, a.YYYYMMDD, lt_total, x.parent_item_id AS BOM_PARENT_ID,CONVERT(CHAR(8), DATEADD(DD, NVL(lt_total,0)+(7*10) , FN_NEXT_DAY(SYSDATE, ''MON'')), 112) as exfactory_fix_period
   from DM_PLN_MKT_FCST a
   inner join DM_MST_ITEM_SINGLE_V c
     on a.item_id = c.item_id
	 and a.division_id = c.DIVISION_ID
	 and c.item_type in ( ''P'',''H'' )
   left join SCM_MST_BOM_ENG_SN x
     on a.division_id = x.division_id
	 and a.item_id    = x.parent_item_id
   left join (
			select division_id, case when division_id = ''82'' then '''' else from_site end from_site , to_site, incoterms, min(lt_total) lt_total
			  from SCP_MST_BOD_V
			where priority = 1
			 group by division_id, case when division_id = ''82'' then '''' else from_site end , to_site, incoterms
             ) bod  
     on a.division_id    = bod.division_id
	 and a.PLANT_SITE_ID = bod.from_site
	 and a.SCM_SITE_ID   = bod.to_site
	 and a.INCOTERMS     = bod.incoterms
  where 1=1
     and a.MEASURE in ( ''MKT_FCST'',''VMI_In_Req'',''RTF'' )
	AND a.YYYYMMDD >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7*1), 112)   -- 당주 월요일부터
	AND a.YYYYMMDD < CONVERT(CHAR(8), DATEADD(DD, NVL(lt_total,0)+(7*10) , FN_NEXT_DAY(SYSDATE, ''MON'')), 112)   -- 당주 월요일 + 11주 까지
	and a.qty > 0
 	and x.parent_item_id is null
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-06-12 18:16:47','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (26, '-', 'SITE_SHIPTO_없는_MKTFCST조회', 'SITE_SHIPTO_없는_MKTFCST조회', ' select distinct a.division_id, project_code, a.scm_site_id, a.item_id, fcst_type, a.incoterms, a.plant_site_id, a.YYYYMMDD,  lt_total, x.SHIPTO_CODE as rep_shipto_code ,CONVERT(CHAR(8), DATEADD(DD, NVL(lt_total,0)+(7*4) , FN_NEXT_DAY(SYSDATE, ''MON'')), 112) as exfactory_fix_period
   from DM_PLN_MKT_FCST a
   inner join scm_mst_site s
   on a.division_id = s.division_id
   and a.scm_site_id = s.scm_site_id
   and s.valid_yn = ''Y''
   left join SCM_MST_SITE_CUSTOMER x
     on a.division_id = x.division_id
	 and a.scm_site_id    = x.scm_site_id
	 and x.valid_yn = ''Y''
	 and x.rep_yn = ''Y''
   left join (
			select division_id, case when division_id = ''82'' then '''' else from_site end from_site , to_site, incoterms, min(lt_total) lt_total
			  from SCP_MST_BOD_V
			 where priority = 1
			 group by division_id, case when division_id = ''82'' then '''' else from_site end , to_site, incoterms
             ) bod  
     on a.division_id    = bod.division_id
	 and a.PLANT_SITE_ID = bod.from_site
	 and a.SCM_SITE_ID   = bod.to_site
	 and a.INCOTERMS     = bod.incoterms
  where a.MEASURE = ''MKT_FCST''
	AND a.YYYYMMDD >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7*1), 112)   -- 당주 월요일부터
	AND a.YYYYMMDD < CONVERT(CHAR(8), DATEADD(DD, NVL(lt_total,0)+(7*3) , FN_NEXT_DAY(SYSDATE, ''MON'')), 112)   -- BOD LT + 4W
	and a.qty > 0
 	and x.SHIPTO_CODE is null
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-06-27 11:37:19','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (57, '-', 'FP Version', 'SCP Plan 사용 FP Version', 'SELECT DIVISION_ID
      ,PLAN_NAME
      ,PLAN_TYPE
      ,PLAN_SEQ
      ,COMPANY_ID
      ,SITE_ID
      ,PLANT_ID
      ,INSTANCE_ID
      ,INSTANCE_TYPE
      ,INSTANCE_DATE
      ,RELEASE_PLAN_ID
      ,FACTORY_ID
      ,PLAN_GROUP_ID
     , CREATION_DATE AS SCP_CREATION_DATE
FROM   SCM_MST_PLAN_FP_RELEASE_ID
WHERE  DIVISION_ID = :PARAM_DIVISION_ID
AND    PLAN_NAME   = :PARAM_PLAN_DATE
AND  (:PARAM_PLAN_TYPE = '''' OR PLAN_TYPE = :PARAM_PLAN_TYPE)
AND  (:PARAM_PLAN_SEQ  = '''' OR PLAN_SEQ  = :PARAM_PLAN_SEQ)
', 'Y', 'Y', 'blueeos', TO_DATE('2019-07-09 11:47:34','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:41','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (58, '-', 'SCP MASTER 수정이력', 'SCP MASTER 수정이력', 'SELECT ''PROJECT ROUTE'' AS MASTER_INFO
		, DIVISION_ID
		, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') AS UPDATE_DATE
		, (SELECT USERNAME FROM TB_FX_USER WHERE USERID=LAST_UPDATED_BY)+''('' || LAST_UPDATED_BY || '')'' AS USER_ID
		, COUNT(DIVISION_ID) AS COUNT
FROM SCM_MST_SITE_ITEM_PRIORITY_H
WHERE (:PARAM_DIVISION_ID = '''' OR :PARAM_DIVISION_ID IS NULL OR DIVISION_ID = :PARAM_DIVISION_ID)
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') >= :PARAM_START_YYYYMMDD
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') <= :PARAM_END_YYYYMMDD
AND (:PARAM_USER_ID = '''' OR :PARAM_USER_ID IS NULL OR LAST_UPDATED_BY = :PARAM_USER_ID)
AND (:PARAM_MASTER_TYPE = '''' OR :PARAM_MASTER_TYPE IS NULL OR ''PROJECT ROUTE'' = :PARAM_MASTER_TYPE)
GROUP BY DIVISION_ID, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD''), LAST_UPDATED_BY
UNION 
SELECT ''TACT TIME'' AS MASTER_INFO
		, DIVISION_ID
		, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') AS UPDATE_DATE
		, (SELECT USERNAME FROM TB_FX_USER WHERE USERID=LAST_UPDATED_BY)+''('' || LAST_UPDATED_BY || '')'' AS USER_ID
		, COUNT(DIVISION_ID) AS COUNT
FROM SCP_MST_TACT_TIME_H
WHERE (:PARAM_DIVISION_ID = '''' OR :PARAM_DIVISION_ID IS NULL OR DIVISION_ID = :PARAM_DIVISION_ID)
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') >= :PARAM_START_YYYYMMDD
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') <= :PARAM_END_YYYYMMDD
AND (:PARAM_USER_ID = '''' OR :PARAM_USER_ID IS NULL OR LAST_UPDATED_BY = :PARAM_USER_ID)
AND (:PARAM_MASTER_TYPE = '''' OR :PARAM_MASTER_TYPE IS NULL OR ''TACT TIME'' = :PARAM_MASTER_TYPE)
GROUP BY DIVISION_ID, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD''), LAST_UPDATED_BY
UNION
SELECT ''TACT TIME'' AS MASTER_INFO
		, DIVISION_ID
		, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') AS UPDATE_DATE
		, (SELECT USERNAME FROM TB_FX_USER WHERE USERID=LAST_UPDATED_BY)+''('' || LAST_UPDATED_BY || '')'' AS USER_ID
		, COUNT(DIVISION_ID) AS COUNT
FROM SCP_MST_TACT_TIME_EXCEPT_H
WHERE (:PARAM_DIVISION_ID = '''' OR :PARAM_DIVISION_ID IS NULL OR DIVISION_ID = :PARAM_DIVISION_ID)
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') >= :PARAM_START_YYYYMMDD
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') <= :PARAM_END_YYYYMMDD
AND (:PARAM_USER_ID = '''' OR :PARAM_USER_ID IS NULL OR LAST_UPDATED_BY = :PARAM_USER_ID)
AND (:PARAM_MASTER_TYPE = '''' OR :PARAM_MASTER_TYPE IS NULL OR ''TACT TIME'' = :PARAM_MASTER_TYPE)
GROUP BY DIVISION_ID, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD''), LAST_UPDATED_BY
UNION
SELECT ''MODEL ALLOCATION'' AS MASTER_INFO
		, DIVISION_ID
		, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') AS UPDATE_DATE
		, (SELECT USERNAME FROM TB_FX_USER WHERE USERID=LAST_UPDATED_BY)+''('' || LAST_UPDATED_BY || '')'' AS USER_ID
		, COUNT(DIVISION_ID) AS COUNT
FROM SCP_MST_MODEL_ALLOCATION_H
WHERE (:PARAM_DIVISION_ID = '''' OR :PARAM_DIVISION_ID IS NULL OR DIVISION_ID = :PARAM_DIVISION_ID)
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') >= :PARAM_START_YYYYMMDD
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') <= :PARAM_END_YYYYMMDD
AND (:PARAM_USER_ID = '''' OR :PARAM_USER_ID IS NULL OR LAST_UPDATED_BY = :PARAM_USER_ID)
AND (:PARAM_MASTER_TYPE = '''' OR :PARAM_MASTER_TYPE IS NULL OR ''MODEL ALLOCATION'' = :PARAM_MASTER_TYPE)
GROUP BY DIVISION_ID, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD''), LAST_UPDATED_BY
UNION
SELECT ''BOD ITEM'' AS MASTER_INFO
		, DIVISION_ID
		, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') AS UPDATE_DATE
		, (SELECT USERNAME FROM TB_FX_USER WHERE USERID=LAST_UPDATED_BY)+''('' || LAST_UPDATED_BY || '')'' AS USER_ID
		, COUNT(DIVISION_ID) AS COUNT
FROM SCP_MST_BOD_ITEM_H
WHERE (:PARAM_DIVISION_ID = '''' OR :PARAM_DIVISION_ID IS NULL OR DIVISION_ID = :PARAM_DIVISION_ID)
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') >= :PARAM_START_YYYYMMDD
AND TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') <= :PARAM_END_YYYYMMDD
AND (:PARAM_USER_ID = '''' OR :PARAM_USER_ID IS NULL OR LAST_UPDATED_BY = :PARAM_USER_ID)
AND (:PARAM_MASTER_TYPE = '''' OR :PARAM_MASTER_TYPE IS NULL OR ''BOD ITEM'' = :PARAM_MASTER_TYPE)
GROUP BY DIVISION_ID, TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD''), LAST_UPDATED_BY', 'Y', 'Y', 'hwwoonins', TO_DATE('2019-10-22 13:28:44','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (59, '-', 'EDI LeadTime 수정이력 조회', 'EDI LeadTime 수정이력 조회', '/*
################### 입력샘플 필독! ###################
1. PROJECT                  : = ''A15AI7001''               OR  (공백일경우 모든 PROJECT 검색)
2. SITE                         : = ''Audi CKD_DE_ING''     OR  (공백일경우 모든 SITE 검색)
3. ITEM                        : = ''APAAGIHEV-A2''  OR  (공백일경우 모든 ITEM 검색)
4. 값을 입력한날짜(시작) : = ''20191201''                  OR  (공백일경우 과거 8주 검색)
5. 값을 입력한날짜(끝)    : = ''20191231''                 OR  (공백일경우 금일까지 검색)
*/

SELECT DIVISION_ID,HISTORY_SEQ,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY
		,(CASE WHEN LAST_UPDATED_BY LIKE ''EDI_INTERFACE%'' THEN ''EDI_BATCH_SYSTEM'' ELSE LAST_UPDATED_BY END) AS ''MODIFY_ID''
		,ATTRIBUTE7 AS ''Call_Off_DATE''
		,ATTRIBUTE8 AS ''LeadTime''
		,ATTRIBUTE6 AS ''IFSEQ_NO''
		,(SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ B.USER_NAME FROM SCM_MST_SSO_USER_INFO B WHERE A.LAST_UPDATED_BY = B.USER_ID) AS MODIFY_USER_NAME
		,TO_CHAR(LAST_UPDATE_DATE, ''YYYY-MM-DD HH24:MI:SS'')  AS ''MODIFY_DATE''

	FROM DM_PLN_MKT_FCST_H A	WHERE 1=1
		AND A.DIVISION_ID IN (''40'',''81'')
		AND A.PROJECT_CODE = ( CASE WHEN :PARAM_PROJECT_CODE = '''' THEN A.PROJECT_CODE ELSE :PARAM_PROJECT_CODE END)
		AND A.SCM_SITE_ID = ( CASE WHEN :PARAM_SCM_SITE_ID = '''' THEN A.SCM_SITE_ID ELSE :PARAM_SCM_SITE_ID END)
		AND A.ITEM_ID = ( CASE WHEN :PARAM_ITEM_ID = '''' THEN A.ITEM_ID ELSE :PARAM_ITEM_ID END)
		/* 날짜조건이 N/A일경우 지난주 월요일부터 데이터만 조회 */
		AND TO_CHAR(A.LAST_UPDATE_DATE, ''YYYYMMDD'')	>=	
		( CASE WHEN :PARAM_FROM_DATE = ''''	THEN TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7*8), 112)	
		ELSE TO_CHAR(:PARAM_FROM_DATE, ''YYYYMMDD'') END ) 
		/* 날짜조건이 N/A일경우 오늘까지의 데이터만 조회 */
		AND TO_CHAR(A.LAST_UPDATE_DATE, ''YYYYMMDD'')	<=	
		( CASE WHEN :PARAM_TO_DATE = '''' THEN TO_CHAR(SYSDATE, ''YYYYMMDD'') ELSE TO_CHAR(:PARAM_TO_DATE, ''YYYYMMDD'') END)
		AND MEASURE IN (''IMMIDIATE'',''PLANNING_FORECAST'',''COMMERCIAL_AGREEMENT'')
', 'Y', 'Y', 'songkeeho', TO_DATE('2019-12-10 12:39:22','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:02:37','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (60, '-', '조립생산계획 라인 대비 전극 ALLOCATION 없는 모델 산출', '조립생산계획 라인 대비 전극 ALLOCATION 없는 모델 산출', 'SELECT PLN.SCM_SITE_ID
      ,PLN.ITEM_ID
      ,PLN.LINE_ID
      ,F.NICK_NAME
FROM SCP_ANL_PRODUCTION_PLAN PLN

LEFT JOIN SCP_MST_FINAL_ITEM F
ON  PLN.ITEM_ID = F.ITEM_ID

LEFT JOIN SCP_MST_MODEL_ALLOCATION ALLO
ON  ALLO.CELL_PLANT_SITE_ID=PLN.SCM_SITE_ID
AND ALLO.CELL_ITEM_ID=PLN.ITEM_ID
AND ALLO.CELL_LINE_ID=PLN.LINE_ID

WHERE 1 = 1
AND NOT(PLN.DIVISION_ID = ''EE'') 
AND PLN.PLAN_START_YYYYMMDD = :PARAM_START_YYYYMMDD
AND PLN.PLAN_TYPE = :PARAM_PLAN_TYPE
AND PLN.OPERATION_GROUP = ''A''
AND PLN.OPERATION_ID IN (''A3000'',''A9000'')
AND PLN.MEASURE = ''PROD_PLAN_AMEND''
AND PLN.QTY < > 0 -- 기본 값
AND ALLO.CELL_PLANT_SITE_ID IS NULL

GROUP BY PLN.SCM_SITE_ID, PLN.ITEM_ID, PLN.LINE_ID, F.NICK_NAME

', 'Y', 'Y', 'hwwoonins', TO_DATE('2020-01-20 17:52:20','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (22, '-', '출하실적', '출하실적 조회', 'SELECT COMPANY_ID
            ,DIVISION_ID
	,PLANT_ID	
	,ITEM_ID
            ,CASE EXFACTORY_STATUS WHEN ''D10'' THEN "생성"
	                                           WHEN ''D20'' THEN "공장출고"
				       WHEN ''D30'' THEN "운송중"
				       WHEN ''D40'' THEN "매출"
				       WHEN ''D90'' THEN "삭제"
				       END STATUS
	,PROJECT_CODE
            ,TRANSPORT_MODE_ERP	
	,TRANSPORT_MODE	
	,INCOTERMS	
	,FROM_SCM_SITE_ID	
	,TO_SCM_SITE_ID
	,PLANT_ISSUE_DATE
	,ORDER_QTY	
	,EXFACTORY_QTY	
	,UOM	
	,ORDER_CREATE_DATE		
	,ON_BOARD_DATE	
	,ACTUAL_EXFACTORY_DATE	
	,SYSTEM_EXFACTORY_DATE	
	,DELIVERY_POSTING_DATE	
	,EXFACTORY_DATE AS GSCP_EXFACTORY_DATE
	,ORDER_NO	
	,ORDER_ITEM_SEQ	
	,ORDER_TYPE_NAME	
	,DELIVERY_NO	
	,DELIVERY_ITEM_SEQ	
	,SOLDTO_CODE	
	,SHIPTO_CODE
FROM SCM_DNM_EXFACTORY_RESULT
WHERE DIVISION_ID = :PARAM_DIVISION_ID
AND   EXFACTORY_DATE >= FN_SCM_SYS_NVL(:PARAM_EXFACTORY_DATE_FROM, CONVERT(CHAR(8), (SYSDATE) + (-1), 112))
AND   EXFACTORY_DATE <= FN_SCM_SYS_NVL(:PARAM_EXFACTORY_DATE_TO, CONVERT(CHAR(8), (SYSDATE) + (-1), 112))
AND   (:PARAM_ITEM_ID = '''' OR ITEM_ID LIKE :PARAM_ITEM_ID)
AND   NVL(EXFACTORY_STATUS,''D90'') NOT IN (''D90'' ,''D10'') -- D90: DO삭제 , D10:DO생성 
AND  STORAGE_ID NOT IN (''6000'' ,''799A'') --상품창고제외 
AND   STORAGE_ID NOT IN (SELECT SEGMENT1 
			     FROM SCM_ADM_LOOKUP_MASTER_DETAIL 
			     WHERE LOOKUP_TYPE = ''SSP_SHIP_RESULT_EXCEPT_STORAGE''
			     AND VALID_YN = ''Y''
			     ) -- 사외 창고 제외 LOOKUP 관리', 'Y', 'Y', 'wisdomena', TO_DATE('2018-05-29 12:02:14','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:08:17','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (23, '-', 'Production Result', '생산실적 (외주 Packer 포함)', 'SELECT v.company_id
      ,v.plant_id
      ,v.scm_site_id
      ,v.item_id
      ,v.scp_operation_group
      ,v.operation_id
      ,v.line_id
      ,v.plan_date
      ,v.actual_qty
      ,v.actual_good_qty
      ,v.actual_scrap_qty
FROM   scm_dnm_product_result_v v
WHERE  v.division_id = :PARAM_DIVISION_ID
AND    (:PARAM_OPERATION_GROUP = '''' OR v.scp_operation_group = :PARAM_OPERATION_GROUP)
AND    (:PARAM_ITEM_ID = '''' OR v.item_id = :PARAM_ITEM_ID)
AND    V.PLAN_DATE >= FN_SCM_SYS_NVL(:PARAM_FROM_DATE, CONVERT(CHAR(8), (SYSDATE) + (-1), 112))
AND    V.PLAN_DATE <= FN_SCM_SYS_NVL(:PARAM_TO_DATE, CONVERT(CHAR(8), (SYSDATE) + (-1), 112))
', 'Y', 'Y', 'wisdomena', TO_DATE('2018-05-29 12:16:14','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (24, '-', 'FP확정 생산계획', 'FP확정 생산계획 조회', 'SELECT 
       scm_site_id
      ,company_id
      ,division_id
      ,site_id
      ,plant_id
      ,factory_id
      ,operation_id
      ,location
      ,top_item_id
      ,item_id
      ,fp_production_type
      ,market
      ,line_id
      ,electrode_type
      ,plan_date
      ,plan_qty
      ,plan_in_qty
      ,equipment_id
FROM SCM_DNM_PLAN_FROZEN_V
WHERE DIVISION_ID = :PARAM_DIVISION_ID
AND   PLAN_DATE >= :PARAM_FROM_PLAN_DATE
AND   PLAN_DATE <= :PARAM_TO_PLAN_DATE
AND   (:PARAM_ITEM_ID = '''' OR ITEM_ID = :PARAM_ITEM_ID)', 'Y', 'Y', 'fpqrhvk', TO_DATE('2018-06-05 10:58:17','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:40','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (44, '-', '소형 1개 이상의 SOLDTO가 연결된 Sales SITE', '소형 1개 이상의 SOLDTO가 연결된 Sales SITE', '
select b.division_id, b.scm_site_id, count(distinct soldto_code) SOLDTO_COUNT
      ,(
	        select distinct (SELECT LISTAGG(DISTINCT cu.soldto_code || '' : '' || cu.SOLDTO_DESCRIPTION, '','') WITHIN GROUP (ORDER BY cu.soldto_code || '' : '' || cu.SOLDTO_DESCRIPTION) from scm_mst_customer cu
									      ,scm_mst_site_customer sc
									 where cu.division_id = sc.division_id
									   and cu.soldto_code = sc.soldto_code
									   and sc.scm_site_id = b.scm_site_id
									   and sc.division_id = b.division_id) 
	   ) SOLD_TO 
      ,(
					 SELECT distinct  (SELECT LISTAGG(DISTINCT z.dept_name_ko, '','') WITHIN GROUP (ORDER BY z.dept_name_ko) from scm_mst_site_item x
												  ,SCM_MST_SSO_USER_INFO y
												  ,SCM_MST_SSO_DEPT_INFO z
											 where x.division_id = b.division_id
											   and x.scm_site_id = b.scm_site_id
											   and x.owner = y.user_id
											   and y.dept_id = z.dept_id 
											   and x.valid_yn = ''Y'') 
	   ) TEAM
      ,(
					 SELECT distinct  (SELECT LISTAGG(DISTINCT y.user_name || '''' || y.job_name, '','') WITHIN GROUP (ORDER BY y.user_name || '''' || y.job_name) from scm_mst_site_item x
												  ,SCM_MST_SSO_USER_INFO y
												  ,SCM_MST_SSO_DEPT_INFO z
											 where x.division_id = b.division_id
											   and x.scm_site_id = b.scm_site_id
											   and x.owner = y.user_id
											   and y.dept_id = z.dept_id 
											   and x.valid_yn = ''Y'') 
	   ) OWNER
  from scm_mst_site_customer a
      ,scm_mst_site b
 where a.division_id = b.division_id
   and a.scm_site_id = b.scm_site_id
   and a.valid_yn = ''Y''
   and b.site_type = ''SALES''
   and a.division_id = ''40''
group by b.division_id, b.scm_site_id
having count(distinct soldto_code) > 1
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-11-07 09:14:31','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:23:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (45, '-', 'MDF 실적', 'MDF 실적', '/****** Script for SelectTopNRows command from SSMS  ******/
SELECT DIVISION_ID
      ,COMPANY_ID
      ,BIZ_AREA
      ,GL_ACCOUNT_CODE
      ,PROFIT_CENTER
      ,SALES_WORK_PLACE
      ,DEBIT_CREDIT_INDICATOR
      ,WBS_TYPE
      ,ITEM_TEXT
      ,CURRENCY
      ,AMOUNT
      ,LOCAL_AMOUNT
      ,DOCUMENT_TYPE
      ,ACCOUNTING_DOC_NO
      ,SYSTEM_INPUT_DATE
      ,SALES_POSTING_DATE
      ,DESIGNATED_NUMBER
      ,VAT_CODE
      ,COST_CENTER
      ,YYYYMM
      ,ACCOUNT_TYPE
      ,PAY_BACK_DOC_NO
      ,PAY_BACK_DATE
      ,REFERENCE_KEY
      ,CUSTOMER_CODE
      ,CUSTOMER_NAME
  FROM LGCE_SCMPROD.DM_PLN_MDF_RESULT
 where division_id = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN division_id ELSE :PARAM_DIVSION_ID END )
   and SUBSTR(SALES_POSTING_DATE,1,7) = ( CASE WHEN :PARAM_sales_yyyymm = '''' THEN SUBSTR(SALES_POSTING_DATE,1,7) ELSE :PARAM_sales_yyyymm END )


', 'Y', 'Y', 'zytchoi', TO_DATE('2018-11-19 13:28:22','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (46, '-', '매출 주마감 여부 확인 DQ', '매출 주마감 여부 확인 DQ', '                
SELECT DIVISION_ID, TEAM,	END_CUSTOMER, SALES_SITE_ID
     ,  ZZ.CUSTOMER_CODE, ZZ.CUSTOMER_NAME
     ,  ROUND( ( SUM(CASE WHEN DAY_DIFF = 0 THEN 1 ELSE 0 END) ) / CAST(COUNT(1) AS NUMBER) ,2) * 100 "당일마감"
     ,  ROUND( ( SUM(CASE WHEN WEEK_DIFF = 0 THEN 1 ELSE 0 END) ) / CAST(COUNT(1) AS NUMBER) ,2) * 100 "당주마감"
	 ,  ROUND( ( SUM(CASE WHEN WEEK_DIFF = 1 THEN 1 ELSE 0 END) ) / CAST(COUNT(1) AS NUMBER) ,2) * 100 "W_1마감"
	 ,  ROUND( ( SUM(CASE WHEN WEEK_DIFF = 2 THEN 1 ELSE 0 END) ) / CAST(COUNT(1) AS NUMBER) ,2) * 100 "W_2마감"
	 ,  ROUND( ( SUM(CASE WHEN WEEK_DIFF >= 3 THEN 1 ELSE 0 END) ) / CAST(COUNT(1) AS NUMBER) ,2) * 100 "W_3이후마감"
	-- , COUNT(1)
FROM (
		SELECT DIVISION_ID
		     , CASE WHEN DIVISION_ID = ''40'' THEN NVL((
				 SELECT W.DEPT_NAME_KO
				   FROM SCM_MST_SITE_ITEM A
				       ,SCM_MST_SSO_DEPT_INFO W
					   ,SCM_MST_SSO_USER_INFO SU
				  WHERE A.DIVISION_ID = ''40''      
					AND A.PROJECT_CODE = X.PROJECT_CODE
					AND A.SCM_SITE_ID = X.SALES_SITE_ID
					AND A.ITEM_ID = X.ITEM_ID  
					AND W.DEPT_ID = SU.DEPT_ID     
					AND SU.USER_ID = (SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT(A.OWNER, '',''))
			  ), ''(팀정보미존재건 ERP NAME) '' || SALES_WORK_PLACE_NAME) 

                               ELSE ( SELECT W.DEPT_NAME_KO FROM SCM_MST_SITE S, LGCE_SCMPROD.SCM_MST_SSO_DEPT_INFO W WHERE S.DIVISION_ID = X.DIVISION_ID AND S.SCM_SITE_ID = X.SALES_SITE_ID AND S.DEPT_ID = W.DEPT_ID) END TEAM
		     ,SALES_SITE_ID
		   --  , NVL((
					--SELECT L.ATTRIBUTE1
					--
FROM LGCE_SCMPROD.SCM_ADM_LOOKUP_MASTER_DETAIL L
					--
WHERE L.LOOKUP_TYPE = ''MTRL_GRP3_MAPPING''
					--   AND L.SEGMENT1 = X.DIVISION_ID
					--   AND L.SEGMENT2 = X.COMPANY_ID
					--   AND L.SEGMENT3 = X.MAT_GROUP
			  -- ), MAT_GROUP_DESC) END_CUSTOMER
			, CASE WHEN DIVISION_ID = ''40'' THEN PROJECT_CODE ELSE  ( SELECT S.END_CUSTOMER  FROM SCM_MST_SITE S WHERE S.DIVISION_ID = X.DIVISION_ID AND S.SCM_SITE_ID = X.SALES_SITE_ID) END END_CUSTOMER
		     ,  SALES_POSTING_DATE
			 ,	SYSTEM_INPUT_DATE
			 , X.CUSTOMER_CODE
			 , (
				SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ C.SOLDTO_DESCRIPTION
				  FROM SCM_MST_CUSTOMER C
				 WHERE C.DIVISION_ID = X.DIVISION_ID
				   AND C.SOLDTO_CODE = X.CUSTOMER_CODE
			   ) CUSTOMER_NAME
			 , /*DATEDIFF_NEEDS_UNIT_SPECIFIC_CALC*/DATEDIFF(WEEK,(CAST(SALES_POSTING_DATE AS DATETIME)) + (-1), (CAST(SYSTEM_INPUT_DATE AS DATETIME)) + (-1)) WEEK_DIFF
			 , /*DATEDIFF_NEEDS_UNIT_SPECIFIC_CALC*/DATEDIFF(DAY,(CAST(SALES_POSTING_DATE AS DATETIME)) + (-1), (CAST(SYSTEM_INPUT_DATE AS DATETIME)) + (-1)) DAY_DIFF
		  FROM LGCE_SCMPROD.DM_DNM_SALES_RESULT_IF X
		 WHERE COST_ITEM = ''''
		   AND SALES_QTY <> 0
		--   AND MAT_GROUP_DESC IS NOT NULL
           AND SALES_POSTING_DATE BETWEEN ''20181101''   AND ''20181129'' 
		   AND DIVISION_ID = ( CASE WHEN ''''  = '''' THEN DIVISION_ID ELSE ''''  END )
		   AND LENGTH(X.CUSTOMER_CODE) > 4 -- 법인간 거래 제외
	  ) ZZ
WHERE ZZ.SALES_SITE_ID IS NOT NULL
GROUP BY  DIVISION_ID, TEAM,	END_CUSTOMER, SALES_SITE_ID,  ZZ.CUSTOMER_CODE, ZZ.CUSTOMER_NAME
                ', 'Y', 'Y', 'songkeeho', TO_DATE('2018-11-21 14:26:19','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:23:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (47, '-', '(임시)1개 이상의 SOLDTO가 연결된 Sales SITE', '(임시)1개 이상의 SOLDTO가 연결된 Sales SITE', 'SELECT B.DIVISION_ID, B.SCM_SITE_ID, COUNT(DISTINCT SOLDTO_CODE) SOLDTO_COUNT
      ,(
	        SELECT DISTINCT (SELECT LISTAGG(DISTINCT CU.SOLDTO_CODE || '' : '' || CU.SOLDTO_DESCRIPTION, '','') WITHIN GROUP (ORDER BY CU.SOLDTO_CODE || '' : '' || CU.SOLDTO_DESCRIPTION) FROM SCM_MST_CUSTOMER CU
									      ,SCM_MST_SITE_CUSTOMER SC
									 WHERE CU.DIVISION_ID = SC.DIVISION_ID
									   AND CU.SOLDTO_CODE = SC.SOLDTO_CODE
									   AND SC.SCM_SITE_ID = B.SCM_SITE_ID
									   AND SC.DIVISION_ID = B.DIVISION_ID) 
	   ) SOLD_TO 
      ,
	  (
					 SELECT DISTINCT  (SELECT LISTAGG(DISTINCT Z.DEPT_NAME_KO, '','') WITHIN GROUP (ORDER BY Z.DEPT_NAME_KO) FROM SCM_MST_SITE_ITEM X
												  ,SCM_MST_SSO_USER_INFO Y
												  ,SCM_MST_SSO_DEPT_INFO Z
												  ,SCM_MST_SITE ST
											 WHERE X.DIVISION_ID = B.DIVISION_ID
											   AND X.DIVISION_ID = ST.DIVISION_ID
											   AND X.SCM_SITE_ID = B.SCM_SITE_ID
											   AND X.SCM_SITE_ID = ST.SCM_SITE_ID
											   AND X.OWNER = Y.USER_ID
											   --AND Y.DEPT_ID = Z.DEPT_ID --SKH
											   AND CASE WHEN X.DIVISION_ID = ''40'' THEN Y.DEPT_ID ELSE ST.DEPT_ID END
											     = Z.DEPT_ID
											   AND X.VALID_YN = ''Y'') 
	   ) TEAM
      ,(
					 SELECT DISTINCT  (SELECT LISTAGG(DISTINCT Y.USER_NAME || '''' || Y.JOB_NAME, '','') WITHIN GROUP (ORDER BY Y.USER_NAME || '''' || Y.JOB_NAME) FROM SCM_MST_SITE_ITEM X
												  ,SCM_MST_SSO_USER_INFO Y
												  ,SCM_MST_SSO_DEPT_INFO Z
												  ,SCM_MST_SITE ST
											 WHERE X.DIVISION_ID = B.DIVISION_ID
											   AND X.DIVISION_ID = ST.DIVISION_ID
											   AND X.SCM_SITE_ID = B.SCM_SITE_ID
											   AND X.SCM_SITE_ID = ST.SCM_SITE_ID
											   AND X.OWNER = Y.USER_ID
											   AND CASE WHEN X.DIVISION_ID = ''40'' THEN Y.DEPT_ID ELSE ST.DEPT_ID END
											     = Z.DEPT_ID
											   AND X.VALID_YN = ''Y'') 
	   ) OWNER
  FROM SCM_MST_SITE_CUSTOMER A
      ,SCM_MST_SITE B
 WHERE A.DIVISION_ID = B.DIVISION_ID
   AND A.SCM_SITE_ID = B.SCM_SITE_ID
   AND A.VALID_YN = ''Y''
   AND B.SITE_TYPE = ''SALES''
   AND A.DIVISION_ID = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN A.DIVISION_ID ELSE :PARAM_DIVSION_ID END )
GROUP BY B.DIVISION_ID, B.SCM_SITE_ID
HAVING COUNT(DISTINCT SOLDTO_CODE) > 1
', 'Y', 'Y', 'songkeeho', TO_DATE('2018-11-27 15:51:13','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:23:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (48, '-', '(임시)Incoterms 계획/실적 비교', '(임시)Incoterms 계획/실적 비교', 'SELECT DISTINCT FCST_RAW.*, SALES_RESULT.INCOTERMS RESULT_INCOTERMS, CASE WHEN FCST_RAW.INCOTERMS = SALES_RESULT.INCOTERMS THEN '''' ELSE ''DIFF'' END DIFF
  FROM (
			SELECT DISTINCT A.DIVISION_ID, D.DEPT_NAME_KO, B.OWNER, C.USER_NAME, C.JOB_NAME, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.INCOTERMS
			  FROM DM_PLN_MKT_FCST A
				  ,SCM_MST_SITE_ITEM B
				  ,SCM_MST_SSO_USER_INFO C
				  ,SCM_MST_SSO_DEPT_INFO D
				,SCM_MST_SITE ST
			 WHERE A.DIVISION_ID = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN A.DIVISION_ID ELSE :PARAM_DIVSION_ID END )
			   AND A.MEASURE = ''MKT_FCST''
			   AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY( SYSDATE -7, ''MON''), ''YYYYMMDD'')
			   AND A.QTY > 0 
			   AND A.DIVISION_ID = B.DIVISION_ID
			   AND A.SCM_SITE_ID = B.SCM_SITE_ID
			   AND A.PROJECT_CODE = B.PROJECT_CODE
			   AND A.ITEM_ID = B.ITEM_ID
			   AND B.VALID_YN = ''Y''
			   AND B.OWNER = C.USER_ID
				AND A.DIVISION_ID = ST.DIVISION_ID
				AND A.SCM_SITE_ID = ST.SCM_SITE_ID
			   AND CASE WHEN A.DIVISION_ID = ''40'' THEN C.DEPT_ID ELSE ST.DEPT_ID END
											     = D.DEPT_ID
        ) FCST_RAW
	 LEFT OUTER JOIN DM_DNM_SALES_RESULT_IF SALES_RESULT
	 ON FCST_RAW.DIVISION_ID   = SALES_RESULT.DIVISION_ID
	 AND FCST_RAW.PROJECT_CODE = SALES_RESULT.PROJECT_CODE
	 AND FCST_RAW.SCM_SITE_ID  = SALES_RESULT.SALES_SITE_ID
	 AND FCST_RAW.ITEM_ID      = SALES_RESULT.ITEM_ID
             AND SALES_RESULT.SALES_POSTING_DATE >= TO_CHAR(ADD_MONTHS(SYSDATE, -2), ''YYYYMMDD'')
', 'Y', 'Y', 'songkeeho', TO_DATE('2018-11-27 16:17:44','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (50, '-', 'EDI 정보 인터페이스 오류건', 'EDI 정보 인터페이스 오류건', TO_CLOB('/*
################### 입력샘플 필독! ###################
1. PROJECT                  : = ''A15AI7001''               OR  (공백일경우 모든 PROJECT 검색)
2. SITE                         : = ''AUDI CKD_DE_ING''     OR  (공백일경우 모든 SITE 검색)
3. ITEM                        : = ''APAAGIHEV-A2''  OR  (공백일경우 모든 ITEM 검색)
4. INCOTERMS                   : = ''FCA''  OR  (공백일경우 모든 INCOTERMS 검색)
5. 값을 입력한날짜(시작) : = ''20191201''                  OR  (공백일경우 과거 8주 검색)
6. 값을 입력한날짜(끝)    : = ''20191231''                 OR  (공백일경우 금일까지 검색)
*/

SELECT * FROM 
(
SELECT ''81'' DIVISION_ID, EDI.SCM_SITE_ID, EDI.ITEM_ID
		,NVL(
				CASE WHEN
				(
					SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ Z.PROJECT_CODE
					FROM SCM_MST_SITE_ITEM Z
					WHERE Z.SCM_SITE_ID			= EDI.SCM_SITE_ID
						AND Z.ITEM_ID			= EDI.ITEM_ID
				) 
				= '''' THEN ''★ NOT FOUND! ★'' 
					ELSE 
				(
					SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ Z.PROJECT_CODE
					FROM SCM_MST_SITE_ITEM Z
					WHERE Z.SCM_SITE_ID			= EDI.SCM_SITE_ID
						AND Z.ITEM_ID			= EDI.ITEM_ID
				) 
					END
				,''★ NOT FOUND! ★'') PROJECT_CODE
		,CASE EDI.ERP_FCST_TYPE WHEN ''M'' THEN ''MPS'' WHEN ''S'' THEN ''SMC'' ELSE ''MPS'' END FCST_TYPE
		,EDI.RDD_START AS YYYYMMDD,QTY
		,NVL( 
				CASE WHEN
				(
				SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ ATTRIBUTE6
					FROM SCM_MST_SITE_ITEM A
					WHERE A.SCM_SITE_ID			= EDI.SCM_SITE_ID
					AND A.ITEM_ID				= EDI.ITEM_ID
					AND A.PROJECT_CODE = 
								(
								SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ Z.PROJECT_CODE
								FROM SCM_MST_SITE_ITEM Z
								WHERE Z.SCM_SITE_ID	= EDI.SCM_SITE_ID
									AND Z.ITEM_ID	= EDI.ITEM_ID
										)
					----AND A.YYYYMMDD >= CONVERT(CHAR(8), (FN_NEXT_DAY(TO_CHAR(SYSDATE, ''YYYYMMDD''), ''MON'') + (-7)), 112) 
					----AND A.FCST_TYPE = CASE EDI.ERP_FCST_TYPE WHEN ''M'' THEN ''MPS'' WHEN ''S'' THEN ''SMC'' ELSE ''MPS'' END 
				--), ''DAP''
				)
				 = '''' THEN ''★ NOT FOUND! ★'' 
				ELSE
				(
				SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ ATTRIBUTE6
					FROM SCM_MST_SITE_ITEM A
					WHERE A.SCM_SITE_ID			= EDI.SCM_SITE_ID
					AND A.ITEM_ID				= EDI.ITEM_ID
					AND A.PROJECT_CODE = 
								(
								SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ Z.PROJECT_CODE
								FROM SCM_MST_SITE_ITEM Z									WHERE Z.SCM_SITE_ID	= EDI.SCM_SITE_ID
								           AND Z.ITEM_ID	= EDI.ITEM_ID
										)
					----AND A.YYYYMMDD >= CONVERT(CHAR(8), (FN_NEXT_DAY(TO_CHAR(SYSDATE, ''YYYYMMDD''), ''MON'') + (-7)), 112) 
					----AND A.FCST_TYPE = CASE EDI.ERP_FCST_TYPE WHEN ''M'' THEN ''MPS'' WHEN ''S'' THEN ''SMC'' ELSE ''MPS'' END 
				--), ''DAP''
				)
				END
				, ''★ NOT FOUND! ★''  -- 20181120 기본값 셋팅해주지 않는것으로 변경
		)  
			INCOTERMS
		,CASE SUBSTR(EDI.ITEM_ID,2,1) WHEN ''P'' THEN EDI.SHIP_FROM_PLANT || ''-P'' 
											WHEN ''M'' THEN EDI.SHIP_FROM_PLANT || ''-P'' 
											WHEN ''C'' THEN EDI.SHIP_FROM_PLANT || ''-A'' 
											ELSE EDI.SHIP_FROM_PLANT || ''-A'' END PLANT_SITE_ID
		,''E'' DOM_EXP
		,EDI.COMPANY_ID
		,EDI.SOLDTO_CODE
		,EDI.SHIPTO_CODE
		,EDI.DOC_IDENTIFINER
		,EDI.ATTRIBUTE2 AS IFSEQNO
		,EDI.CREATION_DATE
		,EDI.LAST_UPDATE_DATE
		--,TO_CHAR(EDI.CREATION_DATE, ''YYYY-MM-DD HH24:MI:SS'')  AS CREATION_DATE
		--,TO_CHAR(EDI.LAST_UPDATE_DATE, ''YYYY-MM-DD HH24:MI:SS'')  AS LAST_UPDATE_DATE
	--INTO #T_TEMP_I  -- MKT_FCST 에 최종INSERT 할 테이블
FROM (
		SELECT 
				(
				SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ A.SCM_SITE_ID
					FROM SCM_MST_SITE_CUSTOMER A
						WHERE A.DIVISION_ID		IN ( ''40'',''81'')
						AND A.SOLDTO_CODE	= ITEM.SOLDTO_CODE
						AND A.SHIPTO_CODE	= ITEM.SHIPTO_CODE
						AND A.VALID_YN		= ''Y''
				) SCM_SITE_ID
				,PARTNERS.SHIP_FROM_PLANT
				,ITEM.*
			 FROM DM_DNM_EDI_CALLOFF_ITEM ITEM
				 ,DM_DNM_EDI_C') || TO_CLOB('ALLOFF_PARTNER PARTNERS
			WHERE ITEM.ATTRIBUTE1 = ''ING''
				AND PARTNERS.SOLDTO_CODE	 = ITEM.SOLDTO_CODE
				AND PARTNERS.SHIPTO_CODE	 = ITEM.SHIPTO_CODE
				AND PARTNERS.DOC_IDENTIFINER = ITEM.DOC_IDENTIFINER
				AND (
					 -- 두 자리가 ''00'' 주차정보 OR 마지막 두 자리가 ''00'' 월정보 인경우는 날짜에 상관없이 조회되도록함 (START)
					 CASE 
					 WHEN SUBSTR(ITEM.RDD_START,5,2) = ''00'' OR SUBSTR(ITEM.RDD_START,7,2) = ''00''  
						THEN TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)
					 ELSE ITEM.RDD_START 
					 END 
					 -- 두 자리가 ''00'' 주차정보 OR 마지막 두 자리가 ''00'' 월정보 인경우는 날짜에 상관없이 조회되도록함 (END)
					 >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)  -- 당주 월요일 이후건만
					)
				) EDI

) X
WHERE 1=1
   		AND X.PROJECT_CODE = ( CASE WHEN :PARAM_PROJECT_CODE = '''' THEN X.PROJECT_CODE ELSE :PARAM_PROJECT_CODE END)
		AND X.SCM_SITE_ID = ( CASE WHEN :PARAM_SCM_SITE_ID = '''' THEN X.SCM_SITE_ID ELSE :PARAM_SCM_SITE_ID END)
		AND X.ITEM_ID = ( CASE WHEN :PARAM_ITEM_ID = '''' THEN X.ITEM_ID ELSE :PARAM_ITEM_ID END)
		AND X.INCOTERMS = ( CASE WHEN :PARAM_INCOTERMS = '''' THEN X.INCOTERMS ELSE :PARAM_INCOTERMS END)
		/* 날짜조건이 N/A일경우 지난주 월요일부터 데이터만 조회 */
		AND TO_CHAR(X.CREATION_DATE, ''YYYYMMDD'')	>=	
		( CASE WHEN :PARAM_FROM_DATE = ''''	THEN TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7*8), 112)	
		ELSE TO_CHAR(:PARAM_FROM_DATE, ''YYYYMMDD'') END ) 
		/* 날짜조건이 N/A일경우 오늘까지의 데이터만 조회 */
		AND TO_CHAR(X.CREATION_DATE, ''YYYYMMDD'')	<=	
		( CASE WHEN :PARAM_TO_DATE = '''' THEN TO_CHAR(SYSDATE, ''YYYYMMDD'') ELSE TO_CHAR(:PARAM_TO_DATE, ''YYYYMMDD'') END)				-- EDI 정보 인터페이스 오류건




'), 'Y', 'Y', 'songkeeho', TO_DATE('2019-01-02 16:05:46','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (51, '-', 'MKT_FCST 계획과 SALES_RESULT 실적 비교', 'MKT_FCST 계획과 SALES_RESULT 실적 비교', TO_CLOB('/*
EX) 
:PARAM_DIVSION_ID   = ''81'' OR ''''
:PARAM_SALES_YYYYMM = ''201901'' --월별조회
*/
-- (1) MKT_FCST○,SALES_RESULT○
SELECT A.DIVISION_ID,C.CUSTOMER_CODE,C.CUSTOMER_NAME, A.SCM_SITE_ID, C.SALES_SITE_ID AS RESULT_SITE_ID,SUBSTR(A.YYYYMMDD,1,6) AS SALES_YYYYMM, SUM(A.QTY) AS FCST_QTY,SUM(C.SALES_QTY) AS SALES_QTY,''(1) MKT_FCST=○,SALES_RESULT=○'' AS ''TYPE''
	FROM DM_PLN_MKT_FCST A
		INNER JOIN SCM_MST_SITE_CUSTOMER B
			ON( A.DIVISION_ID = B.DIVISION_ID
			AND A.SCM_SITE_ID = B.SCM_SITE_ID)
		INNER JOIN DM_DNM_SALES_RESULT_IF C
			ON( A.DIVISION_ID = C.DIVISION_ID
			AND A.SCM_SITE_ID = C.SALES_SITE_ID
			AND B.SOLDTO_CODE = C.CUSTOMER_CODE
			)
		AND a.division_id = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN A.DIVISION_ID ELSE :PARAM_DIVSION_ID END )
		AND a.measure = ''MKT_FCST''
		AND a.yyyymmdd between CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN a.yyyymmdd ELSE  SUBSTR(:PARAM_SALES_YYYYMM,1,6) + ''01''  END -- 조회월의 1일
						   and CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN a.yyyymmdd ELSE  CONVERT(CHAR(8), DATEADD(DD,-1,CONVERT(CHAR(8), ADD_MONTHS(SUBSTR(:PARAM_SALES_YYYYMM,1,6) + ''01'', +1), 112) ), 112)  END  -- 조회월의 말일
		AND b.valid_yn = ''Y''
		AND a.qty <> 0 
		AND C.SALES_YYYYMM = CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN C.SALES_YYYYMM ELSE  :PARAM_SALES_YYYYMM  END
		AND C.cost_item = ''''
		AND LENGTH(C.customer_code) > 4
GROUP BY A.DIVISION_ID,C.CUSTOMER_CODE,C.CUSTOMER_NAME, A.SCM_SITE_ID, C.SALES_SITE_ID,SUBSTR(A.YYYYMMDD,1,6)

UNION ALL

-- (2) MKT_FCST○,SALES_RESULTⅩ
SELECT A.DIVISION_ID,B.SOLDTO_CODE AS CUSTOMER_CODE, '''' AS CUSTOMER_NAME, A.SCM_SITE_ID, '''' AS RESULT_SITE_ID,SUBSTR(A.YYYYMMDD,1,6),SUM(A.QTY) AS FCST_QTY,''0'' AS SALES_QTY,''(2) MKT_FCST=○,SALES_RESULT=Ⅹ'' AS ''TYPE''
	FROM DM_PLN_MKT_FCST A
	INNER JOIN SCM_MST_SITE_CUSTOMER B
		ON( A.DIVISION_ID = B.DIVISION_ID
		AND A.SCM_SITE_ID = B.SCM_SITE_ID)
	where a.division_id = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN A.DIVISION_ID ELSE :PARAM_DIVSION_ID END )
	and a.measure = ''MKT_FCST''
	AND a.yyyymmdd between CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN a.yyyymmdd ELSE  SUBSTR(:PARAM_SALES_YYYYMM,1,6) + ''01''  END -- 조회월의 1일
						and CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN a.yyyymmdd ELSE  CONVERT(CHAR(8), DATEADD(DD,-1,CONVERT(CHAR(8), ADD_MONTHS(SUBSTR(:PARAM_SALES_YYYYMM,1,6) + ''01'', +1), 112) ), 112)  END  -- 조회월의 말일
	and b.valid_yn = ''Y''
	and a.qty <> 0 
	AND NOT EXISTS (
			SELECT DISTINCT C.DIVISION_ID, C.CUSTOMER_CODE, C.CUSTOMER_NAME, '''' AS SOLDTO_CODE, '''' AS SCM_SITE_ID, C.SALES_SITE_ID AS RESULT_SITE_ID
				FROM LGCE_SCMPROD.DM_DNM_SALES_RESULT_IF C
				where division_id = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN DIVISION_ID ELSE :PARAM_DIVSION_ID END )
				AND C.SALES_YYYYMM = CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN C.SALES_YYYYMM ELSE  :PARAM_SALES_YYYYMM  END
				and cost_item = ''''
				and LENGTH(C.customer_code) > 4
				AND A.DIVISION_ID = C.DIVISION_ID
				AND B.SOLDTO_CODE = C.CUSTOMER_CODE
					)
GROUP BY A.DIVISION_ID,B.SOLDTO_CODE, A.SCM_SITE_ID,SUBSTR(A.YYYYMMDD,1,6)

UNION ALL

-- (3) MKT_FCSTⅩ,SALES_RESULT○
SELECT C.DIVISION_ID, C.CUSTOMER_CODE, C.CUSTOMER_NAME, '''' AS SCM_SITE_ID, C.SALES_SITE_ID AS RESULT_SITE_ID,C.SALES_YYYYMM,''0'' AS FCST_QTY,SUM(C.SALES_QTY) AS SALES_QTY,''(3) MKT_FCST=Ⅹ,SALES_RESULT=○'' AS ''TYPE''
	FROM LGCE_SCMPROD.DM_DNM_SALES_RESULT_IF C
	where division_id = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN DIVISION_ID ELSE :PARAM_DIVSION_ID END )
	AND C.SALES_YYYYMM = CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN C.SALES_YYYYMM ELSE  :PARAM_SALES_YYYYMM  END
	and cost_item = ''''
	and LENGTH(C.customer_code) > 4
	AND NOT EXISTS (
					SELECT DISTINCT A.DIVISION_ID,'''' AS CUSTOMER_CODE, '''' AS CUSTOMER_NAME, B.SOLDTO_CODE, A.SCM_SITE_ID, '''' AS RESULT_SITE_ID
						FROM DM_PLN_MKT_FCST A
						INNER JOIN SCM_MST_SITE_CUSTOMER B
							ON( A.DIVISION_ID = B.DIVISION_ID
							AND A.S') || TO_CLOB('CM_SITE_ID = B.SCM_SITE_ID)
						where a.division_id = ( CASE WHEN :PARAM_DIVSION_ID = '''' THEN a.DIVISION_ID ELSE :PARAM_DIVSION_ID END )
						and a.measure = ''MKT_FCST''
						AND a.yyyymmdd between CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN a.yyyymmdd ELSE  SUBSTR(:PARAM_SALES_YYYYMM,1,6) + ''01''  END -- 조회월의 1일
										   and CASE WHEN :PARAM_SALES_YYYYMM  = '''' THEN a.yyyymmdd ELSE  CONVERT(CHAR(8), DATEADD(DD,-1,CONVERT(CHAR(8), ADD_MONTHS(SUBSTR(:PARAM_SALES_YYYYMM,1,6) + ''01'', +1), 112) ), 112)  END  -- 조회월의 말일
						and b.valid_yn = ''Y''
						and a.qty <> 0 
						AND A.DIVISION_ID = C.DIVISION_ID
						AND B.SOLDTO_CODE = C.CUSTOMER_CODE
					)
GROUP BY C.DIVISION_ID, C.CUSTOMER_CODE, C.CUSTOMER_NAME, C.SALES_SITE_ID,C.SALES_YYYYMM
'), 'Y', 'Y', 'songkeeho', TO_DATE('2019-01-18 15:14:21','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:00','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (3, '-', 'User Menu Access Count', '사용자 일자별 메뉴접속 Count', 'select 
       CASE a.MenuID WHEN ''Sales Site Project M'' THEN ''Sales Site Project Model''
	                 WHEN ''Customer Model Mappi'' THEN ''Customer Model Mapping''
					 ELSE a.MenuID END MENU_ID
	  ,a.UserID
      ,us.USER_NAME
	  , max( (case when dept.DEPT_NAME_KO is not null then dept.DEPT_NAME_KO else us.WORKING_NAME end ) ) DEPT_NAME_KO
	  ,TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') LOGIN_DATE
	  ,count(1) counts
      --,COUNT(1) OVER(ORDER BY a.UserID) sum_count
from TB_FX_MenuConnectLog a
      left outer join SCM_MST_SSO_USER_INFO us
	  on (a.UserID = us.USER_ID)
      left outer join SCM_MST_SSO_DEPT_INFO dept
	  on (us.DEPT_ID = dept.DEPT_ID)
 where 1=1
   and a.UserID = us.USER_ID
   and dept.DEPT_NAME_KO not like ''LG CNS%''
   and TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') >= ''20180330''
   and a.menuid IS NOT NULL
group by a.MenuID
	  ,a.UserID
      ,us.USER_NAME
	  ,TO_CHAR(LocalTimeStamp, ''YYYYMMDD'')

', 'Y', 'Y', 'zytchoi', TO_DATE('2018-03-30 20:20:16','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (4, '-', 'User Access Count Planner', 'User Access Count Planner', 'select 
       CASE a.MenuID WHEN ''Sales Site Project M'' THEN ''Sales Site Project Model''
	                 WHEN ''Customer Model Mappi'' THEN ''Customer Model Mapping''
					 ELSE a.MenuID END MENU_ID
	  ,a.UserID
      ,us.USER_NAME
	  , max( (case when dept.DEPT_NAME_KO is not null then dept.DEPT_NAME_KO else us.WORKING_NAME end ) ) DEPT_NAME_KO
	  ,TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') LOGIN_DATE
	  ,count(1) counts
      --,COUNT(1) OVER(ORDER BY a.UserID) sum_count
from TB_FX_MenuConnectLog a
      left outer join SCM_MST_SSO_USER_INFO us
	  on (a.UserID = us.USER_ID)
      left outer join SCM_MST_SSO_DEPT_INFO dept
	  on (us.DEPT_ID = dept.DEPT_ID)
 where 1=1
   and a.UserID = us.USER_ID
   and dept.DEPT_NAME_KO not like ''LG CNS%''
   and TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') >= ''20180330''
   and a.menuid IS NOT NULL
   and (
			select count(1)
			  from TB_FX_User z
			 where defaultgroupid in ( ''DM ADMIN'',''DM Planner'' )
			   and z.UserID = a.UserID
       ) > 0
group by a.MenuID
	  ,a.UserID
      ,us.USER_NAME
	  ,TO_CHAR(LocalTimeStamp, ''YYYYMMDD'')
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-04-02 09:49:28','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (7, '-', 'No Price MKT FCST', 'Unit Price가 없는 MKT_FCST', 'SELECT A.DIVISION_ID,A.MEASURE, D.DEPT_NAME_KO, B.OWNER, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, V.NICK_NAME, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, A.QTY
  FROM DM_PLN_MKT_FCST A
  INNER JOIN SCM_MST_SITE_ITEM B
  ON A.DIVISION_ID = B.DIVISION_ID
  AND A.SCM_SITE_ID = B.SCM_SITE_ID
  AND A.PROJECT_CODE = B.PROJECT_CODE
  AND A.ITEM_ID      = B.ITEM_ID
  AND B.VALID_YN   = ''Y''
  INNER JOIN SCM_MST_SITE C
  ON A.DIVISION_ID = C.DIVISION_ID
  AND A.SCM_SITE_ID = C.SCM_SITE_ID
  AND C.VALID_YN = ''Y''
  INNER JOIN DM_MST_ITEM_SINGLE_V V
  ON A.DIVISION_ID = V.DIVISION_ID
  AND A.ITEM_ID = V.ITEM_ID
  INNER JOIN SCM_MST_SSO_DEPT_INFO D
  ON C.DEPT_ID = D.DEPT_ID
  AND C.VALID_YN = ''Y''
 WHERE A.YYYYMMDD >= TO_CHAR(TRUNC(SYSDATE - 7, ''IW''), ''YYYYMMDD'')
   AND (
          SELECT COUNT(1)
		    FROM SCM_MST_FUTURE_PRICE P
		  WHERE A.DIVISION_ID = P.DIVISION_ID
		    AND A.PROJECT_CODE = P.PROJECT_CODE
			AND A.SCM_SITE_ID = P.SCM_SITE_ID
			AND A.ITEM_ID = P.ITEM_ID
			AND A.DOM_EXP = P.DOM_EXP
			AND A.FCST_TYPE = P.FCST_TYPE
			AND P.YYYYMMDD = ( SELECT BASIS_START_DATE FROM SCM_SYS_CALENDAR_M WHERE BASIS_YYYYMMDD = A.YYYYMMDD )
                                    AND A.INCOTERMS = P.INCOTERMS
			AND P.PRICE > 0
       ) = 0
   --AND A.MEASURE  IN ( ''RTF'' , ''MKT_FCST'' )
   AND A.MEASURE IN ( SELECT SEGMENT1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''DQ_NOPRICE_MEASURE'' AND VALID_YN = ''Y'' AND SEGMENT2 = :PARAM1 )
   AND A.QTY <> 0
   AND A.DIVISION_ID <> ''40''
   AND A.DIVISION_ID = CASE WHEN :PARAM1 = '''' THEN A.DIVISION_ID ELSE :PARAM1 END
UNION ALL
SELECT A.DIVISION_ID,A.MEASURE, D.DEPT_NAME_KO, B.OWNER, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, V.NICK_NAME, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, A.QTY
  FROM DM_PLN_MKT_FCST A
  INNER JOIN SCM_MST_SITE_ITEM B
  ON A.DIVISION_ID = B.DIVISION_ID
  AND A.SCM_SITE_ID = B.SCM_SITE_ID
  AND A.PROJECT_CODE = B.PROJECT_CODE
  AND A.ITEM_ID      = B.ITEM_ID
  AND B.VALID_YN   = ''Y''
  INNER JOIN SCM_MST_SITE C
  ON A.DIVISION_ID = C.DIVISION_ID
  AND A.SCM_SITE_ID = C.SCM_SITE_ID
  AND C.VALID_YN = ''Y''
  INNER JOIN DM_MST_ITEM_SINGLE_V V
  ON A.DIVISION_ID = V.DIVISION_ID
  AND A.ITEM_ID = V.ITEM_ID
  INNER JOIN SCM_MST_SSO_USER_INFO E
  ON  REGEXP_SUBSTR(B.OWNER, ''[^,]+'', 1, 1) = E.USER_ID
  INNER JOIN SCM_MST_SSO_DEPT_INFO D
  ON E.DEPT_ID = D.DEPT_ID
 WHERE A.YYYYMMDD >= TO_CHAR(TRUNC(SYSDATE - 7, ''IW''), ''YYYYMMDD'')
   AND (
          SELECT COUNT(1)
		    FROM SCM_MST_FUTURE_PRICE P
		  WHERE A.DIVISION_ID = P.DIVISION_ID
		    AND A.PROJECT_CODE = P.PROJECT_CODE
			AND A.SCM_SITE_ID = P.SCM_SITE_ID
			AND A.ITEM_ID = P.ITEM_ID
			AND A.DOM_EXP = P.DOM_EXP
			AND A.FCST_TYPE = P.FCST_TYPE
			AND P.YYYYMMDD = ( SELECT BASIS_START_DATE FROM SCM_SYS_CALENDAR_M WHERE BASIS_YYYYMMDD = A.YYYYMMDD )
                                    AND A.INCOTERMS = P.INCOTERMS
			AND P.PRICE > 0
       ) = 0
   --AND A.MEASURE IN ( ''RTF'' , ''MKT_FCST'' )
   AND A.MEASURE IN ( SELECT SEGMENT1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''DQ_NOPRICE_MEASURE'' AND VALID_YN = ''Y'' AND SEGMENT2 = :PARAM1 )
   AND A.QTY <> 0
   AND A.DIVISION_ID = ''40''
   AND A.DIVISION_ID = CASE WHEN :PARAM1 = '''' THEN A.DIVISION_ID ELSE :PARAM1 END
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-04-03 09:22:09','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:59:40','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (8, '-', 'MKT FCST Version GAP', 'MKT FCST의 Version별 차이 비교', 'select z.division_id,c.DEPT_NAME_KO, b.SOLDTO_CUSTOMER, z.SCM_SITE_ID, z.PROJECT_CODE, d.project_name, z.ITEM_ID, z.DOM_EXP,  case z.fcst_type when ''MPS'' then ''양산'' when ''SMC'' then ''셈플'' when ''ETC'' then ''기타'' end fcst_type
     ,  case e.item_type when ''P'' then ''제품'' when ''Q'' then ''상품'' when ''R'' then ''자재'' else  e.item_type end item_type 
     , INCOTERMS, PLANT_SITE_ID,  measure,YYYYMMDD, sum(ver_A) ver_A, sum(ver_b) ver_B, sum(ver_A) - sum(ver_b) GAP
  from (
  select a.division_id, a.SCM_SITE_ID, a.PROJECT_CODE, a.ITEM_ID, a.DOM_EXP, a.FCST_TYPE, a.INCOTERMS, a.PLANT_SITE_ID, measure, a.YYYYMMDD, a.qty ver_A, 0 ver_b
    from dm_pln_mkt_fcst_c a
  where 1=1
    and division_id = :PARAM1
	and a.version_no = :PARAM2
	and a.qty > 0
  UNION

  select a.division_id, a.SCM_SITE_ID, a.PROJECT_CODE, a.ITEM_ID, a.DOM_EXP, a.FCST_TYPE, a.INCOTERMS, a.PLANT_SITE_ID, measure, a.YYYYMMDD, 0 ver_A, a.qty ver_b
    from dm_pln_mkt_fcst_c a
  where 1=1
    and division_id = :PARAM1
    and a.version_no = :PARAM3
		and a.qty > 0
	 ) z
        ,scm_mst_site b
	  ,SCM_MST_SSO_DEPT_INFO c
	  ,scm_mst_project d
	  ,DM_MST_ITEM_SINGLE_V e
where z.measure = ''MKT_FCST''
   and z.scm_site_id = b.scm_site_id
   and b.dept_id = c.dept_id
   and z.project_code = d.PROJECT_CODE
   and z.division_id = e.division_id
   and z.item_id = e.item_id
group by z.division_id, z.SCM_SITE_ID, z.PROJECT_CODE, z.ITEM_ID, z.DOM_EXP, z.FCST_TYPE, z.INCOTERMS, z.PLANT_SITE_ID, z.measure,z.YYYYMMDD, e.item_type,c.DEPT_NAME_KO, b.SOLDTO_CUSTOMER,d.project_name
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-04-04 13:49:57','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:55:59','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (9, '-', 'ESS Exfactory FCST by Current', 'ESS 출하일 기준 MKT FCST 확인', '/*
##############  필  독 ##############
LOOKUP -> LOOKUP TYPE = ''ESS_BOD_LT_INSERT'' 조회
하단의 LOOKUP VALUE 값이 설정된 SITE만 
BOD L/T 와 출하일 값이 출력됩니다.
####################################
*/

SELECT A.DIVISION_ID, C.DEPT_NAME_KO, B.SOLDTO_CUSTOMER ,A.SCM_SITE_ID,  A.PROJECT_CODE,  D.PROJECT_NAME
	  ,D.PROJECT_OWNER
	  ,(
          SELECT Z.USER_NAME
		    FROM SCM_MST_SSO_USER_INFO Z
		   WHERE Z.USER_ID = D.PROJECT_OWNER
	   ) PROJECT_OWNER_KO
      , A.ITEM_ID, E.ITEM_NAME, CASE E.ITEM_TYPE WHEN ''P'' THEN ''제품'' WHEN ''Q'' THEN ''상품'' WHEN ''R'' THEN ''자재'' ELSE  E.ITEM_TYPE END ITEM_TYPE 
      , CASE FCST_TYPE WHEN ''MPS'' THEN ''양산'' WHEN ''SMC'' THEN ''셈플'' WHEN ''ETC'' THEN ''기타'' END FCST_TYPE
 	  , A.INCOTERMS, YYYYMMDD  AS "매출일"
      ,NVL( (


          SELECT DISTINCT CAST(U.SEGMENT4 AS INT)
		   FROM SCM_ADM_LOOKUP_MASTER_DETAIL U
		  WHERE 1=1
		    AND LOOKUP_TYPE = ''ESS_BOD_LT_INSERT'' 
			AND U.SEGMENT2 = A.SCM_SITE_ID
		    AND U.SEGMENT3 = A.INCOTERMS
			AND U.SEGMENT1 = A.PROJECT_CODE

       ),  CASE WHEN A.INCOTERMS = ''EXW'' THEN 0 ELSE NULL END 
	   ) AS "BOD_LT"
	 ,  TO_CHAR(DATEADD( DAY ,- NVL( (


														  SELECT DISTINCT CAST(U.SEGMENT4 AS INT)
														   FROM SCM_ADM_LOOKUP_MASTER_DETAIL U
														  WHERE 1=1
														    AND LOOKUP_TYPE = ''ESS_BOD_LT_INSERT''
															AND U.SEGMENT2 = A.SCM_SITE_ID
															AND U.SEGMENT3 = A.INCOTERMS
															AND U.SEGMENT1 = A.PROJECT_CODE),  CASE WHEN A.INCOTERMS = ''EXW'' THEN 0 ELSE NULL END 
													   ) , CAST(YYYYMMDD AS DATETIME) 
                ), 112 ) AS "출하일"
      ,NVL( (
				SELECT MAX( LT_TOTAL )
				  FROM SCP_MST_BOD_V X
				 WHERE 1=1
				   AND X.PRIORITY = (
									   SELECT MIN( Z.PRIORITY )
											  FROM SCP_MST_BOD_V Z
											 WHERE 1=1
											   AND Z.TO_SITE = A.SCM_SITE_ID
											   AND Z.INCOTERMS = A.INCOTERMS
											   AND Z.BOD_VALID_YN = ''Y''
											   ) 

				   AND X.TO_SITE = A.SCM_SITE_ID
				   AND X.INCOTERMS = A.INCOTERMS
                                                   AND X.DIVISION_ID = A.DIVISION_ID
                                                   AND X.BOD_VALID_YN = ''Y''
	   ),  CASE WHEN A.INCOTERMS = ''EXW'' THEN 0 ELSE NULL END ) AS "SCP_BOD_LT"
	 ,  TO_CHAR(DATEADD( DAY ,- NVL( (
											SELECT MAX( LT_TOTAL )
											  FROM SCP_MST_BOD_V X
											 WHERE X.PRIORITY = 1
											   AND X.TO_SITE = A.SCM_SITE_ID
											   AND X.INCOTERMS = A.INCOTERMS
                                                                                                                                       AND X.DIVISION_ID = A.DIVISION_ID
                                                                                                                                       AND X.BOD_VALID_YN = ''Y''),  CASE WHEN A.INCOTERMS = ''EXW'' THEN 0 ELSE NULL END 
													   ) , CAST(YYYYMMDD AS DATETIME) 
                ), 112 ) AS "SCP_BOD_출하일"
	  ,QTY
,E.Energe as Energy , E.Cell_Quantity --20200116 KHSONG ADD
 -- INTO #ESS_EXFACTORY_FCST
FROM DM_PLN_MKT_FCST A
        ,SCM_MST_SITE B
	  ,SCM_MST_SSO_DEPT_INFO C
	  ,SCM_MST_PROJECT D
	  ,DM_MST_ITEM_SINGLE_V E
 WHERE A.DIVISION_ID = 82
   AND A.DIVISION_ID = B.DIVISION_ID
   AND B.VALID_YN = ''Y''
   AND A.SCM_SITE_ID = B.SCM_SITE_ID
   AND B.DEPT_ID = C.DEPT_ID
   AND A.PROJECT_CODE = D.PROJECT_CODE
   AND A.DIVISION_ID = E.DIVISION_ID
   AND A.ITEM_ID = E.ITEM_ID
   AND MEASURE = ''MKT_FCST''
   AND QTY >  0
   -- AND YYYYMMDD >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)
   AND YYYYMMDD >= SUBSTR(TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112), 1, 6 ) + ''01''
', 'Y', 'Y', 'songkeeho', TO_DATE('2018-04-04 14:04:26','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (10, '-', 'ESS Exfactory FCST by Version', 'cutoff 버젼별 ESS 출하일 기준 MKT FCST 확인', TO_CLOB('/*
##############  필  독 ##############
Lookup -> Lookup Type = ''ESS_BOD_LT_INSERT'' 조회
하단의 Lookup Value 값이 설정된 Site만 
BOD L/T 와 출하일 값이 출력됩니다.
####################################
*/

select a.division_id, c.DEPT_NAME_KO, b.SOLDTO_CUSTOMER ,a.scm_site_id,  a.project_code,  d.project_name
	  ,D.PROJECT_OWNER
	  ,(
          select z.user_name
		    from SCM_MST_SSO_USER_INFO z
		   where z.USER_ID = D.PROJECT_OWNER
	   ) PROJECT_OWNER_KO
      , a.item_id, e.item_name, case e.item_type when ''P'' then ''제품'' when ''Q'' then ''상품'' when ''R'' then ''자재'' else  e.item_type end item_type 
      , case fcst_type when ''MPS'' then ''양산'' when ''SMC'' then ''셈플'' when ''ETC'' then ''기타'' end fcst_type
 	  , a.incoterms, yyyymmdd  as "매출일"
      ,NVL( (


          SELECT DISTINCT CAST(U.SEGMENT4 AS int)
		   FROM SCM_ADM_LOOKUP_MASTER_DETAIL U
		  WHERE 1=1
		    AND LOOKUP_TYPE = ''ESS_BOD_LT_INSERT'' 
			AND U.SEGMENT2 = A.SCM_SITE_ID
		    AND U.SEGMENT3 = A.INCOTERMS
			AND U.SEGMENT1 = A.PROJECT_CODE

       ),  case when a.incoterms = ''EXW'' then 0 else null end 
	   ) as "BOD_LT"
	 ,  TO_CHAR(dateadd( day ,- NVL( (
														  SELECT DISTINCT CAST(U.SEGMENT4 AS int)
														   FROM SCM_ADM_LOOKUP_MASTER_DETAIL U
														  WHERE 1=1
														    AND LOOKUP_TYPE = ''ESS_BOD_LT_INSERT''
															AND U.SEGMENT2 = A.SCM_SITE_ID
															AND U.SEGMENT3 = A.INCOTERMS
															AND U.SEGMENT1 = A.PROJECT_CODE),  case when a.incoterms = ''EXW'' then 0 else null end 
													   ) , cast(yyyymmdd as datetime) 
                ), 112 ) as "출하일"
      ,NVL( (


				SELECT MAX( LT_TOTAL )
				  FROM SCP_MST_BOD_V X
				 WHERE 1=1
				   AND X.PRIORITY = (
									   SELECT MIN( Z.PRIORITY )
											  FROM SCP_MST_BOD_V Z
											 WHERE 1=1
											   AND Z.TO_SITE = A.SCM_SITE_ID
											   AND Z.INCOTERMS = A.INCOTERMS
											   AND Z.BOD_VALID_YN = ''Y''
											   ) 


				   AND X.TO_SITE = A.SCM_SITE_ID
				   AND X.INCOTERMS = A.INCOTERMS
                                                   and x.bod_valid_yn = ''Y''
	   ),  case when a.incoterms = ''EXW'' then 0 else null end ) as "SCP_BOD_LT"
	 ,  convert( varchar, 
	     dateadd( day ,- NVL( (


											SELECT MAX( LT_TOTAL )
											  FROM SCP_MST_BOD_V X
											 WHERE 1=1
											   AND X.PRIORITY = (
																   SELECT MIN( Z.PRIORITY )
																		  FROM SCP_MST_BOD_V Z
																		 WHERE 1=1
																		   AND Z.TO_SITE = A.SCM_SITE_ID
																		   AND Z.INCOTERMS = A.INCOTERMS
																		   AND Z.BOD_VALID_YN = ''Y''
																		   ) 


											   AND X.TO_SITE = A.SCM_SITE_ID
											   AND X.INCOTERMS = A.INCOTERMS
                                                                                                                                       and x.bod_valid_yn = ''Y''
								   ),  case when a.incoterms = ''EXW'' then 0 else null end 
													   ) , cast(yyyymmdd as datetime) 
                ), 112 ) as "SCP_BOD_출하일"

	  ,QTY
,E.ENERGE as ENERGY , E.CELL_QUANTITY --20200116 KHSONG ADD
 -- into #ESS_EXFACTORY_FCST
from (
        select division_id, scm_site_id, project_code,item_id, fcst_type, incoterms, yyyymmdd, measure, qty from dm_pln_mkt_fcst_c where version_no = :PARAM1  AND DIVISION_ID = ''82''
		UNION
		select division_id, scm_site_id, project_code,item_id, fcst_type, incoterms, yyyymmdd, measure, qty from dm_pln_mkt_fcst where yyyymmdd >= SUBSTR(TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112), 1, 6 ) + ''01'' and yyyymmdd < TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)
AND DIVISION_ID = ''82''

	    ) a
        ,scm_mst_site b
	  ,SCM_MST_SSO_DEPT_INFO c
	  ,scm_mst_project d
	  ,DM_MST_ITEM_SINGLE_V e
 where a.division_id = 82
   AND A.DIVISION_ID = B.DIVISION_ID
   AND B.VALID_YN = ''Y''
   and a.scm_site_id = b.scm_') || TO_CLOB('site_id
   and b.dept_id = c.dept_id
   and a.project_code = d.PROJECT_CODE
   and a.division_id = e.division_id
   and a.item_id = e.item_id
   and measure = ''MKT_FCST''
   and qty >  0
   -- and yyyymmdd >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)
   AND YYYYMMDD >= SUBSTR(TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112), 1, 6 ) + ''01'''), 'Y', 'Y', 'songkeeho', TO_DATE('2018-04-04 14:09:12','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (12, '-', 'DM RCCP_VIEW GAP ', 'DM의 MKT FCST수량과 RCCP로 전달된 수량의 차이비교', 'select item_id, YYYYMM, sum(DM_qty) DM_qty, sum(RCCP_V_QTY) RCCP_V_QTY, sum(DM_qty) - sum(RCCP_V_QTY) GAP
from (
select item_id, SUBSTR(YYYYMMDD, 1,6) YYYYMM, SUM(qty) DM_qty , 0 RCCP_V_QTY
  from dm_pln_mkt_fcst_c a
      ,( select max(ver_cd) max_ver_cd from LGCE_SCMPROD.DMS_RCCP_DP_VIEW) b
where version_no = b.max_ver_cd
  and division_id = ''81''
  and measure = ''MKT_FCST''
group by item_id, SUBSTR(YYYYMMDD, 1,6)
UNION 
SELECT MAT_CD item_id
      , SUBSTR(YYYYMMDD, 1,6) YYYYMM
	  , 0 DM_qty
      ,sum( QTY ) RCCP_V_QTY 
  FROM LGCE_SCMPROD.DMS_RCCP_DP_VIEW
       ,( select max(ver_cd) max_ver_cd from LGCE_SCMPROD.DMS_RCCP_DP_VIEW) b
 where ver_cd = b.max_ver_cd
group by MAT_CD, SUBSTR(YYYYMMDD, 1,6)
) x
group by  item_id, YYYYMM
', 'N', 'Y', 'zytchoi', TO_DATE('2018-04-17 10:57:25','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:55:59','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (13, '-', 'ERP Sales Result SITE un-mapping', 'ERP 매출실적 정보중에서 site 정보가 연결되지 못한 정보', 'SELECT distinct COMPANY_ID, A.DIVISION_ID, SALES_WORK_PLACE_NAME AS SALES_WORK_PLACE , SALES_YYYYMM, SALES_POSTING_DATE, PROJECT_CODE,COST_ITEM_NAME, ITEM_ID, CUSTOMER_CODE, CUSTOMER_NAME,  SHIPTO_CODE, SHIPTO_DESCRIPTION, SALES_TYPE, INCOTERMS, LGS_ROUTE_NAME, SALES_QTY, SALES_AMOUNT_SUM, CURRENCY, PLANT_ID ,PROFIT_CENTER_NAME, PARTNER_PROFIT_CENTER_NAME, SALES_USER_NAME
  FROM dm_dnm_sales_result_if A
 WHERE a.sales_site_id in ( ''N'','''',''-'')
   and a.customer_code IS NOT NULL
AND A.SALES_WORK_PLACE <> ''82AS''
   and a.division_id = :PARAM1


/*
SELECT COMPANY_ID, A.DIVISION_ID, SALES_WORK_PLACE_NAME as SALES_WORK_PLACE , RESULT_YYYYMM, SALES_POSTING_DATE, PROJECT_CODE,COST_ITEM_NAME, ITEM_ID, CUSTOMER_CODE, CUSTOMER_NAME,  SHIPTO_CODE, SHIPTO_DESCRIPTION, SALES_TYPE, INCOTERMS, LGS_ROUTE_NAME, SALES_QTY, SALES_AMOUNT_SUM, CURRENCY, PLANT_ID ,PROFIT_CENTER_NAME, PARTNER_PROFIT_CENTER_NAME, SALES_USER_NAME
  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R A
      ,(
	     SELECT DIVISION_ID, MAX(IFSEQNO) MAX_IFSEQNO
		   FROM LGCE_INF.XIF_ERP_SALES_RESULT_R
		  WHERE DIVISION_ID  = :PARAM1
         GROUP BY DIVISION_ID 
	   ) B
 WHERE IFSEQNO = B.MAX_IFSEQNO
   AND A.IFSEQNO = B.MAX_IFSEQNO
   AND TRANSFER_FLAG = ''X''
   AND A.DIVISION_ID = B.DIVISION_ID
*/
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-04-18 18:08:40','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:55:59','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (14, '-', 'ERP Sales Result Project unmapping', 'ERP 매출실적에서 Project 정보가 Mapping 되지 못한 실적 정보', ' SELECT DIVISION_ID
		,PROJECT_CODE
		,SALES_SITE_ID
		,PLANT_SITE_ID
	--	,SITE_ITEM_MAPPING_YN
		,ITEM_ID
	--	,DOM_EXP
		,INCOTERMS
	--	,MEASURE
		,CURRENCY
		,sales_posting_date
		,FCST_TYPE
		,sales_qty
		,customer_code
		,SHIPTO_CODE
                        ,SALES_USER_NAME
		,(
		   SELECT COUNT(DISTINCT PROJECT_CODE)
		     FROM SCM_MST_SITE_ITEM SI
			WHERE SI.DIVISION_ID = A.DIVISION_ID
			  AND SI.SCM_SITE_ID = A.SALES_SITE_ID
			  AND SI.ITEM_ID = A.ITEM_ID
		  ) SITE_ITEM_PROJECT_COUNT
		,(
		   SELECT COUNT(DISTINCT PROJECT_CODE)
		     FROM SCM_MST_SITE_ITEM SI
			WHERE SI.DIVISION_ID = A.DIVISION_ID
		--	  AND SI.SCM_SITE_ID = A.SALES_SITE_ID
			  AND SI.ITEM_ID = A.ITEM_ID
		  ) ITEM_PROJECT_COUNT
  FROM dm_dnm_sales_result_if A
 WHERE PROJECT_CODE in ( ''N'','''',''-'')
   AND ITEM_ID <> ''ETC''
   AND SALES_WORK_PLACE <> ''82AS''
   AND DIVISION_ID = :PARAM1
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-04-18 18:15:06','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:55:59','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (15, '-', 'ESS Exfactory FCST Version GAP', 'ESS 출하일 기준 Version 차이', 'select division_id, dept_name_ko, soldto_customer, scm_site_id, project_code, project_name, item_id, item_name, item_type, fcst_type, incoterms, bod_lt, 출하일, sum(ver_A) ver_A, sum(ver_B) ver_B, sum(ver_A) - sum(ver_B)  GAP
  from (
select a.division_id, c.DEPT_NAME_KO, b.SOLDTO_CUSTOMER ,a.scm_site_id,  a.project_code,  d.project_name, a.item_id, e.item_name, case e.item_type when ''P'' then ''제품'' when ''Q'' then ''상품'' when ''R'' then ''자재'' else  e.item_type end item_type 
      , case fcst_type when ''MPS'' then ''양산'' when ''SMC'' then ''셈플'' when ''ETC'' then ''기타'' end fcst_type
 	  , incoterms --, yyyymmdd  as "매출일"
      ,NVL( (
          select distinct u.[L/T]
		   from [ESS_BOD_LT2$] u
		  where u.scm_site_id = a.scm_site_id
		    and u.incoterms = a.incoterms
			and u.project_code = a.project_code
       ),  case when incoterms = ''EXW'' then 0 else null end 
	   ) as "BOD_LT"
	 ,  convert( varchar, 
	     (case when incoterms = ''EXW'' then 0 else null end) + (- NVL( (
														  select distinct u.[L/T]
														   from [ESS_BOD_LT2$] u
														  where u.scm_site_id = a.scm_site_id
															and u.incoterms = a.incoterms
															and u.project_code = a.project_code
													   )) , cast(yyyymmdd as datetime) 
                ), 112 ) as "출하일"
	  ,QTY ver_A
	  ,0 ver_B
  from dm_pln_mkt_fcst_c a
        ,scm_mst_site b
	  ,SCM_MST_SSO_DEPT_INFO c
	  ,scm_mst_project d
	  ,DM_MST_ITEM_SINGLE_V e
 where a.division_id = 82
   and a.scm_site_id = b.scm_site_id
   and b.dept_id = c.dept_id
   and a.project_code = d.PROJECT_CODE
   and a.division_id = e.division_id
   and a.item_id = e.item_id
   and measure = ''MKT_FCST''
   and qty >  0
   and yyyymmdd >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)
   and a.version_no = :PARAM1
UNION ALL
select a.division_id, c.DEPT_NAME_KO, b.SOLDTO_CUSTOMER ,a.scm_site_id,  a.project_code,  d.project_name, a.item_id, e.item_name, case e.item_type when ''P'' then ''제품'' when ''Q'' then ''상품'' when ''R'' then ''자재'' else  e.item_type end item_type 
      , case fcst_type when ''MPS'' then ''양산'' when ''SMC'' then ''셈플'' when ''ETC'' then ''기타'' end fcst_type
 	  , incoterms --, yyyymmdd  as "매출일"
      ,NVL( (
          select distinct u.[L/T]
		   from [ESS_BOD_LT2$] u
		  where u.scm_site_id = a.scm_site_id
		    and u.incoterms = a.incoterms
			and u.project_code = a.project_code
       ),  case when incoterms = ''EXW'' then 0 else null end 
	   ) as "BOD_LT"
	 ,  convert( varchar, 
	     (case when incoterms = ''EXW'' then 0 else null end) + (- NVL( (
														  select distinct u.[L/T]
														   from [ESS_BOD_LT2$] u
														  where u.scm_site_id = a.scm_site_id
															and u.incoterms = a.incoterms
															and u.project_code = a.project_code
													   )) , cast(yyyymmdd as datetime) 
                ), 112 ) as "출하일"
	  ,0 Ver_A
	  ,QTY ver_B
  from dm_pln_mkt_fcst_c a
        ,scm_mst_site b
	  ,SCM_MST_SSO_DEPT_INFO c
	  ,scm_mst_project d
	  ,DM_MST_ITEM_SINGLE_V e
 where a.division_id = 82
   and a.scm_site_id = b.scm_site_id
   and b.dept_id = c.dept_id
   and a.project_code = d.PROJECT_CODE
   and a.division_id = e.division_id
   and a.item_id = e.item_id
   and measure = ''MKT_FCST''
   and qty >  0
   and yyyymmdd >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)
   and a.version_no = :PARAM2
   ) zz
group by division_id, dept_name_ko, soldto_customer, scm_site_id, project_code, project_name, item_id, item_name, item_type, fcst_type, incoterms, bod_lt, 출하일
', 'Y', 'Y', 'zytchoi', TO_DATE('2018-04-18 18:59:20','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:55:59','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (16, '-', 'sales site shipto check', 'sales site 모니터링용', '
select ''SHIPTO_중복'' TYPE, w.*
      ,(
					 SELECT distinct  (SELECT LISTAGG(DISTINCT z.dept_name_ko, '','') WITHIN GROUP (ORDER BY z.dept_name_ko) from scm_mst_site_item x
												  ,SCM_MST_SSO_USER_INFO y
												  ,SCM_MST_SSO_DEPT_INFO z
											 where x.division_id = w.division_id
											   and x.scm_site_id = w.scm_site_id
											   and x.owner = y.user_id
											   and y.dept_id = z.dept_id 
											   and x.valid_yn = ''Y'') 
	   ) TEAM
      ,(
					 SELECT distinct  (SELECT LISTAGG(DISTINCT y.user_name || '''' || y.job_name, '','') WITHIN GROUP (ORDER BY y.user_name || '''' || y.job_name) from scm_mst_site_item x
												  ,SCM_MST_SSO_USER_INFO y
												  ,SCM_MST_SSO_DEPT_INFO z
											 where x.division_id = w.division_id
											   and x.scm_site_id = w.scm_site_id
											   and x.owner = y.user_id
											   and y.dept_id = z.dept_id 
											   and x.valid_yn = ''Y'') 
	   ) OWNER
from  (
    select a.division_id, a.scm_site_id, a.country, a.city, b.soldto_code, SUBSTR(soldto_code,1,2) soldto_country, b.shipto_code, SUBSTR(shipto_code,1,2) shipto_country
		from scm_mst_site a
			,scm_mst_site_customer b
		where a.SCM_SITE_ID = b.scm_site_id
		and a.site_type = ''SALES''
		and a.valid_yn = ''Y''
		and a.valid_yn = b.VALID_YN
    )  w
	,(
    select b.DIVISION_ID, b.soldto_code, b.shipto_code
		from scm_mst_site a
			,scm_mst_site_customer b
		where a.SCM_SITE_ID = b.scm_site_id
		and a.site_type = ''SALES''
		and a.valid_yn = ''Y''
		and a.valid_yn = b.VALID_YN
		group by b.DIVISION_ID, b.soldto_code, b.shipto_code
		having count( distinct a.scm_site_id) > 1
	) y
where w.SHIPTO_CODE = y.SHIPTO_CODE
and w.SOLDTO_CODE = y.SOLDTO_CODE
and w.DIVISION_ID    = y.DIVISION_ID
UNION ALL
select ''Multi_shipto'' TYPE, *      ,(
					 SELECT DISTINCT  (SELECT LISTAGG(DISTINCT Z.DEPT_NAME_KO, '','') WITHIN GROUP (ORDER BY Z.DEPT_NAME_KO) FROM SCM_MST_SITE_ITEM X2
												  ,SCM_MST_SSO_USER_INFO Y
												  ,SCM_MST_SSO_DEPT_INFO Z
											 WHERE X2.DIVISION_ID = X.DIVISION_ID
											   AND X2.SCM_SITE_ID = X.SCM_SITE_ID
											   AND X2.OWNER = Y.USER_ID
											   AND Y.DEPT_ID = Z.DEPT_ID 
											   AND X2.VALID_YN = ''Y'') 
	   ) TEAM
      ,(
					 SELECT DISTINCT  (SELECT LISTAGG(DISTINCT Y.USER_NAME || '''' || Y.JOB_NAME, '','') WITHIN GROUP (ORDER BY Y.USER_NAME || '''' || Y.JOB_NAME) FROM SCM_MST_SITE_ITEM X2
												  ,SCM_MST_SSO_USER_INFO Y
												  ,SCM_MST_SSO_DEPT_INFO Z
											 WHERE X2.DIVISION_ID = X.DIVISION_ID
											   AND X2.SCM_SITE_ID = X.SCM_SITE_ID
											   AND X2.OWNER = Y.USER_ID
											   AND Y.DEPT_ID = Z.DEPT_ID 
											   AND X2.VALID_YN = ''Y'') 
	   ) OWNER

  from (
		select a.division_id, a.scm_site_id, a.country, a.city, b.soldto_code, SUBSTR(soldto_code,1,2) soldto_country, b.shipto_code, SUBSTR(shipto_code,1,2) shipto_country
				  from scm_mst_site a
					  ,scm_mst_site_customer b
				 where a.SCM_SITE_ID = b.scm_site_id
				   and a.site_type = ''SALES''
				   and a.valid_yn = ''Y''
				   and a.valid_yn = b.VALID_YN
			 )  x
 where scm_site_id in ( 
				select scm_site_id
				  from (
select a.division_id, a.scm_site_id, a.country, a.city, b.soldto_code, SUBSTR(soldto_code,1,2) soldto_country, b.shipto_code, SUBSTR(shipto_code,1,2) shipto_country
		  from scm_mst_site a
			  ,scm_mst_site_customer b
		 where a.SCM_SITE_ID = b.scm_site_id
		   and a.site_type = ''SALES''
		   and a.valid_yn = ''Y''
		   and a.valid_yn = b.VALID_YN
     )  y
				 where x.division_id = y.division_id
				group by scm_site_id
				having count( shipto_code) > 1
   )


', 'Y', 'Y', 'zytchoi', TO_DATE('2018-05-16 17:50:15','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:23:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (54, '-', 'MOVING PLAN', 'FP 공장 내 Cell 이동계획', 'SELECT P.DIVISION_ID
     , P.PLANT_ID
     , FS.SCM_SITE_ID AS FROM_SITE
     , TS.SCM_SITE_ID AS TO_SITE
     , P.ITEM_ID
     , P.PLAN_DATE
     , P.QTY
     , P.STORAGE_ID
     , P.SOC_ID
     , P.MARKET
FROM   SCM_DNM_CELL_INHOUSE_PLAN_SN P
--FROM   LGCE_FP_TR.FP_CELL_INHOUSE_PLAN_H P
     , SCM_MST_SITE FS
     , SCM_MST_SITE TS
WHERE  1=1
AND    P.DIVISION_ID      = :PARAM_DIVISION_ID
AND    P.DIVISION_ID      = FS.DIVISION_ID
AND    P.PLANT_ID         = FS.PLANT_ID
AND    P.CATEGORY         = ''MOVING''
AND    P.PLAN_DATE       >= :PARAM__PLAN_DATE
AND    FS.OPERATION_GROUP = ''A''
AND    FS.SITE_TYPE       = ''PLANT''  
AND    FS.OSP_YN          = ''N''
AND    FS.VALID_YN        = ''Y''
AND    P.DIVISION_ID      = TS.DIVISION_ID
AND    P.PLANT_ID         = TS.PLANT_ID
AND    TS.OPERATION_GROUP = ''P''
AND    TS.SITE_TYPE       = ''PLANT''  
AND    TS.OSP_YN          = ''N''
AND    TS.VALID_YN        = ''Y''', 'Y', 'Y', 'blueeos', TO_DATE('2019-06-12 15:35:23','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (55, '-', 'Plan Summart Report', 'Plan Summart Report', 'SELECT pl.division_id
      ,pl.plan_name
      ,pl.plan_type
      ,pl.plan_seq
      ,A.STEP
      ,A.TITLE
      ,A.QTY
      ,A.CNT
      ,A.QTY_RATIO
      ,A.CNT_RATIO
FROM   ENG_SCP.SCP_ENG_PLAN_SUMMARY A
     ,(SELECT P.DIVISION_ID, P.PLAN_ID, P.PLAN_NAME, PD.PLAN_TYPE, PD.PLAN_SEQ
            , P.DIVISION_ID || ''::'' || P.PLAN_CYCLE                  AS MASTER_ID
            , P.PLAN_ID || ''::'' || PD.PLAN_TYPE || ''::'' || TO_CHAR(PD.PLAN_SEQ) AS ENG_PLAN_ID
       FROM   SCM_MST_PLAN         P
            , SCM_MST_PLAN_DETAIL PD
       WHERE  P.DIVISION_ID = PD.DIVISION_ID
       AND    P.PLAN_ID     = PD.PLAN_ID
       AND    P.DIVISION_ID = :PARAM_DIVISION_ID
       AND    P.PLAN_CYCLE  = ''WEEKLY''
       AND    P.PLAN_NAME   = :PARAM_PLAN_YYYYMMDD
       AND   (:PARAM_PLAN_TYPE = '''' OR PD.PLAN_TYPE = :PARAM_PLAN_TYPE)
       AND   (:PARAM_PLAN_SEQ  = '''' OR PD.PLAN_SEQ  = :PARAM_PLAN_SEQ)
      ) PL
WHERE  A.MASTER_ID = PL.MASTER_ID
AND    A.PLAN_ID   = PL.ENG_PLAN_ID
', 'Y', 'Y', 'blueeos', TO_DATE('2019-06-18 11:07:01','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (56, '-', 'Plan Summart Report_SALES', 'Plan Summart Report_SALES', 'SELECT pl.division_id
      ,pl.plan_name
      ,pl.plan_type
      ,pl.plan_seq
      ,a.sales_site
      ,a.step
      ,a.title
      ,a.qty
      ,a.cnt
      ,a.qty_ratio
      ,a.cnt_ratio
FROM   eng_scp.scp_eng_plan_summary_sales a
     ,(SELECT p.division_id, p.plan_id, p.plan_name, pd.plan_type, pd.plan_seq
            , p.division_id || ''::'' || p.plan_cycle                  AS master_id
            , p.plan_id || ''::'' || pd.plan_type || ''::'' || TO_CHAR(pd.plan_seq) AS eng_plan_id
       FROM   scm_mst_plan         p
            , scm_mst_plan_detail pd
       WHERE  p.division_id = pd.division_id
       AND    p.plan_id     = pd.plan_id
       AND    p.division_id = :PARAM_DIVISION_ID
       AND    p.plan_cycle  = ''WEEKLY''
       AND    p.plan_name   = :PARAM_PLAN_YYYYMMDD
       AND   (:PARAM_PLAN_TYPE = '''' OR pd.plan_type = :PARAM_PLAN_TYPE)
       AND   (:PARAM_PLAN_SEQ  = '''' OR pd.plan_seq  = :PARAM_PLAN_SEQ)
      ) pl
WHERE  a.master_id = pl.master_id
AND    a.plan_id   = pl.eng_plan_id
', 'Y', 'Y', 'blueeos', TO_DATE('2019-06-18 11:08:03','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (94, '-', 'FP result(P5200)', '생산 계획/실적(P5200)', 'SELECT PLAN_WEEK
