 AND (:PARAM_MODEL = '''' OR MODEL = :PARAM_MODEL)', 'Y', 'Y', 'blueeos', TO_DATE('2022-05-23 13:56:13','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
