AND A.BOD_TYPE = (CASE WHEN :PARAM_BOD_TYPE = '''' THEN A.BOD_TYPE ELSE :PARAM_BOD_TYPE END)', 'Y', 'Y', 'sclee.lee', TO_DATE('2022-06-07 09:59:11','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (96, '40', 'Allo target 점검', 'Allo target 점검', TO_CLOB('/*
ALLO TARGET
OPERATION GROUP : CELL
TYPE : PLAN
*/

SELECT NVL(C.NICK_NAME, A.ITEM_ID) "NICK NAME", A.ITEM_ID MODEL, ''1. ALLO TARGET'' LV1, ''ALLO(CELL)'' LV2, SUM(A.QTY) QTY, A.YYYYMM
FROM SCP_ANL_ALLO_TARGET A
INNER JOIN (
            SELECT A.DIVISION_ID, A.MODEL_ID, A.OPERATION_GROUP_ID, A.CHILD_ITEM_ID, A.ACCUMULATED_CHILD_QTY, ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.MODEL_ID, A.OPERATION_GROUP_ID ORDER BY A.PLANT_ID ASC) RN
            FROM   SCM_MST_MODEL_FINAL_ITEM_BOM_V A
            WHERE  1=1
            AND    A.DIVISION_ID = ''40''
            AND    A.OPERATION_GROUP_ID IN (''A'')
           ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.MODEL_ID
LEFT JOIN (
           SELECT DIVISION_ID
                 ,ITEM_ID
                 ,NICK_NAME
           FROM   SCP_MST_FINAL_ITEM
           WHERE  DIVISION_ID = ''40''
          ) C ON A.DIVISION_ID = C.DIVISION_ID AND A.ITEM_ID = C.ITEM_ID
WHERE 1=1
AND A.DIVISION_ID = ''40''
AND A.ITEM_ID LIKE ''MCC%''
AND A.CUTOFF_YYYYMMDD = :PARAM_PLAN_DATE
AND A.TYPE = ''PLAN''
AND A.QTY > 0
AND B.RN = 1
GROUP BY NVL(C.NICK_NAME, A.ITEM_ID), A.ITEM_ID, A.YYYYMM

UNION ALL

/*
SHIPMENT PLAN SEMI
OPERATION GROUP : CELL
MEASURE : SHIP PLAN
PLAN TYPE : FN
*/

SELECT NVL(C.NICK_NAME, A.ITEM_ID) "NICK NAME", A.ITEM_ID MODEL, ''1. ALLO TARGET'' LV1, ''ALLO(PACK)'' LV2, SUM(A.QTY) QTY, SUBSTR(A.YYYYMMDD, 1, 6) YYYYMM
FROM SCP_ANL_SHIPMENT_PLAN_SEMI A
INNER JOIN (
            SELECT A.DIVISION_ID, A.MODEL_ID, A.OPERATION_GROUP_ID, A.CHILD_ITEM_ID, A.ACCUMULATED_CHILD_QTY, ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.MODEL_ID, A.OPERATION_GROUP_ID ORDER BY A.PLANT_ID ASC) RN
            FROM   SCM_MST_MODEL_FINAL_ITEM_BOM_V A
            WHERE  1=1
            AND    A.DIVISION_ID = ''40''
            AND    A.OPERATION_GROUP_ID IN (''A'')
           ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.MODEL_ID
LEFT JOIN (
           SELECT DIVISION_ID
                 ,ITEM_ID
                 ,NICK_NAME
           FROM   SCP_MST_FINAL_ITEM
           WHERE  DIVISION_ID = ''40''
          ) C ON A.DIVISION_ID = C.DIVISION_ID AND A.ITEM_ID = C.ITEM_ID
WHERE 1=1
AND A.DIVISION_ID = ''40''
AND A.ITEM_ID LIKE ''MCC%''
AND A.PLAN_START_YYYYMMDD = :PARAM_PLAN_DATE
AND A.MEASURE = ''SHIP_REQ''
AND A.PLAN_TYPE = ''FN''
AND A.QTY > 0
AND B.RN = 1
GROUP BY NVL(C.NICK_NAME, A.ITEM_ID), A.ITEM_ID, SUBSTR(A.YYYYMMDD, 1, 6)

UNION ALL

/*
SHIPMENT PLAN FG
OPERATION GROUP : PACK
MEASURE : MKT FCST
PLAN TYPE : FN
※PACK의 MKT FCST를 CELL로 환산하여 CELL기준 수량으로 표시
*/

SELECT NVL(C.NICK_NAME, B.CHILD_ITEM_ID) "NICK NAME", B.CHILD_ITEM_ID MODEL, ''2. MKT FCST'' LV1, ''PACK'' LV2, SUM(A.QTY * NVL(B.ACCUMULATED_CHILD_QTY, 1)) QTY, SUBSTR(A.YYYYMMDD, 1, 6) YYYYMM
FROM SCP_ANL_SHIPMENT_PLAN_FG A
INNER JOIN (
            SELECT A.DIVISION_ID, A.MODEL_ID, A.OPERATION_GROUP_ID, A.CHILD_ITEM_ID, A.ACCUMULATED_CHILD_QTY, ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.MODEL_ID, A.OPERATION_GROUP_ID ORDER BY A.PLANT_ID ASC) RN
            FROM   SCM_MST_MODEL_FINAL_ITEM_BOM_V A
            WHERE  1=1
            AND    A.DIVISION_ID = ''40''
            AND    A.OPERATION_GROUP_ID IN (''A'')
           ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.MODEL_ID
LEFT JOIN (
           SELECT DIVISION_ID
                 ,ITEM_ID
                 ,NICK_NAME
           FROM   SCP_MST_FINAL_ITEM
           WHERE  DIVISION_ID = ''40''
          ) C ON B.DIVISION_ID = C.DIVISION_ID AND B.CHILD_ITEM_ID = C.ITEM_ID
WHERE 1=1
AND A.DIVISION_ID = ''40''
AND A.PLAN_START_YYYYMMDD = :PARAM_PLAN_DATE
AND A.MEASURE = ''MKT_FCST''
AND A.PLAN_TYPE = ''FN''
AND A.BIZ_TYPE = ''P''
AND A.QTY > 0
AND B.RN = 1
AND B.CHILD_ITEM_ID LIKE ''MCC%''
GROUP BY NVL(C.NICK_NAME, B.CHILD_ITEM_ID), B.CHILD_ITEM_ID, SUBSTR(A.YYYYMMDD, 1, 6)

UNION ALL

/*
SHIPMENT PLAN FG
OPERATION GROUP : CELL
MEASURE : MKT FCST
PLAN TYPE : FN
') || TO_CLOB('*/

SELECT NVL(C.NICK_NAME, A.ITEM_ID) "NICK NAME", A.ITEM_ID MODEL, ''2. MKT FCST'' LV1, ''CELL'' LV2, SUM(A.QTY) QTY, SUBSTR(A.YYYYMMDD, 1, 6) YYYYMM
