SELECT NVL(C.NICK_NAME, A.ITEM_ID) "NICK NAME", A.ITEM_ID MODEL, ''3. SHIP.REQ'' LV1, ''PACK'' LV2, SUM(A.QTY) QTY, SUBSTR(A.YYYYMMDD, 1, 6) YYYYMM
