SELECT NVL(B.NICK_NAME, A.ITEM_ID) "NICK NAME", A.ITEM_ID MODE') || TO_CLOB('L, ''4. PROD.PLAN'' LV1, ''FN'' LV2, SUM(ROUND(A.QTY, 0)) QTY, SUBSTR(A.YYYYMMDD, 1, 6) YYYYMM
