                 ,NICK_NAME
           FROM   SCP_MST_FINAL_ITEM
           WHERE  DIVISION_ID = ''40''
          ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
WHERE 1=1
AND A.DIVISION_ID = ''40''
AND A.PLAN_START_YYYYMMDD = :PARAM_PLAN_DATE
AND A.YYYYMMDD BETWEEN :PARAM_PLAN_DATE AND /*FORMAT_NEEDS_TO_CHAR_FMT_REVIEW*/FORMAT((CAST(:PARAM_PLAN_DATE AS DATETIME)) + (52)*7 - 1, ''YYYYMMDD'')
AND A.MEASURE = ''SHIP_PLAN''
AND A.PLAN_TYPE = ''FN''
AND A.OPERATION_GROUP = ''A''
AND A.QTY > 0
AND A.SEQ = ''1''
AND A.ITEM_ID LIKE ''MCC%''
GROUP BY NVL(B.NICK_NAME, A.ITEM_ID), A.ITEM_ID, SUBSTR(A.YYYYMMDD, 1, 6)


UNION ALL

/*
SHIPMENT PLAN SEMI
OPERATION GROUP : CELL
MEASURE : SHIP_PLAN
PLAN TYPE : TE
*/

SELECT NVL(B.NICK_NAME, A.ITEM_ID) "NICK NAME", A.ITEM_ID MODEL, ''6. SHIP.PLAN SEMI'' LV1, ''TE'' LV2, SUM(ROUND(A.QTY, 0)) QTY, SUBSTR(A.YYYYMMDD, 1, 6) YYYYMM
FROM SCP_ANL_SHIPMENT_PLAN_SEMI A
LEFT JOIN (
           SELECT DIVISION_ID
                 ,ITEM_ID
                 ,NICK_NAME
           FROM   SCP_MST_FINAL_ITEM
           WHERE  DIVISION_ID = ''40''
          ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
WHERE 1=1
AND A.DIVISION_ID = ''40''
AND A.PLAN_START_YYYYMMDD = :PARAM_PLAN_DATE
AND A.YYYYMMDD BETWEEN :PARAM_PLAN_DATE AND /*FORMAT_NEEDS_TO_CHAR_FMT_REVIEW*/FORMAT((CAST(:PARAM_PLAN_DATE AS DATETIME)) + (52)*7 - 1, ''YYYYMMDD'')
AND A.MEASURE = ''SHIP_PLAN''
AND A.PLAN_TYPE = ''TE''
AND A.OPERATION_GROUP = ''A''
AND A.QTY > 0
AND A.SEQ = ''1''
AND A.ITEM_ID LIKE ''MCC%''
GROUP BY NVL(B.NICK_NAME, A.ITEM_ID), A.ITEM_ID, SUBSTR(A.YYYYMMDD, 1, 6)
'), 'Y', 'Y', 'sclee.lee', TO_DATE('2022-06-03 10:15:56','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (97, '-', 'Engine Intransit Incoterms', '엔진 해상재고 Incoterms 변경 건 확인', 'SELECT INT.DIVISION_ID
     , P.PLAN_START_YYYYMMDD
     , P.PLAN_TYPE
     , P.PLAN_SEQ	 
     , CASE WHEN INT.INCOTERMS <> INT.ATTRIBUTE1 THEN ''Y'' ELSE ''N'' END AS INC_DIFF
     , INT.ORG_TO_SCM_SITE_ID AS SCM_SITE_ID 
	 , INT.ITEM_ID
	 , INT.ETA_DATE
	 , INT.INCOTERMS
	 , INT.ATTRIBUTE1 AS ORG_INCOTERMS
	 , SUM(INT.DELIVERY_QTY) AS DELIVERY_QTY
FROM   SCP_ENG_INTRANSITSHPMNT_I_SN INT
       JOIN SCP_PLAN_VERSION_V P
	   ON  INT.DIVISION_ID = P.DIVISION_ID
	   AND INT.PLAN_ID     = P.PLAN_ID
	   AND INT.PLAN_TYPE   = P.PLAN_TYPE
	   AND INT.PLAN_SEQ    = P.PLAN_SEQ
WHERE  P.DIVISION_ID         = :PARAM_DIVISION_ID
AND    P.PLAN_START_YYYYMMDD = :PARAM_PLAN_START_YYYYMMDD
AND    P.PLAN_TYPE           = :PARAM_PLAN_TYPE
AND    P.PLAN_SEQ            = (CASE WHEN :PARAM_PLAN_SEQ = '''' THEN P.PLAN_SEQ ELSE :PARAM_PLAN_SEQ END)
GROUP BY INT.DIVISION_ID, P.PLAN_START_YYYYMMDD, P.PLAN_TYPE, P.PLAN_SEQ
       , INT.ORG_TO_SCM_SITE_ID, INT.ITEM_ID, INT.INCOTERMS, INT.ETA_DATE, INT.ATTRIBUTE1
', 'Y', 'Y', 'blueeos', TO_DATE('2022-07-13 15:42:52','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (61, '-', 'Production Plan', 'SCP Production Plan', 'SELECT a.division_id, a.plan_start_yyyymmdd, a.plan_type, a.seq
     , a.operation_group, a.scm_site_id, a.line_id
     , a.item_id, b.nick_name
     , a.operation_id, a.measure
     , a.yyyymmdd, a.qty
FROM scp_anl_production_plan a
   , scp_mst_final_item      b
   , (
      SELECT p.division_id, p.plan_name, d.plan_type, d.plan_seq
      FROM  scm_mst_plan        p
          , scm_mst_plan_detail d
      WHERE p.division_id  = d.division_id
      AND   p.plan_id      = d.plan_id
      AND   p.plan_cycle   = ''WEEKLY''
      AND   d.confirm_flag = ''Y''
     ) c 
WHERE a.division_id        = :PARAM_DIVISION_ID
AND a.plan_start_yyyymmdd >= :PARAM_FROM_PLAN_NAME
AND a.plan_start_yyyymmdd <= :PARAM_TO_PLAN_NAME
AND (:PARAM_SCM_SITE_ID    = '''' OR a.scm_site_id = :PARAM_SCM_SITE_ID)
AND (:PARAM_ITEM_ID        = '''' OR a.item_id     = :PARAM_ITEM_ID)
AND (:PARAM_NICK_NAME      = '''' OR b.nick_name LIKE ''%'' + :PARAM_NICK_NAME || ''%'')
AND a.plan_type            = ''FN''
AND a.measure              = ''PROD_PLAN_AMEND''
AND a.qty                 <> 0
AND a.division_id          = b.division_id
AND a.item_id              = b.item_id
AND a.division_id          = c.division_id
AND a.plan_start_yyyymmdd  = c.plan_name
AND a.plan_type            = c.plan_type
AND a.seq                  = c.plan_seq


', 'Y', 'Y', 'blueeos', TO_DATE('2020-03-04 15:19:43','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (62, '-', 'INTRANSIT_V', '해상재고 정보(SCP Plan용)', 'SELECT A.RESULT_DATE
     , A.RESULT_TYPE
     , L.SEGMENT2 AS RESULT_NAME
     , A.COMPANY_ID
     , A.DIVISION_ID
     , A.PLANT_ID 
     , A.PROJECT_CODE
     , A.ITEM_ID
     , A.PLANT_ISSUE_DATE
     , A.INCOTERMS 
     , A.FCST_TYPE 
     , A.CUSTOMER_CODE
     , A.SHIPTO_CODE
     , A.FROM_SCM_SITE_ID
     , A.TO_SCM_SITE_ID 
     , A.SITE_TYPE
     , A.DELIVERY_QTY
     , A.UOM
     , A.TRANSPORT_MODE 
     , A.SHIPPING_DATE
     , A.POL
     , A.POL_ATD_DATE 
     , A.POD
     , A.POD_ETA_DATE
     , A.POD_ATA_DATE
     , A.POD_ETD_DATE
     , A.POD_ATD_DATE 
     , A.F_DEST_PORT_CODE
     , A.F_DEST_ETA_DATE
     , A.F_DEST_ATA_DATE 
     , A.ETA_DATE
     , A.FINAL_INCOTERMS 
     , A.FINAL_SOLDTO_CODE
FROM   SCM_DNM_INTRANSIT_V A

LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
ON  A.RESULT_TYPE = L.SEGMENT1
AND L.LOOKUP_TYPE = ''SHIPMENT_RESULT_TYPE''
AND L.VALID_YN    = ''Y''

WHERE  A.DIVISION_ID = :PARAM_DIVISION_ID
AND    A.RESULT_DATE = :PARAM_RESULT_DATE
AND   (:PARAM_RESULT_TYPE      = '''' OR A.RESULT_TYPE      = :PARAM_RESULT_TYPE)
AND   (:PARAM_ITEM_ID          = '''' OR A.ITEM_ID          = :PARAM_ITEM_ID)
AND   (:PARAM_FROM_SCM_SITE_ID = '''' OR A.FROM_SCM_SITE_ID = :PARAM_FROM_SCM_SITE_ID)
AND   (:PARAM_TO_SCM_SITE_ID   = '''' OR A.TO_SCM_SITE_ID   = :PARAM_TO_SCM_SITE_ID)
', 'Y', 'Y', 'blueeos', TO_DATE('2020-03-05 09:38:51','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:41','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (64, '-', '사용자 ID/영문명/부서정보 확인', 'GSCM에 등록된 전체 사용자임 / F5(Find) 전체조회후 필터기능으로 검색', 'SELECT B.USER_ID, B.USER_NAME, B.USER_NAME_EN, B.DEPT_ID, C.DEPT_NAME_KO 
	FROM SCM_MST_SSO_USER_INFO B
		INNER JOIN SCM_MST_SSO_DEPT_INFO C
			ON B.DEPT_ID = C.DEPT_ID
		INNER JOIN  (SELECT DISTINCT Dept_ID
					  FROM LGCE_SCMPROD.TB_FX_User) D
			ON C.DEPT_ID = D.Dept_ID
	WHERE isnumeric (SUBSTR(C.DEPT_ID,1,2)) = 1 --(''0''이면 문자 ''1''이면 숫자) 스텝 부서는 제외
', 'Y', 'Y', 'songkeeho', TO_DATE('2020-04-16 09:34:56','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:18:13','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (65, '-', 'CUSTOMER_CONSIGN', '고객위탁재고', '
SELECT
	CONS.COMPANY_ID
      ,CONS.DIVISION_ID
      ,CONS.SITE_ID
      ,CONS.PLANT_ID
      ,CONS.ITEM_ID
      ,CONS.RESULT_DATE
      ,CONS.ITEM_NAME
      ,CONS.CUSTOMER_CODE
      ,CONS.CUSTOMER_NAME
      ,CONS.QTY
      ,CONS.UOM
      ,CONS.SCM_SITE_ID
      ,CONS.VALID_YN
      ,CONS.ORIGIN_ITEM_ID
  FROM SCM_DNM_STOCK_CUSTOMER_CONSIGN CONS
 -- LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LOOK
--       ON CONS.CUSTOMER_CODE = LOOK.SEGMENT1
--	   AND LOOK.VALID_YN = ''Y''
--	   AND LOOK.LOOKUP_TYPE = ''VMI_SCM_SITE''
WHERE 1  = 1 
 AND CONS.DIVISION_ID = :PARAM_DIVISION_ID
 AND CONS.RESULT_DATE = :PARAM_RESULT_DATE
 

', 'Y', 'Y', 'attackgo', TO_DATE('2020-05-11 20:08:35','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:41','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (66, '-', 'Production Plan Comparison', '생산계획비교', 'SELECT --TOP 10 
	   D.PLAN_Separation
 	 , D.DIVISION_ID
	 , D.PLAN_START_YYYYMMDD
	 , D.PLAN_TYPE
	 , D.SEQ
     , D.OPERATION_GROUP
	 , D.SCM_SITE_ID
	 , D.LINE_ID
     , D.ITEM_ID
	 , D.NICK_NAME
	 , SUBSTR(D.YYYYMMDD, 1, 4) AS ''PLAN_YEAR''
	 , SUBSTR(D.YYYYMMDD, 1, 6) AS ''PLAN_MONTH''
     , D.OPERATION_ID
	 , D.MEASURE
     --, D.YYYYMMDD
	 , SUM(D.QTY) QTY
	 FROM
	 (
SELECT
	  ''A'' AS ''PLAN_Separation''
	 , A.DIVISION_ID
	 , A.PLAN_START_YYYYMMDD
	 , A.PLAN_TYPE
	 , A.SEQ
     , A.OPERATION_GROUP
	 , A.SCM_SITE_ID
	 , A.LINE_ID
     , A.ITEM_ID
	 , B.NICK_NAME
     , A.OPERATION_ID
	 , A.MEASURE
     , A.YYYYMMDD
	 , A.QTY
FROM SCP_ANL_PRODUCTION_PLAN A
   , SCP_MST_FINAL_ITEM      B
   , (
      SELECT P.DIVISION_ID, P.PLAN_NAME, D.PLAN_TYPE, D.PLAN_SEQ
      FROM  SCM_MST_PLAN        P
          , SCM_MST_PLAN_DETAIL D
      WHERE P.DIVISION_ID  = D.DIVISION_ID
      AND   P.PLAN_ID      = D.PLAN_ID
      AND   P.PLAN_CYCLE   = ''WEEKLY''
      AND   D.CONFIRM_FLAG = ''Y''
     ) C 
WHERE 1 = 1 
AND A.DIVISION_ID        = :PARAM_DIVISION_ID
AND A.PLAN_START_YYYYMMDD = :PARAM_A_PLAN_NAME
AND (:PARAM_SCM_SITE_ID    = '''' OR A.SCM_SITE_ID = :PARAM_SCM_SITE_ID)
AND (:PARAM_ITEM_ID        = '''' OR A.ITEM_ID     = :PARAM_ITEM_ID)
AND (:PARAM_NICK_NAME      = '''' OR B.NICK_NAME LIKE ''%'' + :PARAM_NICK_NAME || ''%'')
AND A.PLAN_TYPE            = :PARAM_A_PLAN_TYPE
AND A.MEASURE              = ''PROD_PLAN_AMEND''
AND A.QTY                 <> 0
AND A.DIVISION_ID          = B.DIVISION_ID
AND A.ITEM_ID              = B.ITEM_ID
AND A.DIVISION_ID          = C.DIVISION_ID
AND A.PLAN_START_YYYYMMDD  = C.PLAN_NAME
AND A.PLAN_TYPE            = C.PLAN_TYPE
AND A.SEQ                  = C.PLAN_SEQ

UNION ALL 

SELECT
	  ''B'' AS ''PLAN_Separation''
	 , A.DIVISION_ID
	 , A.PLAN_START_YYYYMMDD
	 , A.PLAN_TYPE
	 , A.SEQ
     , A.OPERATION_GROUP
	 , A.SCM_SITE_ID
	 , A.LINE_ID
     , A.ITEM_ID
	 , B.NICK_NAME
     , A.OPERATION_ID
	 , A.MEASURE
     , A.YYYYMMDD
	 , A.QTY
FROM SCP_ANL_PRODUCTION_PLAN A
   , SCP_MST_FINAL_ITEM      B
   , (
      SELECT P.DIVISION_ID, P.PLAN_NAME, D.PLAN_TYPE, D.PLAN_SEQ
      FROM  SCM_MST_PLAN        P
          , SCM_MST_PLAN_DETAIL D
      WHERE P.DIVISION_ID  = D.DIVISION_ID
      AND   P.PLAN_ID      = D.PLAN_ID
      AND   P.PLAN_CYCLE   = ''WEEKLY''
      AND   D.CONFIRM_FLAG = ''Y''
     ) C 
WHERE 1 = 1 
AND A.DIVISION_ID        = :PARAM_DIVISION_ID
AND A.PLAN_START_YYYYMMDD = :PARAM_B_PLAN_NAME
AND (:PARAM_SCM_SITE_ID    = '''' OR A.SCM_SITE_ID = :PARAM_SCM_SITE_ID)
AND (:PARAM_ITEM_ID        = '''' OR A.ITEM_ID     = :PARAM_ITEM_ID)
AND (:PARAM_NICK_NAME      = '''' OR B.NICK_NAME LIKE ''%'' + :PARAM_NICK_NAME || ''%'')
AND A.PLAN_TYPE            = :PARAM_B_PLAN_TYPE
AND A.MEASURE              = ''PROD_PLAN_AMEND''
AND A.QTY                 <> 0
AND A.DIVISION_ID          = B.DIVISION_ID
AND A.ITEM_ID              = B.ITEM_ID
AND A.DIVISION_ID          = C.DIVISION_ID
AND A.PLAN_START_YYYYMMDD  = C.PLAN_NAME
AND A.PLAN_TYPE            = C.PLAN_TYPE
AND A.SEQ                  = C.PLAN_SEQ

)D
GROUP BY 
	   D.PLAN_Separation
 	 , D.DIVISION_ID
	 , D.PLAN_START_YYYYMMDD
	 , D.PLAN_TYPE
	 , D.SEQ
     , D.OPERATION_GROUP
	 , D.SCM_SITE_ID
	 , D.LINE_ID
     , D.ITEM_ID
	 , D.NICK_NAME
     , D.OPERATION_ID
	 , D.MEASURE
     , SUBSTR(D.YYYYMMDD, 1, 4)
	 , SUBSTR(D.YYYYMMDD, 1, 6)
', 'Y', 'Y', 'attackgo', TO_DATE('2020-05-22 10:49:33','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (67, '-', 'ESS (G540) Sales Result', 'ESS (G540) Sales Result', '--[C20200514-000253] GSCM-DQ 해외법인 LGCAU(G540) 실적확인기능 추가 요청 
SELECT A.COMPANY_ID
      ,DIVISION_ID
      ,A.RESULT_YYYYMM
      ,SALES_POSTING_DATE
      ,ITEM_TYPE
      ,CUSTOMER_CODE
      ,CUSTOMER_NAME
      ,CURRENCY
      ,SALES_AMOUNT_FOR AS AMT_LOCAL
      ,SALES_AMOUNT_SUM AS AMT_KRW
      ,DOC_CURRENCY AS CURRENCY_AUD
      ,DOC_AMT_FOR AS AMT_LOCAL_AUD
      ,DOC_AMT_KRW AS AMT_KRW_AUD
      ,UOM
      ,SALES_QTY
      ,ITEM_ID
      ,SHIPTO_CODE
      ,SHIPTO_DESCRIPTION
      ,COUNTRY
      ,COUNTRY_NAME
      ,SHIPTO_CITY_NAME
      ,SHIPTO_ZONE_CODE
      ,SHIPTO_ZONE_NAME
      ,RBU_CUSTOMER
      ,INCOTERMS
  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R A
      ,(
		SELECT COMPANY_ID, RESULT_YYYYMM, MAX(IFSEQNO) IFSEQNO
		  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R
		 WHERE DIVISION_ID = ''82''
		   AND COMPANY_ID = ''G540''
		 GROUP BY COMPANY_ID, RESULT_YYYYMM
	   ) B
 WHERE A.IFSEQNO = B.IFSEQNO
   AND A.RESULT_YYYYMM = B.RESULT_YYYYMM
   AND A.COMPANY_ID = B.COMPANY_ID
   AND A.SHIPTO_CODE <> ''G540''
   AND A.RESULT_YYYYMM = :PARAM1
   AND A.DIVISION_ID = ''82''
   --AND A.COST_ITEM = ''''', 'Y', 'Y', 'choiya2', TO_DATE('2020-06-02 11:15:14','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (68, '-', 'ESS REQ, CIQ FCST By Current', 'ESS 출하요청, CIQ FCST By Current', TO_CLOB('

SELECT DT.DIVISION_ID , DT.DEPT_NAME_KO , DT.SOLDTO_CUSTOMER , DT.SCM_SITE_ID , DT.PLANT_SITE_ID
     , DT.PROJECT_CODE , DT.PROJECT_NAME , DT.PROJECT_OWNER ,DT.PROJECT_OWNER_KO, DT.ITEM_ID
     , DT.ITEM_NAME , DT.FCST_TYPE , DT.INCOTERMS , DT.DUE_DATE_MKT , DT.QTY , DT.ENERGY , DT.CELL_QUANTITY
     , DT.BOD_ID , DT.DAYS_MON, DT.DAYS_TUE, DT.DAYS_WED, DT.DAYS_THU, DT.DAYS_FRI, DT.DAYS_SAT, DT.DAYS_SUN
     , DT.LT_TOTAL, DT.OSP_LT
   , TO_CHAR(DATEADD(DD, (CASE WHEN DT.INCOTERMS IN (''A01'',''Z01'',''Z04'',''EXW'',''FCA'',''FAS'')
                                       THEN 0 ELSE DT.VOYAGE_CHECK_LT END + DT.SHIP_LT_TOTAL) * -1, DT.SHIP_PLAN_CAL),112)  AS SHIP_REQ_DATE
   , TO_CHAR(DATEADD(DD, (CASE WHEN DT.INCOTERMS IN (''A01'',''Z01'',''Z04'',''EXW'',''FCA'',''FAS'')
	                                THEN 0 ELSE DT.VOYAGE_CHECK_LT END + DT.SHIP_LT_TOTAL + DT.OSP_LT) * -1, DT.SHIP_PLAN_CAL),112)  AS CIQ_DATE
FROM   (
        SELECT 
               A.DIVISION_ID , A.DEPT_NAME_KO , A.SOLDTO_CUSTOMER , A.SCM_SITE_ID , A.PLANT_SITE_ID
             , A.PROJECT_CODE , A.PROJECT_NAME , A.PROJECT_OWNER ,A.PROJECT_OWNER_KO, A.ITEM_ID
             , A.ITEM_NAME , A.FCST_TYPE , A.INCOTERMS , A.DUE_DATE_MKT , A.QTY , A.ENERGY , A.CELL_QUANTITY
             , A.BOD_ID , A.DAYS_MON, A.DAYS_TUE, A.DAYS_WED, A.DAYS_THU, A.DAYS_FRI, A.DAYS_SAT, A.DAYS_SUN
             , A.LT_DEPARTURE_INLAND , A.LT_WAIT_SHIPPING , A.LT_VOYAGE , A.LT_LAY_OFF_CLEARANCE
             , A.LT_ARRIVAL_INLAND, A.SHIP_LT_TOTAL_ORIGIN , A.SHIP_LT_TOTAL , A.LT_TOTAL
             , A.LT_INLAND , A.GAP_LT, NVL(LT.LT_DAY,0) AS OSP_LT
             , (CONVERT(DATE, A.DUE_DATE_MKT)) + (A.GAP_LT * -1) AS SHIP_PLAN_CAL
             , TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) AS DAY_IDX
             , CASE --  ① 일요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 1
                    THEN CASE WHEN A.DAYS_SUN = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_SAT = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_FRI = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_THU = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_WED = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_TUE = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_MON = ''Y'' THEN 6 ELSE 0 
                         END END END END END END END 
                    --  ② 월요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 2
                    THEN CASE WHEN A.DAYS_MON = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_SUN = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_SAT = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_FRI = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_THU = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_WED = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_TUE = ''Y'' THEN 6 ELSE 0 
                         END END END END END END END 
                    --  ③ 화요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 3
                    THEN CASE WHEN A.DAYS_TUE = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_MON = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_SUN = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_SAT = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_FRI = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_THU = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_WED = ''Y'' THEN 6 ELSE 0 
                         END END END END END END END 
                    --  ④ 수요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT),') || TO_CLOB(' ''D'')) + (A.GAP_LT * -1)) = 4
                    THEN CASE WHEN A.DAYS_WED = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_TUE = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_MON = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_SUN = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_SAT = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_FRI = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_THU = ''Y'' THEN 6 ELSE 0 
                    END END END END END END END 
                    --  ⑤ 목요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 5
                    THEN CASE WHEN A.DAYS_THU = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_WED = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_TUE = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_MON = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_SUN = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_SAT = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_FRI = ''Y'' THEN 6 ELSE 0 
                    END END END END END END END 
                    --  ⑥ 금요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 6
                    THEN CASE WHEN A.DAYS_FRI = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_THU = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_WED = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_TUE = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_MON = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_SUN = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_SAT = ''Y'' THEN 6 ELSE 0 
                    END END END END END END END 
                    --  ⑦ 토요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 7
                    THEN CASE WHEN A.DAYS_SAT = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_FRI = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_THU = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_WED = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_TUE = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_MON = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_SUN = ''Y'' THEN 6 ELSE 0 
                    END END END END END END END 
                    ELSE 0
               END  AS VOYAGE_CHECK_LT
      , A.BOD_VALID_YN

        FROM   (
 
                SELECT MK.DIVISION_ID , MK.DEPT_NAME_KO , MK.SOLDTO_CUSTOMER , MK.SCM_SITE_ID , MK.PLANT_SITE_ID
                     , MK.PROJECT_CODE , MK.PROJECT_NAME , MK.PROJECT_OWNER ,MK.PROJECT_OWNER_KO, MK.ITEM_ID
                     , MK.ITEM_NAME , MK.FCST_TYPE , MK.INCOTERMS , MK.DUE_DATE_MKT , MK.QTY , MK.ENERGY , MK.CELL_QUANTITY
                     , BD.BOD_ID , BD.DAYS_MON, BD.DAYS_TUE, BD.DAYS_WED, BD.DAYS_THU, BD.DAYS_FRI, BD.DAYS_SAT, BD.DAYS_SUN
                     , BD.LT_DEPARTURE_INLAND , BD.LT_WAIT_SHIPPING , BD.LT_VOYAGE , BD.LT_LAY_OFF_CLEARANCE
                     , BD.LT_ARRIVAL_INLAND, BD.SHIP_LT_TOTAL_ORIGIN , BD.SHIP_LT_TOTAL , BD.LT_TOTAL
                     , BD.LT_INLAND , BD.GAP_LT, BD.BOD_VALID_YN
                FROM   (
                        SELECT A.DIVISION_ID , C.DEPT_NAME_KO , B.SOLDTO_CUSTOMER , A.SCM_SITE_ID , PR.PLANT_SITE_ID
                             , A.PROJECT_CODE , D.PROJECT_NAME , D.PROJECT_OWNER
                             , (
                                SELECT Z.USER_NAME
                                FROM   SCM_MST_SSO_USER_INFO Z
                                WHERE  Z.USER_ID = D.PROJECT_OWNER
                               ) AS PROJECT_OWNER_KO
                             , A.ITEM_ID , IT.ITEM_NAME , A.FCST_TYPE , A.INCOTERMS , A.YYYYMMDD  AS DUE_DATE_MKT
                             , A.QTY , IT.ENERGE ') || TO_CLOB(' AS ENERGY , IT.CELL_QUANTITY
                        FROM   DM_PLN_MKT_FCST A
                               LEFT OUTER JOIN
                               (
                                SELECT PR.DIVISION_ID, PR.PLANT_SITE_ID, PR.ITEM_ID
                                FROM   SCM_MST_SITE_ITEM_PRIORITY PR
                                WHERE  DIVISION_ID = ''82''
                                AND    VALID_YN = ''Y''
                                --AND    TO_CHAR(SYSDATE, ''YYYYMMDD'') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD
                                AND TO_YYYYMMDD >= TO_CHAR(SYSDATE, ''YYYYMMDD'')
                                AND    (PLANT_SITE_ID LIKE ''%-P'' OR PLANT_SITE_ID LIKE ''%-A'')
                                GROUP  BY PR.DIVISION_ID, PR.PLANT_SITE_ID, PR.ITEM_ID
                               ) PR
                               ON  A.DIVISION_ID = PR.DIVISION_ID
                               AND A.ITEM_ID     = PR.ITEM_ID
                             , SCM_MST_SITE B
                             , SCM_MST_SSO_DEPT_INFO C
                             , SCM_MST_PROJECT D
                             , SCM_MST_SITE E
                             , DM_MST_ITEM_SINGLE_V IT
                        WHERE  A.DIVISION_ID = ''82''
                        AND    A.MEASURE     IN (''MKT_FCST'', ''AS_IN_REQ'')
                        AND    A.DIVISION_ID = B.DIVISION_ID
                        AND    B.VALID_YN = ''Y''
                        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                        AND    B.DEPT_ID = C.DEPT_ID
                        AND    A.PROJECT_CODE = D.PROJECT_CODE
                        AND    A.DIVISION_ID  = E.DIVISION_ID
                        AND    A.SCM_SITE_ID  = E.SCM_SITE_ID
                        AND    A.DIVISION_ID = IT.DIVISION_ID
                        AND    A.ITEM_ID     = IT.ITEM_ID
                        AND    IT.ITEM_TYPE  = ''P''
                        AND    A.QTY         > 0
                        AND    E.VMI_YN      = ''N''
                        AND    A.YYYYMMDD    >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)
                        AND  (:PARAM_ITEM_ID = '''' OR A.ITEM_ID = :PARAM_ITEM_ID)                        
                        AND  (:PARAM_PROJECT_CODE = '''' OR A.PROJECT_CODE = :PARAM_PROJECT_CODE)
                        UNION  ALL

                        SELECT A.DIVISION_ID , C.DEPT_NAME_KO , B.SOLDTO_CUSTOMER , A.SCM_SITE_ID , PR.PLANT_SITE_ID
                             , A.PROJECT_CODE , D.PROJECT_NAME , D.PROJECT_OWNER
                             , (
                                SELECT Z.USER_NAME
                                FROM   SCM_MST_SSO_USER_INFO Z
                                WHERE  Z.USER_ID = D.PROJECT_OWNER
                               ) AS PROJECT_OWNER_KO
                             , A.ITEM_ID , IT.ITEM_NAME , A.FCST_TYPE , A.INCOTERMS , A.YYYYMMDD  AS DUE_DATE_MKT
                             , A.QTY , IT.ENERGE  AS ENERGY , IT.CELL_QUANTITY
                        FROM   DM_PLN_MKT_FCST A
                               LEFT OUTER JOIN
                               (
                                SELECT PR.DIVISION_ID, PR.PLANT_SITE_ID, PR.ITEM_ID
                                FROM   SCM_MST_SITE_ITEM_PRIORITY PR
                                WHERE  DIVISION_ID = ''82''
                                AND    VALID_YN = ''Y''
                                --AND    TO_CHAR(SYSDATE, ''YYYYMMDD'') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD
                                AND TO_YYYYMMDD >= TO_CHAR(SYSDATE, ''YYYYMMDD'')
                                AND    (PLANT_SITE_ID LIKE ''%-P'' OR PLANT_SITE_ID LIKE ''%-A'')
                                GROUP  BY PR.DIVISION_ID, PR.PLANT_SITE_ID, PR.ITEM_ID
                               ) PR
                               ON  A.DIVISION_ID =') || TO_CLOB(' PR.DIVISION_ID
                               AND A.ITEM_ID     = PR.ITEM_ID
                             , SCM_MST_SITE B
                             , SCM_MST_SSO_DEPT_INFO C
                             , SCM_MST_PROJECT D
                             , SCM_MST_SITE E
                             , DM_MST_ITEM_SINGLE_V IT
                        WHERE  A.DIVISION_ID = ''82''
                        AND    A.MEASURE     = ''VMI_IN_REQ''
                        AND    A.DIVISION_ID = B.DIVISION_ID
                        AND    B.VALID_YN = ''Y''
                        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                        AND    B.DEPT_ID = C.DEPT_ID
                        AND    A.PROJECT_CODE = D.PROJECT_CODE
                        AND    A.DIVISION_ID  = E.DIVISION_ID
                        AND    A.SCM_SITE_ID  = E.SCM_SITE_ID
                        AND    A.DIVISION_ID = IT.DIVISION_ID
                        AND    A.ITEM_ID     = IT.ITEM_ID
                        AND    IT.ITEM_TYPE  = ''P''
                        AND    A.QTY         > 0
                        AND    A.YYYYMMDD    >= TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112)
                        AND    E.VMI_YN      = ''Y''                        
                        AND  (:PARAM_ITEM_ID = '''' OR A.ITEM_ID = :PARAM_ITEM_ID)                       
                        AND  (:PARAM_PROJECT_CODE = '''' OR A.PROJECT_CODE = :PARAM_PROJECT_CODE)
                       ) MK
                       LEFT OUTER JOIN 
                       (
                       SELECT DISTINCT
                              A.BOD_ID, A.DIVISION_ID, A.FROM_SITE, A.TO_SITE, A.INCOTERMS, B.ITEM_ID
                            , A.DAYS_MON, A.DAYS_TUE, A.DAYS_WED, A.DAYS_THU, A.DAYS_FRI, A.DAYS_SAT, A.DAYS_SUN
                            , A.LT_DEPARTURE_INLAND, A.LT_WAIT_SHIPPING, A.LT_VOYAGE, A.LT_LAY_OFF_CLEARANCE
                            , A.LT_ARRIVAL_INLAND, A.SHIP_LT_TOTAL_ORIGIN, A.SHIP_LT_TOTAL, A.LT_TOTAL
                            , A.LT_DEPARTURE_INLAND + A.LT_WAIT_SHIPPING AS LT_INLAND
                            , CASE WHEN A.LT_TOTAL <= A.LT_DEPARTURE_INLAND + A.LT_WAIT_SHIPPING
                                   THEN 0
                                   ELSE A.LT_TOTAL - (A.LT_DEPARTURE_INLAND + A.LT_WAIT_SHIPPING)
                              END  AS GAP_LT
                            , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.FROM_SITE, A.TO_SITE, A.INCOTERMS, B.ITEM_ID ORDER BY A.PRIORITY, A.LT_TOTAL DESC, A.BOD_ID) AS BOD_PRIORITY
                            , B.VALID_YN AS BOD_VALID_YN
                       FROM   SCP_MST_BOD_V A
                            , SCP_MST_BOD_ITEM B
                       WHERE  A.DIVISION_ID     = ''82''
                       AND    A.DIVISION_ID     = B.DIVISION_ID
                       AND    A.BOD_ID          = B.BOD_ID
                       AND    A.BOD_VALID_YN    = ''Y''
                       --AND    B.VALID_YN        = ''Y''
                       ) BD
                       ON  MK.DIVISION_ID = BD.DIVISION_ID
                       AND MK.SCM_SITE_ID = BD.TO_SITE
                       AND MK.PLANT_SITE_ID = BD.FROM_SITE
                       AND MK.INCOTERMS     = BD.INCOTERMS
                       AND MK.ITEM_ID       = BD.ITEM_ID
                       AND BD.BOD_PRIORITY  = 1            

               ) A
               LEFT OUTER JOIN
               SCP_MST_OPERATION_LT LT
               ON  A.DIVISION_ID     = LT.DIVISION_ID
               AND A.PLANT_SITE_ID   = LT.SCM_SITE_ID
               AND A.ITEM_ID         = LT.ITEM_ID
               AND LT.LT_OPERATION   = ''OSP_LT''
       ) DT
 WHERE NVL(DT.BOD_VALID_YN,''Y'') = ''Y''
--ORDER  BY 1,3,4,5
'), 'Y', 'Y', 'jsheo', TO_DATE('2020-07-21 10:12:36','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (69, '-', 'ESS REQ, CIQ FCST By Version', 'ESS 출하요청, CIQ FCST By Version', TO_CLOB('

SELECT DT.DIVISION_ID , DT.DEPT_NAME_KO , DT.SOLDTO_CUSTOMER , DT.SCM_SITE_ID , DT.PLANT_SITE_ID
     , DT.PROJECT_CODE , DT.PROJECT_NAME , DT.PROJECT_OWNER ,DT.PROJECT_OWNER_KO, DT.ITEM_ID
     , DT.ITEM_NAME , DT.FCST_TYPE , DT.INCOTERMS , DT.DUE_DATE_MKT , DT.QTY , DT.ENERGY , DT.CELL_QUANTITY
     , DT.BOD_ID , DT.DAYS_MON, DT.DAYS_TUE, DT.DAYS_WED, DT.DAYS_THU, DT.DAYS_FRI, DT.DAYS_SAT, DT.DAYS_SUN
     , DT.LT_TOTAL, DT.OSP_LT, DT.GAP_LT, DT.VOYAGE_CHECK_LT
   , TO_CHAR(DATEADD(DD, (CASE WHEN DT.INCOTERMS IN (''A01'',''Z01'',''Z04'',''EXW'',''FCA'',''FAS'')
                                       THEN 0 ELSE DT.VOYAGE_CHECK_LT END + DT.SHIP_LT_TOTAL) * -1, DT.SHIP_PLAN_CAL),112)  AS SHIP_REQ_DATE
   , TO_CHAR(DATEADD(DD, (CASE WHEN DT.INCOTERMS IN (''A01'',''Z01'',''Z04'',''EXW'',''FCA'',''FAS'')
                                       THEN 0 ELSE DT.VOYAGE_CHECK_LT END + DT.SHIP_LT_TOTAL + DT.OSP_LT) * -1, DT.SHIP_PLAN_CAL),112)  AS CIQ_DATE

FROM   (
        SELECT 
               A.DIVISION_ID , A.DEPT_NAME_KO , A.SOLDTO_CUSTOMER , A.SCM_SITE_ID , A.PLANT_SITE_ID
             , A.PROJECT_CODE , A.PROJECT_NAME , A.PROJECT_OWNER ,A.PROJECT_OWNER_KO, A.ITEM_ID
             , A.ITEM_NAME , A.FCST_TYPE , A.INCOTERMS , A.DUE_DATE_MKT , A.QTY , A.ENERGY , A.CELL_QUANTITY
             , A.BOD_ID , A.DAYS_MON, A.DAYS_TUE, A.DAYS_WED, A.DAYS_THU, A.DAYS_FRI, A.DAYS_SAT, A.DAYS_SUN
             , A.LT_DEPARTURE_INLAND , A.LT_WAIT_SHIPPING , A.LT_VOYAGE , A.LT_LAY_OFF_CLEARANCE
             , A.LT_ARRIVAL_INLAND, A.SHIP_LT_TOTAL_ORIGIN , A.SHIP_LT_TOTAL , A.LT_TOTAL
             , A.LT_INLAND , A.GAP_LT, NVL(LT.LT_DAY,0) AS OSP_LT
             , (CONVERT(DATE, A.DUE_DATE_MKT)) + (A.GAP_LT * -1) AS SHIP_PLAN_CAL
             , TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) AS DAY_IDX
             , CASE --  ① 일요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 1
                    THEN CASE WHEN A.DAYS_SUN = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_SAT = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_FRI = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_THU = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_WED = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_TUE = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_MON = ''Y'' THEN 6 ELSE 0 
                         END END END END END END END 
                    --  ② 월요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 2
                    THEN CASE WHEN A.DAYS_MON = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_SUN = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_SAT = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_FRI = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_THU = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_WED = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_TUE = ''Y'' THEN 6 ELSE 0 
                         END END END END END END END 
                    --  ③ 화요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 3
                    THEN CASE WHEN A.DAYS_TUE = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_MON = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_SUN = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_SAT = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_FRI = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_THU = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_WED = ''Y'' THEN 6 ELSE 0 
                         END END END END END END END 
                    --  ④ 수요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(T') || TO_CLOB('O_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 4
                    THEN CASE WHEN A.DAYS_WED = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_TUE = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_MON = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_SUN = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_SAT = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_FRI = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_THU = ''Y'' THEN 6 ELSE 0 
                    END END END END END END END 
                    --  ⑤ 목요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 5
                    THEN CASE WHEN A.DAYS_THU = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_WED = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_TUE = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_MON = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_SUN = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_SAT = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_FRI = ''Y'' THEN 6 ELSE 0 
                    END END END END END END END 
                    --  ⑥ 금요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 6
                    THEN CASE WHEN A.DAYS_FRI = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_THU = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_WED = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_TUE = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_MON = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_SUN = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_SAT = ''Y'' THEN 6 ELSE 0 
                    END END END END END END END 
                    --  ⑦ 토요일인 경우 --------------------------------------------------------
                    WHEN TO_NUMBER(TO_CHAR((CONVERT(DATE, A.DUE_DATE_MKT), ''D'')) + (A.GAP_LT * -1)) = 7
                    THEN CASE WHEN A.DAYS_SAT = ''Y'' THEN 0 ELSE CASE WHEN A.DAYS_FRI = ''Y'' THEN 1 ELSE 
                         CASE WHEN A.DAYS_THU = ''Y'' THEN 2 ELSE CASE WHEN A.DAYS_WED = ''Y'' THEN 3 ELSE 
                         CASE WHEN A.DAYS_TUE = ''Y'' THEN 4 ELSE CASE WHEN A.DAYS_MON = ''Y'' THEN 5 ELSE 
                         CASE WHEN A.DAYS_SUN = ''Y'' THEN 6 ELSE 0 
                    END END END END END END END 
                    ELSE 0
               END  AS VOYAGE_CHECK_LT
         , A.BOD_VALID_YN
        FROM   (
 
                SELECT MK.DIVISION_ID , MK.DEPT_NAME_KO , MK.SOLDTO_CUSTOMER , MK.SCM_SITE_ID , MK.PLANT_SITE_ID
                     , MK.PROJECT_CODE , MK.PROJECT_NAME , MK.PROJECT_OWNER ,MK.PROJECT_OWNER_KO, MK.ITEM_ID
                     , MK.ITEM_NAME , MK.FCST_TYPE , MK.INCOTERMS , MK.DUE_DATE_MKT , MK.QTY , MK.ENERGY , MK.CELL_QUANTITY
                     , BD.BOD_ID , BD.DAYS_MON, BD.DAYS_TUE, BD.DAYS_WED, BD.DAYS_THU, BD.DAYS_FRI, BD.DAYS_SAT, BD.DAYS_SUN
                     , BD.LT_DEPARTURE_INLAND , BD.LT_WAIT_SHIPPING , BD.LT_VOYAGE , BD.LT_LAY_OFF_CLEARANCE
                     , BD.LT_ARRIVAL_INLAND, BD.SHIP_LT_TOTAL_ORIGIN , BD.SHIP_LT_TOTAL , BD.LT_TOTAL
                     , BD.LT_INLAND , BD.GAP_LT, BD.BOD_VALID_YN
                FROM   (
                        SELECT A.DIVISION_ID , C.DEPT_NAME_KO , B.SOLDTO_CUSTOMER , A.SCM_SITE_ID , PR.PLANT_SITE_ID
                             , A.PROJECT_CODE , D.PROJECT_NAME , D.PROJECT_OWNER
                             , (
                                SELECT Z.USER_NAME
                                FROM   SCM_MST_SSO_USER_INFO Z
                                WHERE  Z.USER_ID = D.PROJECT_OWNER
                               ) AS PROJECT_OWNER_KO
                             , A.ITEM_ID , IT.ITEM_NAME , A.FCST_TYPE , A.INCOTERMS , A.YYYYMMDD  AS DUE_DATE_MKT
         ') || TO_CLOB('                    , A.QTY , IT.ENERGE  AS ENERGY , IT.CELL_QUANTITY
                        FROM   DM_PLN_MKT_FCST_C A
                               LEFT OUTER JOIN
                               (
                                SELECT PR.DIVISION_ID, PR.PLANT_SITE_ID, PR.ITEM_ID
                                FROM   SCM_MST_SITE_ITEM_PRIORITY PR
                                WHERE  DIVISION_ID = ''82''
                                AND    VALID_YN = ''Y''
                                --AND    TO_CHAR(SYSDATE, ''YYYYMMDD'') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD
                                AND TO_YYYYMMDD >= TO_CHAR(SYSDATE, ''YYYYMMDD'')
                                AND    (PLANT_SITE_ID LIKE ''%-P'' OR PLANT_SITE_ID LIKE ''%-A'')
                                GROUP  BY PR.DIVISION_ID, PR.PLANT_SITE_ID, PR.ITEM_ID
                               ) PR
                               ON  A.DIVISION_ID = PR.DIVISION_ID
                               AND A.ITEM_ID     = PR.ITEM_ID
                             , SCM_MST_SITE B
                             , SCM_MST_SSO_DEPT_INFO C
                             , SCM_MST_PROJECT D
                             , SCM_MST_SITE E
                             , DM_MST_ITEM_SINGLE_V IT
                        WHERE  A.DIVISION_ID = ''82''
                        AND    A.VERSION_NO = SUBSTR(:PARAM_VERSION_NO, 1, 18)    
                        AND    A.MEASURE     IN (''MKT_FCST'', ''AS_In_Req'')
                        AND    A.DIVISION_ID = B.DIVISION_ID
                        AND    B.VALID_YN = ''Y''
                        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                        AND    B.DEPT_ID = C.DEPT_ID
                        AND    A.PROJECT_CODE = D.PROJECT_CODE
                        AND    A.DIVISION_ID  = E.DIVISION_ID
                        AND    A.SCM_SITE_ID  = E.SCM_SITE_ID
                        AND    A.DIVISION_ID = IT.DIVISION_ID
                        AND    A.ITEM_ID     = IT.ITEM_ID
                        AND    IT.ITEM_TYPE  = ''P''
                        AND    A.QTY         > 0
                        AND    E.VMI_YN      = ''N''
                        AND    A.YYYYMMDD    >= SUBSTR(TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112), 1, 6 ) + ''01''                   
                        AND  (:PARAM_ITEM_ID = '''' OR A.ITEM_ID = :PARAM_ITEM_ID)                        
                        AND  (:PARAM_PROJECT_CODE = '''' OR A.PROJECT_CODE = :PARAM_PROJECT_CODE)
                        UNION  ALL

                        SELECT A.DIVISION_ID , C.DEPT_NAME_KO , B.SOLDTO_CUSTOMER , A.SCM_SITE_ID , PR.PLANT_SITE_ID
                             , A.PROJECT_CODE , D.PROJECT_NAME , D.PROJECT_OWNER
                             , (
                                SELECT Z.USER_NAME
                                FROM   SCM_MST_SSO_USER_INFO Z
                                WHERE  Z.USER_ID = D.PROJECT_OWNER
                               ) AS PROJECT_OWNER_KO
                             , A.ITEM_ID , IT.ITEM_NAME , A.FCST_TYPE , A.INCOTERMS , A.YYYYMMDD  AS DUE_DATE_MKT
                             , A.QTY , IT.ENERGE  AS ENERGY , IT.CELL_QUANTITY
                        FROM   DM_PLN_MKT_FCST_C A
                               LEFT OUTER JOIN
                               (
                                SELECT PR.DIVISION_ID, PR.PLANT_SITE_ID, PR.ITEM_ID
                                FROM   SCM_MST_SITE_ITEM_PRIORITY PR
                                WHERE  DIVISION_ID = ''82''
                                AND    VALID_YN = ''Y''
                                --AND    TO_CHAR(SYSDATE, ''YYYYMMDD'') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD
                                AND TO_YYYYMMDD >= TO_CHAR(SYSDATE, ''YYYYMMDD'')
                                AND    (PLANT_SITE_ID LIKE ''%-P'' OR PLANT_SITE_ID LIKE ''%-A'')
   ') || TO_CLOB('                             GROUP  BY PR.DIVISION_ID, PR.PLANT_SITE_ID, PR.ITEM_ID
                               ) PR
                               ON  A.DIVISION_ID = PR.DIVISION_ID
                               AND A.ITEM_ID     = PR.ITEM_ID
                             , SCM_MST_SITE B
                             , SCM_MST_SSO_DEPT_INFO C
                             , SCM_MST_PROJECT D
                             , SCM_MST_SITE E
                             , DM_MST_ITEM_SINGLE_V IT
                        WHERE  A.DIVISION_ID = ''82''                        
                        AND    A.VERSION_NO = SUBSTR(:PARAM_VERSION_NO, 1, 18)    
                        AND    A.MEASURE     = ''VMI_In_Req''
                        AND    A.DIVISION_ID = B.DIVISION_ID
                        AND    B.VALID_YN = ''Y''
                        AND    A.SCM_SITE_ID = B.SCM_SITE_ID
                        AND    B.DEPT_ID = C.DEPT_ID
                        AND    A.PROJECT_CODE = D.PROJECT_CODE
                        AND    A.DIVISION_ID  = E.DIVISION_ID
                        AND    A.SCM_SITE_ID  = E.SCM_SITE_ID
                        AND    A.DIVISION_ID = IT.DIVISION_ID
                        AND    A.ITEM_ID     = IT.ITEM_ID
                        AND    IT.ITEM_TYPE  = ''P''
                        AND    A.QTY         > 0
                        AND    A.YYYYMMDD    >= SUBSTR(TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7), 112), 1, 6 ) + ''01''
                        AND    E.VMI_YN      = ''Y''
                        AND  (:PARAM_ITEM_ID = '''' OR A.ITEM_ID = :PARAM_ITEM_ID)                        
                        AND  (:PARAM_PROJECT_CODE = '''' OR A.PROJECT_CODE = :PARAM_PROJECT_CODE)
                       ) MK
                       LEFT OUTER JOIN 
                       (
                       SELECT DISTINCT
                              A.BOD_ID, A.DIVISION_ID, A.FROM_SITE, A.TO_SITE, A.INCOTERMS, B.ITEM_ID
                            , A.DAYS_MON, A.DAYS_TUE, A.DAYS_WED, A.DAYS_THU, A.DAYS_FRI, A.DAYS_SAT, A.DAYS_SUN
                            , A.LT_DEPARTURE_INLAND, A.LT_WAIT_SHIPPING, A.LT_VOYAGE, A.LT_LAY_OFF_CLEARANCE
                            , A.LT_ARRIVAL_INLAND, A.SHIP_LT_TOTAL_ORIGIN, A.SHIP_LT_TOTAL, A.LT_TOTAL
                            , A.LT_DEPARTURE_INLAND + A.LT_WAIT_SHIPPING AS LT_INLAND
                            , CASE WHEN A.LT_TOTAL <= A.LT_DEPARTURE_INLAND + A.LT_WAIT_SHIPPING
                                   THEN 0
                                   ELSE A.LT_TOTAL - (A.LT_DEPARTURE_INLAND + A.LT_WAIT_SHIPPING)
                              END  AS GAP_LT
                            , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.FROM_SITE, A.TO_SITE, A.INCOTERMS, B.ITEM_ID ORDER BY A.PRIORITY, A.LT_TOTAL DESC, A.BOD_ID) AS BOD_PRIORITY
		  , VALID_YN AS BOD_VALID_YN
                       FROM   SCP_MST_BOD_V A
                            , SCP_MST_BOD_ITEM B
                       WHERE  A.DIVISION_ID     = ''82''
                       AND    A.DIVISION_ID     = B.DIVISION_ID
                       AND    A.BOD_ID          = B.BOD_ID
                       AND    A.BOD_VALID_YN    = ''Y''
                       --AND    B.VALID_YN        = ''Y''
                       ) BD
                       ON  MK.DIVISION_ID = BD.DIVISION_ID
                       AND MK.SCM_SITE_ID = BD.TO_SITE
                       AND MK.PLANT_SITE_ID = BD.FROM_SITE
                       AND MK.INCOTERMS     = BD.INCOTERMS
                       AND MK.ITEM_ID       = BD.ITEM_ID
                       AND BD.BOD_PRIORITY  = 1            

               ) A
               LEFT OUTER JOIN
               SCP_MST_OPERATION_LT LT
               ON  A.DIVISION_ID     = LT.DIVISION_ID
               AND A.PLANT_SITE_ID   = LT.SCM_SITE_ID
               AND A.ITEM_ID         = LT.ITEM_ID
 ') || TO_CLOB('              AND LT.LT_OPERATION   = ''OSP_LT''
       ) DT
 WHERE NVL(DT.BOD_VALID_YN,''Y'') = ''Y''
--ORDER  BY 1,3,4,5



'), 'Y', 'Y', 'jsheo', TO_DATE('2020-07-21 10:14:35','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (70, '-', 'SCS_PACKER_PROD_PLAN', 'SCS 대상 Packer 생산 계획', 'SELECT division_id, cutoff_date, scm_sitE_id, item_id, line_id
     , prod_date, prod_qty
     , plan_operation, plan_type, shift
FROM   SCM_DNM_SCS_PROD_PLAN  
