AND  (:PARAM_ITEM_ID     = '''' OR ITEM_ID = :PARAM_ITEM_ID)
', 'Y', 'Y', 'blueeos', TO_DATE('2020-08-27 14:07:11','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:41','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (71, '-', 'SCS_PACKER_PROD_RESULT', 'SCS 대상 Packer 생산 실적', 'SELECT division_id, scm_sitE_id, item_id, line_id
