INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (74, '-', 'ESS ESMI(G380) Sales Result', 'ESS ESMI(G380) Sales Result', '--[C20210106-000227] GSCM 북미 ESMI 법인 매출 확인
SELECT A.COMPANY_ID
      ,DIVISION_ID
      ,A.RESULT_YYYYMM
      ,SALES_POSTING_DATE
      ,ITEM_TYPE
      ,CUSTOMER_CODE
      ,CUSTOMER_NAME
      ,CURRENCY
      ,SALES_AMOUNT_FOR AS AMT_LOCAL
      ,SALES_AMOUNT_SUM AS AMT_KRW
      ,UOM
      ,SALES_QTY
      ,ITEM_ID
      ,SHIPTO_CODE
      ,SHIPTO_DESCRIPTION
      ,COUNTRY
      ,COUNTRY_NAME
      ,SHIPTO_CITY_NAME
      ,SHIPTO_ZONE_CODE
      ,SHIPTO_ZONE_NAME
      ,RBU_CUSTOMER
      ,INCOTERMS
  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R A
      ,(
		SELECT COMPANY_ID, RESULT_YYYYMM, MAX(IFSEQNO) IFSEQNO
		  FROM LGCE_INF.XIF_ERP_SALES_RESULT_R
		 WHERE DIVISION_ID = ''82''
		   AND COMPANY_ID = ''G380''
		 GROUP BY COMPANY_ID, RESULT_YYYYMM
	   ) B
 WHERE A.IFSEQNO = B.IFSEQNO
   AND A.RESULT_YYYYMM = B.RESULT_YYYYMM
   AND A.COMPANY_ID = B.COMPANY_ID
   AND A.SHIPTO_CODE <> ''G380''
   AND A.RESULT_YYYYMM = :PARAM1
   AND A.DIVISION_ID = ''82''
', 'Y', 'Y', 'choiya2', TO_DATE('2021-01-11 13:16:55','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (75, '-', 'MKT FCST SSP 동기화내역', 'MKT FCST SSP 동기화 상세내역', '
SELECT SCM_SITE_ID, ITEM_ID, FCST_TYPE, INCOTERMS, YYYYMMDD, QTY AS CURRENT_QTY
, ATTRIBUTE1 AS MKT_FCST_QTY_BEFORE_SYNC
, ATTRIBUTE2 AS NETTING_CARRYOVER_QTY
, ATTRIBUTE3 AS SHIPMENT_PLAN_QTY
FROM DM_PLN_MKT_FCST A
WHERE DIVISION_ID = :PARAM_DIVISION_ID
	AND YYYYMMDD BETWEEN :PARAM_FROM_DATE AND :PARAM_TO_DATE
	AND SCM_SITE_ID LIKE :PARAM_SALES_SITE || ''%''
	AND ITEM_ID LIKE :PARAM_MODEL || ''%''
	AND MEASURE = ''MKT_FCST''
', 'Y', 'Y', 'hwi1993', TO_DATE('2021-01-11 15:13:55','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (78, '-', 'Sales Site (Sales Customer) - Active 이력', 'Sales Site (Sales Customer) - Active 이력', 'SELECT /* TODO: add WHERE ROWNUM <= 5 or FETCH FIRST 5 ROWS ONLY */ HISTORY_SEQ, DIVISION_ID, SCM_SITE_ID, SOLDTO_CODE, SHIPTO_CODE, REP_YN, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
--
FROM [165.244.95.223,1433].LGCE_SCMDEV.SCM_MST_SITE_CUSTOMER_H
FROM SCM_MST_SITE_CUSTOMER_H

WHERE 1=1
	AND DIVISION_ID = :PARAM_DIVISION_ID
            AND SCM_SITE_ID = :PARAM_SCM_SITE_ID
	AND SOLDTO_CODE = :PARAM_SOLDTO_CODE 
	AND SHIPTO_CODE = :PARAM_SHIPTO_CODE 
ORDER BY LAST_UPDATE_DATE DESC', 'Y', 'Y', 'kuniid', TO_DATE('2021-01-19 17:20:49','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:02:37','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (80, '-', '출하계획 Cutoff 이력 조회', '출하계획 Cutoff 이력 조회', 'SELECT *										
FROM SSP_ANL_SHIP_PLAN_ALL TT0					
WHERE 1=1													
AND TT0.PLAN_START_YYYYMMDD = :PARAM_PLAN_START_YYYYMMDD
AND  (:PARAM_DIVISION_ID = ''''		OR TT0.DIVISION_ID	   = :PARAM_DIVISION_ID)
AND  (:PARAM_COMPNAY_ID = ''''		OR TT0.COMPANY_ID	   = :PARAM_COMPNAY_ID)
AND  (:PARAM_OPERATION_GROUP = '''' OR TT0.OPERATION_GROUP = :PARAM_OPERATION_GROUP)
AND TT0.SHIPMENT_CONFIRM_QTY > 0							
', 'Y', 'Y', 'kimyh8848', TO_DATE('2021-03-18 09:28:56','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (81, '-', 'Project Route Status N 81', 'Project Route 미등록 81 임시', TO_CLOB('SELECT DISTINCT
		 t.division_id
        ,fn_get_division_name(t.division_id) AS division_name
		,t.scm_site_id 
		,t.project_code
		,t.item_id 
		,CASE WHEN  u.plant_per_item is null  THEN ''BOM Not Exists'' ELSE  u.plant_per_item END AS plant_per_item 
		,NVL(u.cmpltd_status,''N'') AS cmpltd_status
		--,SUBSTR(yyyymmdd,1,6) AS month 
		--,t.qty
	--INTO #TblDynamicPivot_SCP0006_01
FROM ( select distinct a.division_id,project_code,a.scm_site_id,a.item_id,dom_exp,fcst_type,incoterms,measure,plant_site_id,yyyymmdd,qty 
	         from dm_pln_mkt_fcst a 
			 JOIN scm_mst_item_sn b ON a.division_id = b.division_id and a.item_id= b.item_id
			 LEFT JOIN scm_mst_site s ON s.DIVISION_ID=a.DIVISION_ID AND s.SCM_SITE_ID=a.SCM_SITE_ID AND s.VMI_YN=''Y''
	        WHERE 1=1 
			  --AND a.measure =''MKT_FCST''
			  AND a.MEASURE = CASE WHEN NVL(s.vmi_yn, ''N'') = ''Y'' THEN ''VMI_In_Req'' ELSE ''MKT_FCST'' END
			  AND b.scp_operation_group_id <> ''E''
			  AND a.yyyymmdd >= ''20210329''
			  AND a.yyyymmdd <= ''20220430''
			  and a.yyyymmdd != '''' and a.yyyymmdd is not null

			union all

		   select distinct a.division_id,project_code,a.scm_site_id,a.item_id,dom_exp,fcst_type,incoterms,measure,plant_site_id,yyyymmdd,qty 
	         from DM_PLN_MKT_FCST_RESULT a 
	         JOIN scm_mst_item_sn b ON a.division_id = b.division_id and a.item_id= b.item_id
			 LEFT JOIN scm_mst_site s ON s.DIVISION_ID=a.DIVISION_ID AND s.SCM_SITE_ID=a.SCM_SITE_ID AND s.VMI_YN=''Y''
	        WHERE 1=1 
			  --AND a.measure =''MKT_FCST''
			  AND a.MEASURE = CASE WHEN NVL(s.vmi_yn, ''N'') = ''Y'' THEN ''VMI_In_Req'' ELSE ''MKT_FCST'' END
			  AND b.scp_operation_group_id <> ''E''
			  AND a.yyyymmdd >= ''20210329''
			  AND a.yyyymmdd <= ''20220430''
			  and a.yyyymmdd != '''' and a.yyyymmdd is not null			  	
	     ) t  

		 /*******************start of 수량 카운트 부분 ********************************************************************************/
		 LEFT OUTER JOIN  (SELECT division_id
								 ,SCM_SITE_ID
		                         ,project_code								 
								 ,model_id
								 ,TO_CHAR(SUM(plant_cnt)) +''/'' || TO_CHAR(tot_cnt) AS plant_per_item
								 ,CASE WHEN SUM(plant_cnt) = tot_cnt THEN ''Y'' ELSE ''N'' END cmpltd_status
							FROM (
								SELECT division_id,SCM_SITE_ID, project_code, model_id, COUNT(*) OVER(PARTITION BY division_id,SCM_SITE_ID,project_code,model_id) AS tot_cnt, CASE WHEN primary_plant IS NOT NULL THEN 1 ELSE 0 END AS plant_cnt
								FROM (
										SELECT DISTINCT	
										         (CASE 
												  WHEN FN_GET_ITEM_OPERATION_GROUP(a.division_id, a.item_id) = ''E'' THEN C.ITEM_ID
												  ELSE b.model_id	
												  END ) AS model_id	
											   , (CASE 
												  -- 전극 제외 20180517
												  --WHEN d.operation_group_id = ''E'' THEN ''Electrode''
												  WHEN d.operation_group_id = ''A'' THEN ''Cell''
												  WHEN d.operation_group_id = ''P'' THEN ''Pack''
												  END ) AS operation_group_id
											   ,d.electrode_type
											   ,b.child_item_id AS item_id
											  ,(SELECT rownumber 
												 FROM (		
														SELECT ROW_NUMBER() OVER (ORDER BY from_yyyymmdd) AS rownumber
												 		 FROM scm_mst_site_item_priority s 
														WHERE s.division_id   = b.division_id
														  AND s.item_id       = b.child_item_id 
														  AND s.project_code  = a.project_code
														  AND s.SALES_SITE_ID = a.SCM_SITE_ID /* 20180326 sales site 추가부분 */
														  AND s.to_yyyymmdd  >= TO_CHAR(SYSDATE, ''YYYYMMDD'') 
														  AND s.valid_yn = ''Y''
														  AND s.priority = ''1''
	 													) a 
												 WHERE rownumber =1
												) AS primary_plant
											 ,b.division_id
											 ,a.SCM_SITE_ID
											 ,a.project_code			
										FROM dm_pln_mkt_fcst a 
											JOIN scm_mst_bom_sn b    ON a.division_id   = b.div') || TO_CLOB('ision_id
																	and a.item_id       = b.model_id 	
											JOIN scm_mst_item_sn c   ON b.company_id    = c.company_id 
																	and b.division_id   = c.division_id	
																	and b.site_id       = c.site_id 
																	and b.child_item_id = c.item_id
											JOIN scm_mst_final_item_v d  ON b.division_id = d.division_id  and b.child_item_id = d.item_id
											LEFT JOIN scm_mst_site s ON s.DIVISION_ID=a.DIVISION_ID AND s.SCM_SITE_ID=a.SCM_SITE_ID AND s.VMI_YN=''Y''
										WHERE 1=1
										--AND c.item_type		<> ''r''
										--  실적(등록된 카운트)수량은 분기되기 이전 날짜 전체를 사용해야 카운트가 맞음
										--Alternate Part 제외로직 추가
										AND	b.alt_priority =''Y''
										AND a.yyyymmdd >= ''20210329''
										AND a.yyyymmdd <= ''20220430''
									 	--AND a.measure =''MKT_FCST''
										AND a.MEASURE = CASE WHEN NVL(s.vmi_yn, ''N'') = ''Y'' THEN ''VMI_In_Req'' ELSE ''MKT_FCST'' END
			  							AND a.qty>0	
										AND a.division_id  = ''81''
										AND d.OPERATION_GROUP_ID <> ''E''
										--팩모델 하위의 CELL중에서 일부가 자동차전지에만 BOM에서 모ITEM으로 존재하지만,PROJECT ROUTE화면에서 ESS에 생산지를 등록하도록 표기되는 오류수정
										AND EXISTS (SELECT *
													FROM SCM_MST_BOM_ENG_SN
												   WHERE DIVISION_ID = ''81''
													 AND PARENT_ITEM_ID= b.child_item_id
													--BOM을 제거모델 조회안되도록 수정
													AND EFF_END_DATE >= SYSDATE
													AND KEY_DATE = ( SELECT MAX(KEY_DATE)
																	 FROM SCM_MST_BOM_ENG_SN
																    WHERE PARENT_ITEM_ID= b.child_item_id --''ECE0315N1-01''
																 	  AND DIVISION_ID = ''81'' )
												   )
									) m
								) n
							GROUP BY division_id, SCM_SITE_ID,project_code, model_id, tot_cnt
						) u  ON t.division_id  = u.division_id
						    AND t.SCM_SITE_ID  = u.SCM_SITE_ID
						    AND t.project_code = u.project_code
						    AND t.item_id      = u.model_id
		/******************end of 수량카운트********************************************************************************************/

		 INNER JOIN  scm_mst_site_item v  ON t.division_id  = v.division_id 
										and t.item_id      = v.item_id
										and t.scm_site_id  = v.scm_site_id 
										and t.project_code = v.project_code
         INNER JOIN  (SELECT division_id
		   				    ,item_id
		   				    ,nick_name
		   					,item_type
		   					,ROW_NUMBER() OVER ( PARTITION BY division_id, item_id ORDER BY  CASE item_type WHEN ''P'' THEN 999 WHEN ''H'' THEN 888 WHEN ''R'' THEN 777  WHEN ''Q'' THEN 666 ELSE 0 END  DESC ) nums
					   FROM SCM_MST_ITEM_SN 
					   ) i   ON t.division_id  = i.division_id
						    AND t.item_id      = i.item_id
							AND i.nums =1
	WHERE 1=1
	  AND i.item_type NOT IN (''Q'',''R'')	
	  --AND t.measure =''MKT_FCST''
	  AND t.measure in (''VMI_In_Req'',  ''MKT_FCST'')
	  AND t.qty>0	
		AND t.division_id  = ''81''

and NVL(u.cmpltd_status,''N'') = ''N''

'), 'Y', 'Y', 'blueeos', TO_DATE('2021-03-29 19:15:25','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:19','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (82, '-', 'No Line Assign With Prod Plan', '생산계획 있는데 Lign Assign 안 된 모델 조회', 'SELECT DISTINCT A.ORIGIN_DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.OPERATION_ID, A.LINE_ID, PROD_MONTH
FROM   (
		SELECT A.ORIGIN_DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.OPERATION_ID, A.LINE_ID, A.YYYYMMDD, SUBSTR(A.YYYYMMDD, 1, 6) AS PROD_MONTH, A.QTY
		FROM   SCP_ANL_PRODUCTION_PLAN A 
		WHERE  1=1

		AND    DIVISION_ID         = :PARAM_DIVSION_ID
		AND    PLAN_START_YYYYMMDD = :PARAM_PLAN_YYYYMMDD
		AND    PLAN_TYPE           = :PARAM_PLAN_TYPE
		AND    SEQ                 = :PARAM_PLAN_SEQ
		
		AND    QTY                 > 0
		AND    MEASURE             = ''PROD_PLAN_AMEND''
		AND    OPERATION_ID IN (SELECT SEGMENT1 AS OPERATION_ID
                                FROM   SCM_ADM_LOOKUP_MASTER_DETAIL   
                                WHERE  LOOKUP_TYPE = ''SCP_PLAN_OPERATION'' 
								AND    segment3 = CASE WHEN :PARAM_DIVSION_ID = ''EE'' THEN ''E''
								                       ELSE segment3
												  END
						       )
		AND    NOT EXISTS (
							SELECT 1
							FROM   (
									SELECT *
									FROM   SCM_MST_ITEM_LINE_ASSIGN_SN C 
									WHERE  1=1
									AND    C.OPERATION_ID  IN (SELECT SEGMENT1 AS OPERATION_ID
                                                               FROM   SCM_ADM_LOOKUP_MASTER_DETAIL   
                                                               WHERE  LOOKUP_TYPE = ''SCP_PLAN_OPERATION'' 
								                               AND    segment3 = CASE WHEN :PARAM_DIVSION_ID = ''EE'' THEN ''E''
								                                                      ELSE segment3
												                                 END
															  )
									AND    C.PRIORITY NOT IN (''0'', ''9'')
								 ) B
							WHERE  1=1
							AND    A.LINE_ID           = B.LINE_ID
							AND    A.OPERATION_ID      = B.OPERATION_ID
							AND    A.ITEM_ID           = B.ITEM_ID
							AND    SUBSTR(A.YYYYMMDD, 1, 6) = B.MONTH
							)
	) A

', 'Y', 'Y', 'blueeos', TO_DATE('2021-05-26 11:35:29','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (83, '-', 'Unplan List', 'Engine Unplan List', 'SELECT A.DIVISION_ID
     , A.PLAN_START_YYYYMMDD
     , A.PLAN_TYPE
     , A.SEQ
     , A.SALES_SITE_ID
     , A.MODEL_ID
     , A.YYYYMMDD
     , A.QTY                          AS FCST_QTY
     , B.PLANNED_QTY                  AS PLANNED_QTY
     , A.QTY- NVL(B.PLANNED_QTY,0) AS UNPLAN_QTY
FROM   SCP_ANL_PROBLEM_REPORT_DEMAND A
  LEFT OUTER JOIN (
                   SELECT A.ENG_DEMAND_ID
                        , A.ITEM_ID
                        , A.TO_SITE
                        , TO_CHAR(A.DUE_DATE, ''YYYYMMDD'') AS YYYYMMDD
                        , A.REQUIRED_QTY
                        , ROUND(A.PLANNED_QTY,0)            AS PLANNED_QTY
                   FROM   SCP_ANL_PROBLEM_REPORT_PEGGING A
                   WHERE  A.DIVISION_ID            = :PARAM_DIVSION_ID
                   AND    A.PLAN_START_YYYYMMDD    = :PARAM_PLAN_START_YYYYMMDD
                   AND    A.PLAN_TYPE              = :PARAM_PLAN_TYPE
                   AND    A.SEQ                    = :PARAM_PLAN_SEQ 
                   AND    A.PEGGING_OPERATION_CODE = ''ALLOC''
                  ) B
  ON  (A.ENG_DEMAND_ID = B.ENG_DEMAND_ID)
WHERE  A.DIVISION_ID         = :PARAM_DIVSION_ID
AND    A.PLAN_START_YYYYMMDD = :PARAM_PLAN_START_YYYYMMDD
AND    A.PLAN_TYPE           = :PARAM_PLAN_TYPE
AND    A.SEQ                 = :PARAM_PLAN_SEQ 
AND    A.PROBLEM_TYPE        = ''UNPLAN''
AND   (:PARAM_SCM_SITE_ID = '''' OR A.SALES_SITE_ID = :PARAM_SCM_SITE_ID)
AND   (:PARAM_ITEM_ID     = '''' OR A.MODEL_ID      = :PARAM_ITEM_ID)
', 'Y', 'Y', 'blueeos', TO_DATE('2021-06-07 17:39:18','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (52, '-', 'MKT_FCST 수정이력 조회', 'MKT_FCST 수정이력 조회', '/*
################### 입력샘플 필독! ###################
1. 사업부                       : = ''81''                          OR  (공백일경우 모든 사업부 검색)
2. PROJECT                  : = ''A15JR7002''               OR  (공백일경우 모든 PROJECT 검색)
3. SITE                         : = ''MAGNA_AT_GRZ''     OR  (공백일경우 모든 SITE 검색)
4. ITEM                        : = ''APJLRX590-A1-D01''  OR  (공백일경우 모든 ITEM 검색)
5. 값을 입력한날짜(시작) : = ''20190101''                  OR  (공백일경우 과거 8주 검색)
6. 값을 입력한날짜(끝)    : = ''20190131''                 OR  (공백일경우 금일까지 검색)
*/

SELECT DIVISION_ID,HISTORY_SEQ,PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY
		,LAST_UPDATED_BY AS ''MODIFY_ID''
		,(SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ B.USER_NAME FROM SCM_MST_SSO_USER_INFO B WHERE A.LAST_UPDATED_BY = B.USER_ID) AS MODIFY_USER_NAME
		,TO_CHAR(LAST_UPDATE_DATE, ''YYYY-MM-DD HH24:MI:SS'')  AS ''MODIFY_DATE''

	FROM DM_PLN_MKT_FCST_H A	WHERE 1=1
		AND A.DIVISION_ID = (CASE WHEN :PARAM_DIVSION_ID = '''' THEN A.DIVISION_ID ELSE :PARAM_DIVSION_ID END)
		AND A.PROJECT_CODE = ( CASE WHEN :PARAM_PROJECT_CODE = '''' THEN A.PROJECT_CODE ELSE :PARAM_PROJECT_CODE END)
		AND A.SCM_SITE_ID = ( CASE WHEN :PARAM_SCM_SITE_ID = '''' THEN A.SCM_SITE_ID ELSE :PARAM_SCM_SITE_ID END)
		AND A.ITEM_ID = ( CASE WHEN :PARAM_ITEM_ID = '''' THEN A.ITEM_ID ELSE :PARAM_ITEM_ID END)
		/* 날짜조건이 N/A일경우 지난주 월요일부터 데이터만 조회 */
		AND TO_CHAR(A.LAST_UPDATE_DATE, ''YYYYMMDD'')	>=	
		( CASE WHEN :PARAM_FROM_DATE = ''''	THEN TO_CHAR((FN_NEXT_DAY(SYSDATE, ''MON'')) + (-7*8), 112)	
		ELSE TO_CHAR(:PARAM_FROM_DATE, ''YYYYMMDD'') END ) 
		/* 날짜조건이 N/A일경우 오늘까지의 데이터만 조회 */
		AND TO_CHAR(A.LAST_UPDATE_DATE, ''YYYYMMDD'')	<=	
		( CASE WHEN :PARAM_TO_DATE = '''' THEN TO_CHAR(SYSDATE, ''YYYYMMDD'') ELSE TO_CHAR(:PARAM_TO_DATE, ''YYYYMMDD'') END)
		AND MEASURE IN (''MKT_FCST'',''RTF'')', 'Y', 'Y', 'songkeeho', TO_DATE('2019-01-24 16:17:47','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:02:37','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (53, '-', 'VMI Intransit', 'VMI향 해상 재고', 'SELECT /* TODO: add WHERE ROWNUM <= 30000 or FETCH FIRST 30000 ROWS ONLY */ STOCK.COMPANY_ID
       ,STOCK.DIVISION_ID
       ,MS.SCM_SITE_ID
       ,STOCK.PLANT_ID
       ,STOCK.FACTORY_ID
       ,FN_GET_ITEM_OPERATION_GROUP(STOCK.DIVISION_ID, STOCK.ITEM_ID) OPERATION_GROUP
       ,STOCK.ITEM_ID
       ,STOCK.STOCK_TYPE
       ,STOCK.STORAGE_ID
       ,MS.DESCRIPTION	 STORAGE_DESCRIPTION
       ,STOCK.OPERATION_ID
       ,NVL(STOCK.SCM_QTY, 0) SCM_QTY
       ,STOCK.QTY2
       ,STOCK.MOVING_QTY
    ,STOCK.DEFECT_QTY
       ,STOCK.MODIFY_FP_APPLY_WIPQTY
       ,STOCK.FP_APPLY_WIPQTY
       ,STOCK.CAL_QTY
       ,STOCK.QTY_UOM
       ,NVL(STOCK.WIPHOLD_YN,''N'')WIPHOLD_YN
       ,STOCK.HOLDING_DATE
       ,STOCK.AVAILABLE_DATE
       ,STOCK.OUTSOURCING_FLAG
       ,STOCK.OUTSOURCING_FACTORY
FROM    SCM_DNM_STOCK STOCK 
INNER JOIN   SCM_MST_VMI_INT_SLOC MS
ON    STOCK.DIVISION_ID           = MS.DIVISION_ID	
AND   STOCK.PLANT_ID              = MS.PLANT_ID
AND   STOCK.STORAGE_ID            = MS.STORAGE_ID
WHERE STOCK.DIVISION_ID = :PARAM_DIVSION_ID
AND   STOCK.CUTOFF_DATE = :PARAM_CUTOFF_DATE
AND  (:PARAM_ITEM_ID = '''' OR STOCK.ITEM_ID = :PARAM_ITEM_ID)
AND  (:PARAM_PLANT_ID = '''' OR STOCK.PLANT_ID = :PARAM_PLANT_ID)
AND  (:PARAM_OPERATION_GROUP = '''' OR FN_GET_ITEM_OPERATION_GROUP(STOCK.DIVISION_ID, STOCK.ITEM_ID) = :PARAM_OPERATION_GROUP)
AND  (:PARAM_STORAGE_ID = '''' OR STOCK.STORAGE_ID = :PARAM_STORAGE_ID)
AND  (:PARAM_STOCK_TYPE = '''' OR STOCK.STOCK_TYPE = :PARAM_STOCK_TYPE)
ORDER BY COMPANY_ID,DIVISION_ID,SCM_SITE_ID,PLANT_ID,FACTORY_ID,ITEM_ID,STOCK_TYPE,STORAGE_ID,OPERATION_ID

', 'Y', 'Y', 'blueeos', TO_DATE('2019-06-11 10:19:04','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:02:37','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (91, '-', 'DM ERP 실적 원본', 'DM ERP 매출실적 원본 중 최신데이터 전체를 조회', 'SELECT 
IFSEQNO, COMPANY_ID, DIVISION_ID, RESULT_YYYYMM, RESULT_YYYYMMDD, RESULT_HHMMSS, SALES_TYPE, SALES_DEPT, SALES_WORK_PLACE, SALES_WORK_PLACE_NAME
, SALES_GROUP, SALES_GROUP_NAME, SALES_POSTING_DATE, COST_ITEM, COST_ITEM_NAME, SALES_TYPE_2, VALUATION_CLASS, ITEM_TYPE, CUSTOMER_CODE, CUSTOMER_NAME
, CUSTOMER_PROJECT_NAME, CUSTOMER_ITEM_NAME, BIZ_TYPE, PROJECT_CODE, PROJECT_NAME, CELL_TYPE, CAR_MODEL, QTY_CELL_BY_PACK, Z_TYPE, Z_CODE, SALES_REGION
, DISTRIBUTION_CHANNEL, LGS_ROUTE_NAME, CONNECT_NAME, CAR_QTY, CELL_QTY, SALES_PRICE, CURRENCY, SALES_AMOUNT_FOR, SALES_AMOUNT_SUM, UOM, SALES_QTY
, SALES_USER, SALES_USER_NAME, MAT_GROUP, MAT_GROUP_DESC, ITEM_ID, BIZ_TYPE_2, APP, USAGE, SALES_TEAM, ESS_PM, PLANT_ID, SHIPTO_CODE, SHIPTO_DESCRIPTION
, COUNTRY, COUNTRY_NAME, SHIPTO_CITY_NAME, SHIPTO_ZONE_CODE, SHIPTO_ZONE_NAME, RBU_CUSTOMER, INCOTERMS, PROFIT_CENTER_ID, PROFIT_CENTER_NAME, PARTNER_PROFIT_CENTER_ID
, PARTNER_PROFIT_CENTER_NAME, ITEM_TEXT, AFFILIATE_CODE, SALES_SEQ, SALES_KEY, CUSTOMER_GROUP_CODE, CUSTOMER_GROUP_NAME, CELL_CODE, DELEGATE_MODEL_ID
, DELEGATE_MODEL_NAME, C_P_MODEL_ID, C_P_MODEL_NAME, LRREGULAR_CODE, LRREGULAR_NAME, MACHINE_CODE, MACHINE_NAME, LINE_ID, LINE_NAME, TCO, CREATE_DATE
, CREATE_TIME, CREATE_USER_ID, UPDATE_DATE, UPDATE_TIME, UPDATE_USER_ID, TRANSFER_DATE, TRANSFER_TIME, TRANSFER_USER_ID, TRANSFER_FLAG, ATTRIBUTE1
, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13
, ATTRIBUTE14, ATTRIBUTE15, SYSTEM_INPUT_DATE, SYSTEM_INPUT_TIME, DOC_CURRENCY, DOC_AMT_FOR, DOC_AMT_KRW, FKDAT, SO_NO, POSNN AS [주문품목번호], VGBEL AS [납품문서번호], VGPOS, TKNUM AS [선적번호]
, RBELN AS [빌링문서번호], RPOSN, SALES_EXCHRATE_M, SALES_AMOUNT_SUM_M
FROM XIF_ERP_SALES_RESULT_R_SN
WHERE IFSEQNO IN ( SELECT MAX(IFSEQNO) FROM XIF_ERP_SALES_RESULT_R_SN )
    AND DIVISION_ID = :PARAM_DIVISION_ID

', 'Y', 'Y', 'hwi1993', TO_DATE('2022-03-10 13:41:57','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (92, '-', '메뉴 접속이력', '메뉴별 접속이력', 'SELECT A.MENUID, CASE WHEN DEPT_NAME_KO LIKE ''소형%'' THEN ''소형'' WHEN DEPT_NAME_KO LIKE ''자동차%'' THEN ''자동차'' WHEN  DEPT_NAME_KO LIKE ''ESS%'' THEN ''ESS'' ELSE '''' END AS Div_Name, C.DEPT_NAME_KO, USERID, B.USER_NAME
, SUM(A.VIEWCNT) AS VIEW_CNT, CNNTDATE
FROM TB_FX_MenuConnect A
JOIN SCM_MST_SSO_USER_INFO B ON A.UserID = B.USER_ID
JOIN SCM_MST_SSO_DEPT_INFO C ON B.DEPT_ID = C.DEPT_ID
WHERE CNNTDATE LIKE :PARAM_YEAR || ''%''
AND MENUID LIKE ''%'' + :PARAM_MENU || ''%''
GROUP BY A.MENUID, CASE WHEN DEPT_NAME_KO LIKE ''소형%'' THEN ''소형'' WHEN DEPT_NAME_KO LIKE ''자동차%'' THEN ''자동차'' WHEN  DEPT_NAME_KO LIKE ''ESS%'' THEN ''ESS'' ELSE '''' END, C.DEPT_NAME_KO, USERID, B.USER_NAME, CNNTDATE
', 'Y', 'Y', 'hwi1993', TO_DATE('2022-03-16 16:09:20','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (93, '-', 'SLOC_SHIPTO_SOLDTO', 'SHIPTO, SOLDTO의 모든 SLOC를 조회', 'SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.SITE_DESCRIPTION, B.SOLDTO_CODE, B.SHIPTO_CODE, A.VALID_YN AS SITE_VALID_YN, B.REP_YN, B.VALID_YN AS SOLDTO_SHIPTO_VALID_YN, C.LOCATION_CODE
FROM SCM_MST_SITE A
JOIN SCM_MST_SITE_CUSTOMER B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID
LEFT OUTER JOIN ( SELECT DISTINCT DIVISION_ID, SCM_SITE_ID, LOCATION_CODE
                    FROM SCM_MST_LOCATION
                    ) C ON A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID
WHERE A.SITE_TYPE = ''SALES''', 'Y', 'Y', 'rosia27', TO_DATE('2022-03-18 14:13:02','YYYY-MM-DD HH24:MI:SS'), 'rosia27', TO_DATE('2022-03-18 14:14:08','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (98, '-', 'Lookup Master Info.', 'Lookup 마스터 정보 조회', 'SELECT B.LOOKUP_TYPE, B.LOOKUP_NAME, B.LOOKUP_GROUP
     , A.SEGMENT1, A.SEGMENT2, A.SEGMENT3, A.SEGMENT4, A.SEGMENT5
	 , A.DISPLAY_SEQ, A.VALID_YN, A.DESCRIPTION
FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A
     , (
		SELECT LOOKUP_TYPE, DESCRIPTION AS LOOKUP_NAME, LOOKUP_GROUP
		FROM   SCM_ADM_LOOKUP_MASTER
		WHERE  LOOKUP_GROUP IN (''SCP'', ''DM'')
		AND    VALID_YN = ''Y''
	   ) B
WHERE  A.LOOKUP_TYPE = B.LOOKUP_TYPE
AND    A.LOOKUP_TYPE IN (''DM_R_ITEM_ID'')
AND    (:PARAM_LOOKUP_TYPE = '''' OR B.LOOKUP_TYPE LIKE ''%''+:PARAM_LOOKUP_TYPE || ''%'')
AND    (:PARAM_LOOKUP_GROUP = '''' OR B.LOOKUP_GROUP = :PARAM_LOOKUP_GROUP)', 'Y', 'Y', 'jsheo', TO_DATE('2022-08-12 10:56:12','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (99, '-', 'Shipment Result IF Monitoring', '출하 결과 인터페이스 상세내역', TO_CLOB('SELECT     X.DIVISION_ID 
	,      MS.COMPANY_ID AS COMPANY_ID
	,	   X.ERP_SO_NO
	,      X.ERP_DO_NO
	,      X.CONFIRM_ID 
	,      X.ITEM_ID 
	,      FN_GET_ITEM_NICKNAME(X.DIVISION_ID, X.ITEM_ID) AS NICK_NAME	
	,      NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID,X.FROM_SITE),X.FROM_SITE)   AS FROM_SITE 
	,      NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID,X.TO_SITE),X.TO_SITE)       AS TO_SITE 		
	,      X.END_CUSTOMER  
	,      X.QTY AS RESULT_ERP
	,      X.WQTY AS RESULT_OWMS
	,      X.QTY - X.WQTY AS GAP
	,      NVL(MS.OSP_YN,''N'')  AS PACKER_YN
	,      X.NORMAL_YN 
	,      TO_CHAR(TO_DATE(X.YYYYMMDD, ''YYYYMMDD''), ''YYYY-MM-DD'') AS YYYYMMDD 
	,      X.TRANSPORT_MODE
	,      X.INCOTERMS
	,      TO_CHAR(TO_DATE(X.ETD_DATE, ''YYYYMMDD''), ''YYYY-MM-DD'') AS ETD_DATE
	,      TO_CHAR(TO_DATE(X.ETA_DATE, ''YYYYMMDD''), ''YYYY-MM-DD'') AS ETA_DATE
	,	   X.SHIP_TYPE	
	FROM (		
		SELECT R.DIVISION_ID     AS DIVISION_ID
		,     ''E''				 AS TYPE 
		,      R.ERP_SO_NO       AS ERP_SO_NO
		,      R.ERP_DO_NO       AS ERP_DO_NO
		,      R.CONFIRM_ID      AS CONFIRM_ID 
		,      R.ITEM_ID         AS ITEM_ID 
		,      R.FROM_SITE       AS FROM_SITE 
		,      R.TO_SITE         AS TO_SITE 
		,      NULL              AS END_CUSTOMER
		,      SUM(R.RESULT_QTY)      AS QTY 
		,      R.YYYYMMDD        AS YYYYMMDD
		--,      P.TRANSPORT_MODE  AS TRANSPORT_MODE
		--,      P.INCOTERMS       AS INCOTERMS
		,      R.TRANSPORT_MODE  AS TRANSPORT_MODE
		,      R.INCOTERMS       AS INCOTERMS
		,      R.ETD_DATE        AS ETD_DATE
		,      R.ETA_DATE        AS ETA_DATE
		,      CASE WHEN R.ERP_DO_NO IS NULL OR R.ERP_DO_NO = '''' THEN ''N'' 
			        WHEN W.SHIP_TYPE IN (SELECT L1.SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L1
								   WHERE L1.LOOKUP_TYPE = ''SSP_SHIP_TYPE'' 
								   AND L1.VALID_YN = ''Y'') THEN ''N'' ELSE ''Y'' END  AS NORMAL_YN
		,      W.SHIP_TYPE		 AS SHIP_TYPE
		,      W.QTY             AS WQTY	
		FROM  (
				SELECT  E.DIVISION_ID             AS DIVISION_ID
				,       E.CONFIRM_ID              AS CONFIRM_ID
				,       E.ORDER_NO				  AS ERP_SO_NO 
				,       E.DELIVERY_NO             AS ERP_DO_NO
				,       E.EXFACTORY_DATE          AS YYYYMMDD
				,       E.TRANSPORT_MODE		  AS TRANSPORT_MODE
				,       E.INCOTERMS				  AS INCOTERMS
				,		E.ETA_DATE				  AS ETA_DATE
				,		E.ETD_DATE				  AS ETD_DATE
				,		E.FROM_SCM_SITE_ID		  AS FROM_SITE
				,		E.TO_SCM_SITE_ID		  AS TO_SITE
				,		E.ITEM_ID				  AS ITEM_ID
				,       SUM(E.EXFACTORY_QTY )     AS RESULT_QTY 					
				FROM SCM_DNM_EXFACTORY_RESULT E
					JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
						ON L.LOOKUP_TYPE = ''ERP_SSP_TYPE''
					AND L.VALID_YN = ''Y''
					AND L.SEGMENT1    = E.SSP_TYPE 
				WHERE 1=1
				AND   NVL(E.EXFACTORY_STATUS,''D90'') NOT IN (''D90'' ,''D10'')
				AND   E.CONFIRM_ID LIKE ''C%''
				AND   E.EXFACTORY_DATE BETWEEN :PARAM_FROM_YYYYMMDD  AND :PARAM_TO_YYYYMMDD
				GROUP BY E.DIVISION_ID 
				,        E.CONFIRM_ID
				,        E.ORDER_NO
				,        E.DELIVERY_NO
				,        E.EXFACTORY_DATE
				,		 E.TRANSPORT_MODE
				,        E.INCOTERMS
				,		 E.ETA_DATE
				,        E.ETD_DATE
				,		 E.FROM_SCM_SITE_ID	
				,		 E.TO_SCM_SITE_ID	
				,		 E.ITEM_ID ) R 
				JOIN (SELECT A.DIVISION_ID       AS DIVISION_ID 
					,      A.ITEM_ID           AS ITEM_ID 
					,      A.FROM_SITE         AS FROM_SITE
					,      CASE WHEN A.TO_SITE =''-'' THEN A.CUSTOMER_CODE ELSE  A.TO_SITE END          AS TO_SITE
					,      SUM(A.LOT_QTY)            AS QTY 
					,      A.PLANT_ISSUE_DATE  AS YYYYMMDD
					,	   A.SHIP_TYPE AS SHIP_TYPE
					,      A.DELIVERY_NO AS ERP_DO_NO
					FROM SSP_DNM_SHIP_RESULT_OWMS A
					WHERE A.PLANT_ISSUE_DATE BETWEEN  :PARAM_FROM_YYYYMMDD  AND :PARAM_TO_YYYYMMDD
					GROUP BY A.DIVISION_ID        
					,        A.ITEM_ID      
					,        A.FROM_SITE   
					,        CASE WHEN A.TO_SITE =''-'' THEN A.CUSTOMER_CODE EL') || TO_CLOB('SE A.TO_SITE  END  
					,        A.PLANT_ISSUE_DATE  
					,		 A.SHIP_TYPE
					,        A.DELIVERY_NO) W
					ON R.DIVISION_ID = W.DIVISION_ID 
					AND R.FROM_SITE = W.FROM_SITE
					AND R.ITEM_ID = W.ITEM_ID	
					AND R.ERP_DO_NO = W.ERP_DO_NO

		GROUP BY R.DIVISION_ID
		,        R.ERP_SO_NO
		,        R.ERP_DO_NO
		,        R.FROM_SITE                                                                           
		,        R.TO_SITE 
		,        R.ITEM_ID
		--,		 P.TRANSPORT_MODE			   
		--,		 P.INCOTERMS
		,		 R.TRANSPORT_MODE			   
		,		 R.INCOTERMS
		--,		 P.ETD_DATE
		--,		 P.ETA_DATE
		,		 R.ETD_DATE
		,		 R.ETA_DATE			  
		,        R.YYYYMMDD 
		,        R.CONFIRM_ID			
		,        W.QTY
		,        W.SHIP_TYPE

	UNION ALL 

		--CONFIRM_ID 없는 실적 
		SELECT R.DIVISION_ID     AS DIVISION_ID
		,     ''E''                AS TYPE 
		,      R.ERP_SO_NO       AS ERP_SO_NO
		,      R.ERP_DO_NO       AS ERP_DO_NO
		,      NULL              AS CONFIRM_ID 
		,      R.ITEM_ID         AS ITEM_ID 
		,      R.FROM_SITE       AS FROM_SITE 
		,      R.TO_SITE         AS TO_SITE 
		,      NULL              AS END_CUSTOMER
		,      R.QTY             AS QTY 
		,      R.YYYYMMDD        AS YYYYMMDD 
		--,      NULL              AS TRANSPORT_MODE
		--,      NULL              AS INCOTERMS
		,      R.TRANSPORT_MODE  AS TRANSPORT_MODE
		,      R.INCOTERMS       AS INCOTERMS
		--,      NULL              AS ETD_DATE
		--,      NULL              AS ETA_DATE
		,      R.ETD_DATE        AS ETD_DATE
		,      R.ETA_DATE        AS ETA_DATE 
		,      CASE WHEN R.ERP_DO_NO IS NULL OR R.ERP_DO_NO = '''' THEN ''N'' 
			        WHEN W.SHIP_TYPE IN (SELECT L1.SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L1
								   WHERE L1.LOOKUP_TYPE = ''SSP_SHIP_TYPE'' 
								   AND L1.VALID_YN = ''Y'') THEN ''N'' ELSE ''Y'' END  AS NORMAL_YN
		,      W.SHIP_TYPE       AS SHIP_TYPE
		,      W.QTY             AS WQTY
		FROM  (SELECT  E.DIVISION_ID             AS DIVISION_ID
		,       ''-''                       AS CONFIRM_ID
		,       E.ORDER_NO				  AS ERP_SO_NO 
		,       E.DELIVERY_NO             AS ERP_DO_NO
		,       E.FROM_SCM_SITE_ID        AS FROM_SITE                                                                    
        ,       NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)     AS TO_SITE   
		,       E.ITEM_ID                 AS ITEM_ID
		,       E.EXFACTORY_DATE          AS YYYYMMDD
		,       E.TRANSPORT_MODE      AS TRANSPORT_MODE
		,       E.INCOTERMS				  AS INCOTERMS
		,		E.ETA_DATE				  AS ETA_DATE
		,		E.ETD_DATE				  AS ETD_DATE
		,       SUM(E.EXFACTORY_QTY )     AS QTY  		
		FROM SCM_DNM_EXFACTORY_RESULT E
			JOIN  SCP_MST_FINAL_ITEM F 
			  ON F.ITEM_ID = E.ITEM_ID 
			 AND F.DIVISION_ID = E.DIVISION_ID
			JOIN   SCM_MST_SITE FS
				ON FS.SCM_SITE_ID = E.FROM_SCM_SITE_ID 
			   AND FS.DIVISION_ID = E.DIVISION_ID 			 
			JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
				ON L.LOOKUP_TYPE = ''ERP_ORDER_TYPE''
			AND L.VALID_YN = ''Y''
			AND L.SEGMENT1    = E.ORDER_TYPE_CODE 
			LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L3
					ON L3.LOOKUP_TYPE = ''SHIP_RESULT_TO_SITE_MAPPING''
				AND L3.SEGMENT1    = E.DIVISION_ID 
				AND L3.SEGMENT2    = E.SOLDTO_CODE
				AND L3.SEGMENT3    = E.SHIPTO_CODE					    
		WHERE 1=1
		AND   NVL(E.EXFACTORY_STATUS,''D90'') NOT IN (''D90'' ,''D10'')
		AND   NVL(E.CONFIRM_ID,'''') NOT LIKE  ''C%''
		AND   E.EXFACTORY_DATE BETWEEN  :PARAM_FROM_YYYYMMDD  AND :PARAM_TO_YYYYMMDD		
		AND   E.STORAGE_ID NOT IN (''6000'' ,''799A'')		
		AND   E.STORAGE_ID NOT IN (SELECT SEGMENT1 
								FROM SCM_ADM_LOOKUP_MASTER_DETAIL 
								WHERE LOOKUP_TYPE = ''SSP_SHIP_RESULT_EXCEPT_STORAGE''
									AND VALID_YN = ''Y''
								)
		GROUP BY E.DIVISION_ID 
		,        E.ORDER_NO
		,        E.DELIVERY_NO
		,        E.FROM_SCM_SITE_ID                                                                           
		,        NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID) 
		,    ') || TO_CLOB('    E.ITEM_ID   
		,        E.EXFACTORY_DATE
		,		 E.TRANSPORT_MODE
		,        E.INCOTERMS
		,		 E.ETA_DATE
		,        E.ETD_DATE	) R 
			  JOIN (SELECT A.DIVISION_ID       AS DIVISION_ID 
				,      A.ITEM_ID           AS ITEM_ID 
				,      A.FROM_SITE         AS FROM_SITE
				,      CASE WHEN A.TO_SITE =''-'' THEN A.CUSTOMER_CODE ELSE  A.TO_SITE END          AS TO_SITE
				,      SUM(A.LOT_QTY)            AS QTY 
				,      A.PLANT_ISSUE_DATE  AS YYYYMMDD
				,	   A.SHIP_TYPE AS SHIP_TYPE
				,      A.DELIVERY_NO AS ERP_DO_NO
				FROM SSP_DNM_SHIP_RESULT_OWMS A
				WHERE A.PLANT_ISSUE_DATE BETWEEN  :PARAM_FROM_YYYYMMDD  AND :PARAM_TO_YYYYMMDD
				GROUP BY A.DIVISION_ID        
				,        A.ITEM_ID      
				,        A.FROM_SITE   
				,        CASE WHEN A.TO_SITE =''-'' THEN A.CUSTOMER_CODE ELSE A.TO_SITE  END  
				,        A.PLANT_ISSUE_DATE  
				,		 A.SHIP_TYPE
				,        A.DELIVERY_NO	) W
					  ON R.DIVISION_ID = W.DIVISION_ID 
					  AND R.FROM_SITE = W.FROM_SITE
					  AND R.ITEM_ID = W.ITEM_ID		
					  AND R.ERP_DO_NO = W.ERP_DO_NO
	
	) X
		JOIN SCM_MST_SITE MS 
		  ON MS.DIVISION_ID = X.DIVISION_ID 
		 AND MS.SCM_SITE_ID = X.FROM_SITE  
		 AND MS.OPERATION_GROUP < > ''E''
		JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
   		  ON L.LOOKUP_TYPE = ''SSP_SHIPMENT_RESULT_TYPE'' -- LOOKUP에 등록된 공정만 
		 AND L.SEGMENT1 = X.TYPE 
		 AND L.VALID_YN = ''Y''
		LEFT OUTER JOIN SSP_MST_MODEL_USER M 
		          ON  M.DIVISION_ID = X.DIVISION_ID 
					AND M.FROM_SITE = X.FROM_SITE 
					AND M.ITEM_ID = X.ITEM_ID 
					AND M.VALID_YN = ''Y''
	WHERE 1=1	
	AND ( ( :PARAM_DIVISION_ID   IS NULL OR :PARAM_DIVISION_ID ='''')  OR X.DIVISION_ID  = :PARAM_DIVISION_ID ) 
	AND ( ( :PARAM_COMPANY_ID   IS NULL OR :PARAM_COMPANY_ID ='''')  OR MS.COMPANY_ID  = :PARAM_COMPANY_ID )
	AND ( ( :PARAM_FROM_SITE   IS NULL OR :PARAM_FROM_SITE ='''')  OR X.FROM_SITE IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT(:PARAM_FROM_SITE,'','')) )
	AND ( ( :PARAM_ITEM_ID   IS NULL OR :PARAM_ITEM_ID ='''')  OR X.ITEM_ID IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT(:PARAM_ITEM_ID,'','')) )	
	AND ( ( :PARAM_ERP_DO_NO   IS NULL OR :PARAM_ERP_DO_NO ='''')  OR X.ERP_DO_NO IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT(:PARAM_ERP_DO_NO,'','')) )
	AND ( ( :PARAM_PACKER_YN   IS NULL OR :PARAM_PACKER_YN ='''')  OR MS.OSP_YN = :PARAM_PACKER_YN )	
	AND ( ( :PARAM_NORMAL_YN   IS NULL OR :PARAM_NORMAL_YN ='''')  OR X.NORMAL_YN = :PARAM_NORMAL_YN )	
	AND ( ( :PARAM_GAP_YN   IS NULL OR :PARAM_GAP_YN ='''' OR :PARAM_GAP_YN =''N'')  OR ( :PARAM_GAP_YN = ''Y'' AND  X.QTY - X.WQTY > 0 ) )	
		
	--ORDER BY X.DIVISION_ID, X.FROM_SITE, X.YYYYMMDD, X.ITEM_ID, X.TO_SITE, L.DISPLAY_SEQ, X.CONFIRM_ID'), 'N', 'Y', 'jungilsetup', TO_DATE('2022-10-11 16:04:31','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:26:13','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (100, '-', 'Amend time history', '매주 planning 시의 최종 amend 시간 조회', 'SELECT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, LAST_UPDATED_BY, TO_CHAR(HISTORY_CREATION_DATE, ''YYYYMMDD'') AS HISTORY_CREATION_DATE, TO_CHAR(HISTORY_CREATION_DATE, ''HH24:MI:SS'') AS HISTORY_CREATION_TIME

FROM   SCP_ANL_PRODUCTION_PLAN_H
WHERE  (:PARAM_DIVISION_ID = '''' OR DIVISION_ID = :PARAM_DIVISION_ID)
AND    PLAN_START_YYYYMMDD = :PARAM_PLAN_START_YYYYMMDD
AND    (:PARAM_PLAN_TYPE = '''' OR PLAN_TYPE = :PARAM_PLAN_TYPE)
AND    (:PARAM_SEQ = '''' OR TO_CHAR(SEQ) = :PARAM_SEQ)
GROUP BY DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, LAST_UPDATED_BY, TO_CHAR(HISTORY_CREATION_DATE, ''YYYYMMDD''), TO_CHAR(HISTORY_CREATION_DATE, ''HH24:MI:SS'')
', 'Y', 'Y', 'blueeos', TO_DATE('2023-01-05 10:57:13','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (101, '-', 'GPLM Cell Conversion Factor 2', 'GPLM Cell Conversion Factor 2', '
  SELECT
	 CELL_TYPE
	,TARGET_CELL
	,CELL_SEQ
	,LVL
	,ITEM_SEQ
	,ITEM_ID
	,ITEM_DESCRIPTION
	,ITEM_SPEC
	,UNIT
	,AMOUNT
	,CELL_CF AS  GPLM_CELL_CONVERSION_FACTOR
	,REVISION
	,BOM_MODIFY_DATE
FROM SCP_MST_ITEM_CELL_CF       
WHERE 1 = 1
AND  ITEM_ID = (CASE WHEN :PARAM_ITEM_ID = '''' THEN ITEM_ID ELSE :PARAM_ITEM_ID END)
', 'Y', 'Y', 'yongseokyoon', TO_DATE('2023-02-13 18:17:42','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (102, '-', '생산계획 스냅샷', '-', '-', 'N', 'Y', 'multishin', TO_DATE('2023-04-15 22:28:05','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:08:17','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (104, '-', 'FP WPP 계획', 'FP WPP 계획', 'SELECT P.PLANT_ID,
P.FACTORY_ID,
C.GROUP_CODE1, 
C.GROUP_CODE2, 
C.NICK_NAME,
P.TOP_ITEM_ID,
P.OPERATION_ID, 
P.FP_PRODUCTION_TYPE,
P.LINE_ID, 
P.ELECTRODE_TYPE, 
P.PLAN_DATE, 
D.YYYYMM, 
D.YYYYWW,
D.YYYYMMDD,
P.PLAN_TYPE,
P.PLAN_QTY 
FROM LGCE_FP_TR.FP_DAILY_PRODUCTIOIN_PLAN_H P,
LGCE_SCMPROD.SCP_MST_FINAL_ITEM C,
LGCE_SCMPROD.SCM_MST_BUCKET D
WHERE 1=1
AND P.DIVISION_ID = C.DIVISION_ID 
AND P.TOP_ITEM_ID = C.ITEM_ID
AND P.OPERATION_ID IN (''P5500'',''P9500'')
AND P.PLANT_ID IN  (''A040'', ''G481'')
AND P.PLAN_DATE = D.YYYYMMDD
AND P.PLAN_TYPE = ''WPP''
AND P.PLAN_QTY > 0

', 'Y', 'Y', 'sji.kwon', TO_DATE('2023-04-18 17:50:43','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (105, '-', 'FP 실적', 'FP 실적', 'SELECT R.PLANT_ID,
R.FACTORY_ID,
C.GROUP_CODE1, 
C.GROUP_CODE2, 
C.NICK_NAME,
R.TOP_ITEM_ID,
R.OPERATION_ID, 
R.FP_PRODUCTION_TYPE,
R.LINE_ID, 
R.ELECTRODE_TYPE, 
R.PLAN_DATE, 
D.YYYYMM, 
D.YYYYWW,
D.YYYYMMDD,
''RESULT''  PLAN_TYPE,
R.ACTUAL_GOOD_QTY 
FROM LGCE_FP_TR.SCM_DAILY_PRODUCT_RESULT_H R,
LGCE_SCMPROD.SCP_MST_FINAL_ITEM C,
LGCE_SCMPROD.SCM_MST_BUCKET D
WHERE 1=1
AND R.DIVISION_ID = C.DIVISION_ID 
AND R.TOP_ITEM_ID = C.ITEM_ID
AND R.OPERATION_ID IN (''P5500'',''P9500'')
AND R.PLANT_ID IN  (''A040'', ''G481'')
AND R.PLAN_DATE = D.YYYYMMDD
AND R.ACTUAL_GOOD_QTY > 0

', 'Y', 'Y', 'sji.kwon', TO_DATE('2023-04-18 17:51:32','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (106, '-', 'ESS CEG Sales Result_N', 'ESS CEG Sales Result', 'SELECT A.COMPANY_ID
