   AND A.SHIPTO_CODE <> ''G690''
   AND A.SALES_YYYYMM = :PARAM1
   AND A.DIVISION_ID = ''82''
   AND A.CUSTOMER_CODE <> ''C100''', 'Y', 'Y', 'chano0612', TO_DATE('2023-06-07 09:09:33','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (107, '-', 'ESS (G540) Sales Result_N', 'ESS (G540) Sales Result', '   SELECT A.COMPANY_ID
