      ,A.SALES_AMOUNT_SUM AS AMT_KRW
      ,A.UOM
      ,A.SALES_QTY
      ,A.ITEM_ID
      ,A.SHIPTO_CODE
      ,A.SHIPTO_DESCRIPTION
      ,A.COUNTRY
      ,A.COUNTRY_NAME
      ,A.SHIPTO_CITY_NAME
      ,A.SHIPTO_ZONE_CODE
      ,A.SHIPTO_ZONE_NAME
