   AND A.COMPANY_ID = ''G380''
   AND A.SHIPTO_CODE <> ''G380''
   AND A.SALES_YYYYMM = :PARAM1
   AND A.DIVISION_ID = ''82''', 'Y', 'Y', 'chano0612', TO_DATE('2023-06-07 09:15:00','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (109, '-', 'Cell Product Assy Map', 'Cell Product와 Cell Assy Mapping 정보', 'SELECT a.DIVISION_ID, a.PLANT_ID, a.ITEM_ID_PROD, A.ITEM_ID_ASSY, CELL_TYPE, VALID_YN
  FROM SCP_MST_CELL_PROD_ASSY_MAP a
 WHERE a.DIVISION_ID        = :PARAM_DIVISION_ID
   AND (:PARAM_PLANT_ID     = '''' OR a.PLANT_ID LIKE :PARAM_PLANT_ID)
   AND (:PARAM_ITEM_ID_PROD = '''' OR a.ITEM_ID_PROD LIKE :PARAM_ITEM_ID_PROD)
   AND (:PARAM_ITEM_ID_ASSY = '''' OR a.ITEM_ID_ASSY LIKE ITEM_ID_ASSY)
', 'Y', 'Y', 'blueeos', TO_DATE('2023-06-30 13:27:59','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:56:01','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (110, '-', 'SSPM INVENTORY DAYS 변경이력', '82번 사업부의 SSPM Inventory Days 변경이력 확인', 'SELECT /* TODO: add WHERE ROWNUM <= 10000 or FETCH FIRST 10000 ROWS ONLY */ * FROM(
SELECT HISTORY_SEQ
,TO_CHAR(LAST_UPDATE_DATE, ''YYYYMMDD'') AS  LAST_UPDATE_DATE
, DIVISION_ID
, PROJECT_CODE
, SCM_SITE_ID
, ITEM_ID
, CONSENSUS_MKT
, CONSENSUS_ESS
, CONSENSUS_SCM
, INVENTORY_DAY
, ''N/A'' AS CHANGE_REASON
, VALID_YN
, BPMS_EXIST
, CREATED_BY
, CREATION_DATE
, LAST_UPDATED_BY
  FROM SCM_MST_SITE_ITEM_H
WHERE 1=1
AND  DIVISION_ID = ''82'' 
AND PROJECT_CODE = ( CASE WHEN ''''  = '''' THEN PROJECT_CODE ELSE ''''  END ) 
AND SCM_SITE_ID IN (''LGCEG_DE_MWA'',''LGCAU_AU_BNE'',''LGCMI_US_LGB'')
AND SCM_SITE_ID = ( CASE WHEN ''''  = '''' THEN SCM_SITE_ID ELSE ''''  END ) 
AND ITEM_ID  = ( CASE WHEN ''''  = '''' THEN ITEM_ID ELSE ''''  END )  
AND ATTRIBUTE3 = ''Y''
) A
WHERE A.CONSENSUS_MKT != '''' AND CONSENSUS_ESS != '''' AND CONSENSUS_SCM != ''''
GROUP BY  HISTORY_SEQ
, DIVISION_ID
, PROJECT_CODE
, SCM_SITE_ID
, ITEM_ID
, CONSENSUS_MKT
, CONSENSUS_ESS
, CONSENSUS_SCM
, INVENTORY_DAY
, ''N/A'' AS CHANGE_REASON
, VALID_YN
, BPMS_EXIST
, CREATED_BY
, CREATION_DATE
, LAST_UPDATED_BY
, LAST_UPDATE_DATE
ORDER BY A.HISTORY_SEQ DESC', 'Y', 'Y', 'chano0612', TO_DATE('2023-09-13 09:50:00','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:26:13','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (111, '-', 'OPT Lookup Validation', '최적화 제약 점검(룩업)', TO_CLOB('SELECT Contents, LOOKUP_TYPE, SEGMENT2, SEGMENT3, SEGMENT4, SEGMENT5, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
FROM
(
	SELECT 
		''[구간 중복] 최소 가동율(평준화)'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_MIN_OPERATION''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.ATTRIBUTE1 <> b.ATTRIBUTE1
		AND a.ATTRIBUTE2 <> b.ATTRIBUTE2
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE2 >= b.ATTRIBUTE1 AND a.ATTRIBUTE2 <= b.ATTRIBUTE2)
		OR (b.ATTRIBUTE2 >= a.ATTRIBUTE1 AND b.ATTRIBUTE2 <= a.ATTRIBUTE2)
		OR (a.ATTRIBUTE1 <= b.ATTRIBUTE1 AND a.ATTRIBUTE2 >= b.ATTRIBUTE2)

	UNION ALL

	SELECT 
		''[구간 중복] 운송모드 BLOCK'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_BOD_BLOCKING''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.ATTRIBUTE1 = b.ATTRIBUTE1
		AND a.ATTRIBUTE5 <> b.ATTRIBUTE5
		AND a.ATTRIBUTE6 <> b.ATTRIBUTE6
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE6 >= b.ATTRIBUTE5 AND a.ATTRIBUTE6 <= b.ATTRIBUTE6)
		OR (b.ATTRIBUTE6 >= a.ATTRIBUTE5 AND b.ATTRIBUTE6 <= a.ATTRIBUTE6)
		OR (a.ATTRIBUTE5 <= b.ATTRIBUTE5 AND a.ATTRIBUTE6 >= b.ATTRIBUTE6)

	UNION ALL

	SELECT 
		''[구간 중복] 활성화 LT 구간별'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_FORMATION_LT''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.SEGMENT5 = b.SEGMENT5
		AND a.ATTRIBUTE3 <> b.ATTRIBUTE3
		AND a.ATTRIBUTE4 <> b.ATTRIBUTE4
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE4 >= b.ATTRIBUTE3 AND a.ATTRIBUTE4 <= b.ATTRIBUTE4)
		OR (b.ATTRIBUTE4 >= a.ATTRIBUTE3 AND b.ATTRIBUTE4 <= a.ATTRIBUTE4)
		OR (a.ATTRIBUTE3 <= b.ATTRIBUTE3 AND a.ATTRIBUTE4 >= b.ATTRIBUTE4)

	UNION ALL

	SELECT 
		''[구간 중복] 활성화 수율 구간별'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_FORMATION_PERIOD_YIELD''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.SEGMENT5 = b.SEGMENT5
		AND a.ATTRIBUTE1 <> b.ATTRIBUTE1
		AND a.ATTRIBUTE2 <> b.ATTRIBUTE2
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE2 >= b.ATTRIBUTE1 AND a.ATTRIBUTE2 <= b.ATTRIBUTE2)
		OR (b.ATTRIBUTE2 >= a.ATTRIBUTE1 AND b.ATTRIBUTE2 <= a.ATTRIBUTE2)
		OR (a.ATTRIBUTE1 <= b.ATTRIBUTE1 AND a.ATTRIBUTE2 >= b.ATTRIBUTE2)

	UNION ALL

	SELECT 
		''[구간 중복] 전진검사'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, ') || TO_CLOB('a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_FORWARD_INSPECTION''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.SEGMENT5 = b.SEGMENT5
		AND a.ATTRIBUTE1 = b.ATTRIBUTE1
		AND a.ATTRIBUTE2 = b.ATTRIBUTE2
		AND a.ATTRIBUTE3 = b.ATTRIBUTE3
		AND a.ATTRIBUTE4 = b.ATTRIBUTE4
		AND NVL(a.ATTRIBUTE9,''ZZ'') = NVL(b.ATTRIBUTE9,''ZZ'')
		AND NVL(a.ATTRIBUTE10,''ZZ'') = NVL(b.ATTRIBUTE10,''ZZ'')
		AND NVL(a.ATTRIBUTE11,''ZZ'') = NVL(b.ATTRIBUTE11,''ZZ'')

		AND a.ATTRIBUTE5 <> b.ATTRIBUTE5
		AND a.ATTRIBUTE6 <> b.ATTRIBUTE6
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE6 >= b.ATTRIBUTE5 AND a.ATTRIBUTE6 <= b.ATTRIBUTE6)
		OR (b.ATTRIBUTE6 >= a.ATTRIBUTE5 AND b.ATTRIBUTE6 <= a.ATTRIBUTE6)
		OR (a.ATTRIBUTE5 <= b.ATTRIBUTE5 AND a.ATTRIBUTE6 >= b.ATTRIBUTE6)

	UNION ALL

	--A 타입인데 stage가
from: MDLE, to: MDLEBIZ가 아니거나, from/to site가 plant/sales가 아닐때
	SELECT 
		''[데이터 이상-A Type의 Stage나 site 정보 확인 필요] 전진검사'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	WHERE
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_FORWARD_INSPECTION''
		AND a.VALID_YN = ''Y''
		AND SEGMENT4 = ''A''
		AND (
			ATTRIBUTE2 != ''MDLE'' 
			OR ATTRIBUTE4 != ''MDLEBIZ'' 
			OR ''PLANT'' != (SELECT SITE_TYPE FROM SCM_MST_SITE WHERE DIVISION_ID = SEGMENT3 AND SCM_SITE_ID = ATTRIBUTE1)
			OR ''SALES'' != (SELECT SITE_TYPE FROM SCM_MST_SITE WHERE DIVISION_ID = SEGMENT3 AND SCM_SITE_ID = ATTRIBUTE3)
			)

	UNION ALL

	--B 타입인데 stage가
from: MDLE, to: MDLE가 아니거나, from/to site가 plant가 아닐때
	SELECT 
		''[데이터 이상-B Type의 Stage나 site 정보 확인 필요] 전진검사'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	WHERE
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_FORWARD_INSPECTION''
		AND a.VALID_YN = ''Y''
		AND SEGMENT4 = ''B''
		AND (
			ATTRIBUTE2 != ''MDLE'' 
			OR ATTRIBUTE4 != ''MDLE'' 
			OR ''PLANT'' != (SELECT SITE_TYPE FROM SCM_MST_SITE WHERE DIVISION_ID = SEGMENT3 AND SCM_SITE_ID = ATTRIBUTE1)
			OR ''PLANT'' != (SELECT SITE_TYPE FROM SCM_MST_SITE WHERE DIVISION_ID = SEGMENT3 AND SCM_SITE_ID = ATTRIBUTE3)
			)

	UNION ALL

	SELECT 
		''[중복 데이터] 자재/포장재의 입고 예정정보'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	WHERE
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_INCOMMING_MATERIAL'' AND
		a.VALID_YN = ''Y'' AND
		EXISTS (
			SELECT 1
			FROM SCM_ADM_LOOKUP_MASTER_DETAIL b
			WHERE 
				a.LOOKUP_TYPE = b.LOOKUP_TYPE AND
				a.SEGMENT2 = b.SEGMENT2 AND
				a.SEGMENT3 = b.SEGMENT3 AND
				a.SEGMENT5 = b.SEGMENT5 AND
				a.ATTRIBUTE1 = b.ATTRIBUTE1 AND

				a.VALID_YN = b.VALID_YN AND
				CONCAT(a.SEGMENT1, a.DISPLAY_SEQ) != CONCAT(b.SEGMENT1, b.DISPLAY_SEQ) 
		)

	UNION ALL

	SELECT 
		''[구간 중복] 출하 계획 포장재 제약'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_PACKING_EQUIPMENT''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = ') || TO_CLOB('b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.SEGMENT5 = b.SEGMENT5
		AND a.ATTRIBUTE1 = b.ATTRIBUTE1
		AND a.ATTRIBUTE2 <> b.ATTRIBUTE2
		AND a.ATTRIBUTE3 <> b.ATTRIBUTE3
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE3 >= b.ATTRIBUTE2 AND a.ATTRIBUTE3 <= b.ATTRIBUTE3)
		OR (b.ATTRIBUTE3 >= a.ATTRIBUTE2 AND b.ATTRIBUTE3 <= a.ATTRIBUTE3)
		OR (a.ATTRIBUTE2 <= b.ATTRIBUTE2 AND a.ATTRIBUTE3 >= b.ATTRIBUTE3)

	UNION ALL

	SELECT 
		''[구간 중복] 선행생산 일수(max_cover_day)'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_PRECEDE''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.SEGMENT5 = b.SEGMENT5
		AND a.ATTRIBUTE1 <> b.ATTRIBUTE1
		AND a.ATTRIBUTE2 <> b.ATTRIBUTE2
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE2 >= b.ATTRIBUTE1 AND a.ATTRIBUTE2 <= b.ATTRIBUTE2)
		OR (b.ATTRIBUTE2 >= a.ATTRIBUTE1 AND b.ATTRIBUTE2 <= a.ATTRIBUTE2)
		OR (a.ATTRIBUTE1 <= b.ATTRIBUTE1 AND a.ATTRIBUTE2 >= b.ATTRIBUTE2)

	UNION ALL

	SELECT 
		''[구간 중복] 안전 재고(min_cover_day)'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_SAFETY_STOCK''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.SEGMENT5 = b.SEGMENT5
		AND a.ATTRIBUTE1 <> b.ATTRIBUTE1
		AND a.ATTRIBUTE2 <> b.ATTRIBUTE2
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE2 >= b.ATTRIBUTE1 AND a.ATTRIBUTE2 <= b.ATTRIBUTE2)
		OR (b.ATTRIBUTE2 >= a.ATTRIBUTE1 AND b.ATTRIBUTE2 <= a.ATTRIBUTE2)
		OR (a.ATTRIBUTE1 <= b.ATTRIBUTE1 AND a.ATTRIBUTE2 >= b.ATTRIBUTE2)

	UNION ALL

	SELECT 
		''[구간 중복] 안전 재고(min_stock_Qty)'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_SAFETY_STOCK_QTY''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.SEGMENT5 = b.SEGMENT5
		AND a.ATTRIBUTE5 = b.ATTRIBUTE5
		AND a.ATTRIBUTE1 <> b.ATTRIBUTE1
		AND a.ATTRIBUTE2 <> b.ATTRIBUTE2
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE2 >= b.ATTRIBUTE1 AND a.ATTRIBUTE2 <= b.ATTRIBUTE2)
		OR (b.ATTRIBUTE2 >= a.ATTRIBUTE1 AND b.ATTRIBUTE2 <= a.ATTRIBUTE2)
		OR (a.ATTRIBUTE1 <= b.ATTRIBUTE1 AND a.ATTRIBUTE2 >= b.ATTRIBUTE2)

	UNION ALL

	SELECT 
		''[중복 데이터] 형교환'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	WHERE
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_SETUP'' AND
		a.VALID_YN = ''Y'' AND
		EXISTS (
			SELECT 1
			FROM SCM_ADM_LOOKUP_MASTER_DETAIL b
			WHERE 
				a.LOOKUP_TYPE = b.LOOKUP_TYPE AND
				a.SEGMENT2 = b.SEGMENT2 AND
				a.SEGMENT3 = b.SEGMENT3 AND
				a.SEGMENT4 = b.SEGMENT4 AND
				a.SEGMENT5 = b.SEGMENT5 AND
				a.ATTRIBUTE1 = b.ATTRIBUTE1 AND
				a.ATTRIBUTE2 = b.ATTRIBUTE2 AND

				a.VALID_YN = b.VALID_YN AND
				CONCAT(a.SEGM') || TO_CLOB('ENT1, a.DISPLAY_SEQ) != CONCAT(b.SEGMENT1, b.DISPLAY_SEQ) 
		)

	UNION ALL

	SELECT 
		''[구간 중복] Sales site별 우선순위'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_TOSITE_PRIORITY''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.ATTRIBUTE1 <> b.ATTRIBUTE1
		AND a.ATTRIBUTE2 <> b.ATTRIBUTE2
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE2 >= b.ATTRIBUTE1 AND a.ATTRIBUTE2 <= b.ATTRIBUTE2)
		OR (b.ATTRIBUTE2 >= a.ATTRIBUTE1 AND b.ATTRIBUTE2 <= a.ATTRIBUTE2)
		OR (a.ATTRIBUTE1 <= b.ATTRIBUTE1 AND a.ATTRIBUTE2 >= b.ATTRIBUTE2)

	UNION ALL

	SELECT 
		''[중복 데이터] Group Master'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	WHERE
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_CONST_DEMAND_GROUP'' AND
		a.VALID_YN = ''Y'' AND
		EXISTS (
			SELECT 1
			FROM SCM_ADM_LOOKUP_MASTER_DETAIL b
			WHERE 
				a.LOOKUP_TYPE = b.LOOKUP_TYPE AND
				a.SEGMENT2 = b.SEGMENT2 AND
				a.SEGMENT3 = b.SEGMENT3 AND
				a.SEGMENT5 = b.SEGMENT5 AND

				a.VALID_YN = b.VALID_YN AND
				CONCAT(a.SEGMENT1, a.ATTRIBUTE1, a.ATTRIBUTE2, a.DISPLAY_SEQ) != CONCAT(b.SEGMENT1, b.ATTRIBUTE1, b.ATTRIBUTE2, b.DISPLAY_SEQ) 
		)

	UNION ALL

	SELECT 
		''[중복 데이터] 생산 Fix'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	WHERE
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_PROD_FIX'' AND
		a.VALID_YN = ''Y'' AND
		EXISTS (
			SELECT 1
			FROM SCM_ADM_LOOKUP_MASTER_DETAIL b
			WHERE 
				a.LOOKUP_TYPE = b.LOOKUP_TYPE AND
				a.SEGMENT2 = b.SEGMENT2 AND
				a.SEGMENT3 = b.SEGMENT3 AND
				a.SEGMENT4 = b.SEGMENT4 AND
				a.SEGMENT5 = b.SEGMENT5 AND
				a.ATTRIBUTE1 = b.ATTRIBUTE1 AND
				a.ATTRIBUTE2 = b.ATTRIBUTE2 AND
				a.ATTRIBUTE3 = b.ATTRIBUTE3 AND

				a.VALID_YN = b.VALID_YN AND
				CONCAT(a.SEGMENT1, a.DISPLAY_SEQ) != CONCAT(b.SEGMENT1, b.DISPLAY_SEQ) 
		)

	UNION ALL

	SELECT 
		''[구간 중복] Ramp up'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	JOIN 
		SCM_ADM_LOOKUP_MASTER_DETAIL b
	ON 
		a.LOOKUP_TYPE = ''SCP_OPT_ENG_RAMPUP''
		AND a.LOOKUP_TYPE = b.LOOKUP_TYPE
		AND a.SEGMENT2 = b.SEGMENT2
		AND a.SEGMENT3 = b.SEGMENT3
		AND a.SEGMENT4 = b.SEGMENT4
		AND a.SEGMENT5 = b.SEGMENT5
		AND a.ATTRIBUTE2 <> b.ATTRIBUTE2
		AND a.ATTRIBUTE3 <> b.ATTRIBUTE3
		AND a.VALID_YN = ''Y''
		AND b.VALID_YN = ''Y''
	WHERE (a.ATTRIBUTE3 >= b.ATTRIBUTE2 AND a.ATTRIBUTE3 <= b.ATTRIBUTE3)
		OR (b.ATTRIBUTE3 >= a.ATTRIBUTE2 AND b.ATTRIBUTE3 <= a.ATTRIBUTE3)
		OR (a.ATTRIBUTE2 <= b.ATTRIBUTE2 AND a.ATTRIBUTE3 >= b.ATTRIBUTE3)

	UNION ALL

	SELECT 
		''[중복 데이터] Capa 임시'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	WHERE
		a.LOOKUP_TYPE = ''SCP_OPT_MASTER_CAPA_TEMP'' AND
		a.VALID_YN = ''Y'' AND
		EXISTS (
			SELECT 1
			FROM SCM_ADM_LOOKUP_MASTER_DETAIL b
			WHERE 
				a.LOOKUP_TYPE = b.LOOKUP_TYP') || TO_CLOB('E AND
				a.SEGMENT2 = b.SEGMENT2 AND
				a.SEGMENT3 = b.SEGMENT3 AND
				a.SEGMENT4 = b.SEGMENT4 AND
				a.SEGMENT5 = b.SEGMENT5 AND
				a.ATTRIBUTE1 = b.ATTRIBUTE1 AND
				a.ATTRIBUTE2 = b.ATTRIBUTE2 AND
				a.ATTRIBUTE3 = b.ATTRIBUTE3 AND

				a.VALID_YN = b.VALID_YN AND
				CONCAT(a.SEGMENT1, a.DISPLAY_SEQ) != CONCAT(b.SEGMENT1, b.DISPLAY_SEQ) 
		)

	UNION ALL

	SELECT 
		''[중복 데이터] 비조업 정리본'' as Contents
		,a.LOOKUP_TYPE, a.SEGMENT2, a.SEGMENT3, a.SEGMENT4,a.SEGMENT5, a.ATTRIBUTE1, a.ATTRIBUTE2, a.ATTRIBUTE3, a.ATTRIBUTE4, a.ATTRIBUTE5, a.ATTRIBUTE6, a.ATTRIBUTE7, a.ATTRIBUTE8, a.ATTRIBUTE9, a.ATTRIBUTE10
	FROM 
		SCM_ADM_LOOKUP_MASTER_DETAIL a
	WHERE
		a.LOOKUP_TYPE = ''SCP_OPT_MASTER_NOWORK2_TEMP'' AND
		a.VALID_YN = ''Y'' AND
		EXISTS (
			SELECT 1
			FROM SCM_ADM_LOOKUP_MASTER_DETAIL b
			WHERE 
				a.LOOKUP_TYPE = b.LOOKUP_TYPE AND
				a.SEGMENT1 = b.SEGMENT1 AND
				a.SEGMENT2 = b.SEGMENT2 AND
				a.SEGMENT3 = b.SEGMENT3 AND
				a.SEGMENT5 = b.SEGMENT5 AND

				a.VALID_YN = b.VALID_YN AND
				CONCAT(a.SEGMENT4, a.DISPLAY_SEQ) != CONCAT(b.SEGMENT4, b.DISPLAY_SEQ) 
		)
) MAIN
WHERE 1=1
AND LOOKUP_TYPE = (CASE WHEN :PARAM_LOOKUP_TYPE = '''' THEN LOOKUP_TYPE ELSE :PARAM_LOOKUP_TYPE END )
'), 'Y', 'Y', 'jaeuk.shin', TO_DATE('2025-05-14 08:52:07','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:21','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (112, '-', '-', '-', '-', 'N', 'Y', 'lges_anhnv', TO_DATE('2026-03-09 15:34:42','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:08:17','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (113, '-', '-', '-', '-', 'N', 'Y', 'lges_anhnv', TO_DATE('2026-03-09 16:55:28','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:08:17','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (114, '-', 'fff', '-', '-', 'N', 'Y', 'lges_anhnv', TO_DATE('2026-03-09 16:57:56','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:08:17','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (115, '-', 'SCP 타겟', '자동차 SCM 매월 KPI로 산출하는 내용에 대한 RAW DATA', 'SELECT 
DIVISION_ID	
,PLAN_START_YYYYMMDD	
,PLAN_TYPE	
,SEQ	
,OPERATION_GROUP	
,SCM_SITE_ID	
,ITEM_ID	
,LINE_ID	
,OPERATION_ID	
,MEASURE	
,YYYYMMDD	
,QTY	
,ORIGIN_DIVISION_ID	
,ELECTRODE_TYPE	
,CREATED_BY	
,CREATION_DATE	
,LAST_UPDATED_BY	
,LAST_UPDATE_DATE	
,ATTRIBUTE1	
,ATTRIBUTE2	
,ATTRIBUTE3	
,ATTRIBUTE4	
,ATTRIBUTE5	
,ATTRIBUTE6	
,ATTRIBUTE7	
,ATTRIBUTE8	
,ATTRIBUTE9	
,ATTRIBUTE10	
,CELL_QTY
FROM SCP_ANL_PRODUCTION_PLAN A 
WHERE PLAN_TYPE = ''FN''
AND DIVISION_ID LIKE :PARAM_DIVISION_ID || ''%''
AND QTY > 0
AND PLAN_START_YYYYMMDD BETWEEN  :PARAM_FROM_PLAN_DATE AND :PARAM_TO_PLAN_DATE
AND MEASURE = ''PROD_PLAN_AMEND''
AND YYYYMMDD BETWEEN PLAN_START_YYYYMMDD AND CONVERT(CHAR(8),(CONVERT(DATE,PLAN_START_YYYYMMDD, 112)) + (56),112)
AND SEQ = (
	SELECT MAX(SEQ) FROM SCP_ANL_PRODUCTION_PLAN B 
	WHERE A.DIVISION_ID = B.DIVISION_ID 
	AND A.PLAN_START_YYYYMMDD = B.PLAN_START_YYYYMMDD 
	AND A.PLAN_TYPE = B.PLAN_TYPE
)', 'Y', 'Y', 'yanbn82', TO_DATE('2026-04-02 09:31:46','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (116, '-', 'FP 타겟', 'SCM KPI FP-SCP 동기화율 산출을 위한 Raw Data', 'SELECT A.DIVISION_ID, TO_CHAR(A.CUTOFF_DATE, ''YYYYMMDD'') AS CUTOFF_DATE , A.COMPANY_ID, A.PLANT_ID, A.INSTANCE_TYPE, A.OPERATION_ID, A.ITEM_ID
, A.PRODUCTION_TYPE, A.LINE_ID, B.BASIS_YYYYMM, B.WEEK_NAME,TO_CHAR(A.PLAN_DATE, ''YYYYMMDD'') AS PLAN_DATE, A.PLAN_QTY
FROM LGCE_FPDEV_TR.FP_DAILY_PRODUCTION_PLAN_CUTOFF_H A
JOIN LGCE_SCMDEV.SCM_SYS_CALENDAR_M B
ON A.PLAN_DATE = B.BASIS_DATE
WHERE 1=1
AND A.CUTOFF_DATE BETWEEN :PARAM_FROM_PLAN_DATE AND :PARAM_TO_PLAN_DATE
--AND A.PLANT_ID = ''WA00''
AND A.DIVISION_ID LIKE :PARAM_DIVISION_ID || ''%''
AND A.OPERATION_ID IN (''A9000'', ''P5500'',''P9500'')
AND A.PLAN_TYPE = ''RELEASE''
AND A.CUTOFF_DATE = A.PLAN_DATE
AND B.DAYOFWEEK IN (''MON'', ''TUE'')

UNION ALL

 --수요일에본 나머지
SELECT A.DIVISION_ID, TO_CHAR(A.CUTOFF_DATE, ''YYYYMMDD'') AS CUTOFF_DATE, A.COMPANY_ID, A.PLANT_ID, A.INSTANCE_TYPE, A.OPERATION_ID, A.ITEM_ID
, A.PRODUCTION_TYPE, A.LINE_ID, B.BASIS_YYYYMM, B.WEEK_NAME,TO_CHAR(A.PLAN_DATE, ''YYYYMMDD'') AS PLAN_DATE, A.PLAN_QTY
FROM LGCE_FPDEV_TR.FP_DAILY_PRODUCTION_PLAN_CUTOFF_H A
JOIN LGCE_SCMDEV.SCM_SYS_CALENDAR_M B
ON A.CUTOFF_DATE = B.BASIS_DATE
WHERE 1=1
AND A.CUTOFF_DATE BETWEEN :PARAM_FROM_PLAN_DATE AND :PARAM_TO_PLAN_DATE
--AND A.PLANT_ID = ''WA00''
AND A.DIVISION_ID LIKE :PARAM_DIVISION_ID || ''%''
AND A.OPERATION_ID IN (''A9000'', ''P5500'',''P9500'')
AND A.PLAN_TYPE = ''RELEASE''
AND B.DAYOFWEEK = ''WED''
AND A.PLAN_TYPE = ''RELEASE''
AND B.DAYOFWEEK = ''TUE''', 'Y', 'Y', 'yanbn82', TO_DATE('2026-04-02 09:54:02','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:04:20','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (84, '-', '소형 Stock Detail', '소형 Stock Detail', TO_CLOB('SELECT  
	 DIVISION_ID			AS DIV
	,FROM_SITE				AS SITE
	,ITEM_ID				AS MODEL
	,NICK_NAME				AS NICK_NAME
	,LOT_ID					AS LOT_ID
	,YYYYMMDD_LOT_ID_APPLIED_LT AS D_DAY_EXPECTED
	,MES_CHANGE_STATUS		AS CHANGE_STATUS
	,LOT_TYPE				AS LOT_TYPE
	,TO_CHAR(CONVERT(INT,MES_ASSY_QTY))			AS MES_ASSY_QTY
	,TO_CHAR(CONVERT(INT,LOT_QTY_MES))				AS GMES_LOT_QTY
	,TO_CHAR(CONVERT(INT,LOT_QTY_MES_NG))			AS GMES_LOT_NG_QTY
	,TO_CHAR(CONVERT(INT,LOT_QTY_FCS))				AS FCS_LOT_QTY
    ,TO_CHAR(CONVERT(INT,FCS_SPECIAL_QTY))			AS SPECIAL_LOT_QTY
    ,TO_CHAR(CONVERT(INT,OWMS_STOCK_QTY))			AS OWMS_STOCK_QTY
	,TO_CHAR(CONVERT(INT,OWMS_RESULT_QTY))			AS OWMS_SHIP_QTY
    ,USER_MOD_RELEASE_DATE	AS USER_MODIFIED_RELEASE_DATE
    ,AVAILABLE_YN			AS AVAILABLE_STOCK_YN
    ,MES_HOLD_YN			AS MES_HOLD_YN
    ,QMS_HOLD_YN			AS QMS_HOLD_YN
    ,FCS_HOLD_YN			AS FCS_HOLD_YN
    ,REMARKS				AS REMARKS
    ,JUDG_VLD_DATE			AS JUDGE_VAILD_DATE
    ,MES_HOLD_RELEASE		AS MES_UNHOLD_SCHED_DATE
    ,QMS_HOLD_RELEASE		AS QMS_UNHOLD_SCHED_DATE
    ,LAST_UPDATED_BY		AS LAST_UPDATED_BY
    ,TO_CHAR(LAST_UPDATE_DATE, ''YYYY-MM-DD HH24:MI:SS'')		AS LAST_UPDATED_DATE
FROM
(
	SELECT  ROW_NUMBER() OVER(PARTITION BY T1.DIVISION_ID,T1.FROM_SITE,T1.ITEM_ID,T1.LOT_ID ORDER BY T1.LOT_TYPE DESC,T1.MES_CHANGE_STATUS DESC) AS ROWNUM
		,T1.DIVISION_ID		
		,T1.FROM_SITE		
		,T1.ITEM_ID			
		,T1.NICK_NAME		
		,T1.LOT_ID			
		,T1.YYYYMMDD_LOT_ID_APPLIED_LT 
		,T1.MES_CHANGE_STATUS
		,T1.LOT_TYPE
		,T1.LOT_QTY_MES
		,T1.LOT_QTY_FCS
		,T1.FCS_SPECIAL_QTY
		,T1.OWMS_STOCK_QTY
		,T1.LOT_QTY_TOT
		,T1.AVAILABLE_YN
		,T1.MES_HOLD_YN
		,T1.QMS_HOLD_YN
		,T1.FCS_HOLD_YN
		,T1.LONGTERM_HOLD_YN
		,T1.JUDG_VLD_DATE
		,T1.MES_HOLD_RELEASE
		,T1.QMS_HOLD_RELEASE
		,T1.USER_MOD_RELEASE_DATE
		,T1.REMARKS
		,T1.LAST_UPDATED_BY
		,T1.LAST_UPDATE_DATE
		,T1.MES_ASSY_QTY
		,T1.OWMS_RESULT_QTY
		,T1.LOT_QTY_MES_NG
	FROM
	(
		SELECT
				X.DIVISION_ID
				,X.FROM_SITE
				,X.ITEM_ID
				,FN_GET_ITEM_NICKNAME(X.DIVISION_ID, X.ITEM_ID) AS NICK_NAME
				--,SUBSTR(X.LOT_ID, 1,9) AS LOT_ID
				,X.LOT_ID AS LOT_ID
				,TO_CHAR(CONVERT(DATE, TO_CHAR(X.YYYYMMDD_LOT_ID_APPLIED_LT))) AS YYYYMMDD_LOT_ID_APPLIED_LT
				,X.CHANGE_STATUS AS MES_CHANGE_STATUS
				,X.LOT_TYPE
				,X.LOT_QTY_MES
				,X.LOT_QTY_FCS
				,X.FCS_SPECIAL_QTY
				,X.OWMS_STOCK_QTY
				,X.LOT_QTY_TOT   AS LOT_QTY_TOT
				,X.AVAILABLE_YN
				,X.MES_HOLD_YN
				,X.QMS_HOLD_YN
				,X.FCS_HOLD_YN
				,X.LONGTERM_HOLD_YN
				,TO_CHAR(TO_DATE(CASE X.JUDG_VLD_DATE WHEN ''-'' THEN NULL ELSE X.JUDG_VLD_DATE END, ''YYYYMMDD''), ''YYYY-MM-DD'') AS JUDG_VLD_DATE
				,TO_CHAR(TO_DATE(CASE X.MES_HOLD_RELEASE WHEN ''-'' THEN NULL ELSE X.MES_HOLD_RELEASE END, ''YYYYMMDD''), ''YYYY-MM-DD'') AS MES_HOLD_RELEASE
				,TO_CHAR(TO_DATE(CASE X.QMS_HOLD_RELEASE WHEN ''-'' THEN NULL ELSE X.QMS_HOLD_RELEASE END, ''YYYYMMDD''), ''YYYY-MM-DD'') AS QMS_HOLD_RELEASE
				,TO_CHAR(TO_DATE(CASE X.USER_MOD_RELEASE_DATE WHEN '''' THEN NULL ELSE X.USER_MOD_RELEASE_DATE END, ''YYYYMMDD''), ''YYYY-MM-DD'') AS USER_MOD_RELEASE_DATE
				,X.REMARKS
				,CASE WHEN ''KO'' = ''KO'' THEN U.USERNAME ELSE U.USERNAME_E END || ''('' || X.LAST_UPDATED_BY || '')'' AS LAST_UPDATED_BY
				,X.LAST_UPDATE_DATE
				,NVL(A.MES_ASSY_QTY, 0)		AS MES_ASSY_QTY
				,NVL(W.OWMS_RESULT_QTY, 0)	AS OWMS_RESULT_QTY
				,NVL(X.ATTRIBUTE4, 0)        AS LOT_QTY_MES_NG
			FROM SSP_ANL_MES_FCS_STOCK_40_C X
				    LEFT OUTER JOIN (SELECT DIVISION_ID, FROM_SITE, ITEM_ID, LOT_ID, SUM(WIPQTY2_ED) AS MES_ASSY_QTY
									FROM SSP_DNM_MES_WIP_HISTORY
                                    GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, LOT_ID) AS A
				ON X.DIVISION_ID	= A.DIVISION_ID 
				AND X.FROM_SITE	= A.FROM_SITE
				AND X.ITEM_ID		= A.ITEM_ID
				AND X.LOT_ID		= A.LOT_ID
				    LEFT OUTER JOIN (SELECT DIVISION_ID, FROM_SITE, ITEM_ID, SUBSTR(LOT_ID,1,8) AS LOT_ID, SUM(LOT_QTY) AS OWMS_RESULT_QTY
                                   ') || TO_CLOB(' FROM SSP_DNM_SHIP_RESULT_OWMS A 
                                    GROUP BY 
									        DIVISION_ID, FROM_SITE, ITEM_ID, SUBSTR(LOT_ID,1,8)
                                    ) AS W
				ON X.DIVISION_ID	= W.DIVISION_ID 
				AND X.FROM_SITE	= W.FROM_SITE
				AND X.ITEM_ID		= W.ITEM_ID
				AND X.LOT_ID		= W.LOT_ID
				    LEFT OUTER JOIN TB_FX_USER U 
				ON X.LAST_UPDATED_BY = U.USERID 
				AND U.USEYN = ''Y''
			WHERE X.DIVISION_ID = ''40'' 
				AND X.PLAN_START_YYYYMMDD	= ''20210721'' 
				AND ( ( ''G182-A''    IS NULL OR ''G182-A''  ='''')  OR X.FROM_SITE IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT(''G182-A'' ,'','')) )
				AND ( ( ''''    IS NULL OR ''''  ='''')  OR X.ITEM_ID IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT('''' ,'','')) )
				AND ( ( ''''    IS NULL OR ''''  ='''')  OR X.LOT_ID IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT('''' ,'','')) )
			UNION ALL
			SELECT 
					A.DIVISION_ID
				,A.FROM_SITE 
				,A.ITEM_ID
				,FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID ) AS NICK_NAME
				,SUBSTR(A.LOT_ID, 1,9) AS LOT_ID
				,NULL   AS YYYYMMDD_LOT_ID_APPLIED_LT
				,NULL AS MES_CHANGE_STATUS
				,NULL AS LOT_TYPE
				,0 AS LOT_QTY_MES
				,0 AS LOT_QTY_FCS
				,0 AS FCS_SPECIAL_QTY
				,SUM(A.STOCK_QTY) AS OWMS_STOCK_QTY
				,0 AS LOT_QTY_TOT
				,''-'' AS AVAILABLE_YN
				,''-'' AS MES_HOLD_YN
				,''-'' AS QMS_HOLD_YN
				,''-'' AS FCS_HOLD_YN
				,''-'' AS LONGTERM_HOLD_YN
				,NULL AS JUDG_VLD_DATE
				,NULL AS MES_HOLD_RELEASE
				,NULL AS QMS_HOLD_RELEASE
				,NULL AS USER_MOD_RELEASE_DATE
				,NULL AS REMARKS
				,NULL AS LAST_UPDATE_BY
				,NULL AS LAST_UPDATE_DATE
				,0		AS MES_ASSY_QTY
				,SUM(NVL(W.OWMS_RESULT_QTY, 0))		AS OWMS_RESULT_QTY
				,0      AS LOT_QTY_MES_NG
			FROM SSP_ANL_OWMS_STOCK_C A
					LEFT OUTER JOIN SCM_MST_SLOC B 
				ON B.DIVISION_ID = A.DIVISION_ID  
				AND B.STORAGE_ID = A.STORAGE_ID 
				AND B.PLANT_ID = A.PLANT_ID
				    LEFT OUTER JOIN (SELECT DIVISION_ID, FROM_SITE, ITEM_ID, SUBSTR(LOT_ID,1,8) AS LOT_ID, SUM(LOT_QTY) AS OWMS_RESULT_QTY
                                    FROM SSP_DNM_SHIP_RESULT_OWMS A 
                                    GROUP BY 
									        DIVISION_ID, FROM_SITE, ITEM_ID, SUBSTR(LOT_ID,1,8)
                                    ) AS W
				ON A.DIVISION_ID	= W.DIVISION_ID 
				AND A.FROM_SITE	= W.FROM_SITE
				AND A.ITEM_ID		= W.ITEM_ID
				AND A.LOT_ID		= W.LOT_ID
		WHERE A.DIVISION_ID = ''40'' 
			AND A.PLAN_START_YYYYMMDD = ''20210721'' 
			AND ( ( ''G182-A''    IS NULL OR ''G182-A''  ='''')  OR A.FROM_SITE IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT(''G182-A'' ,'','')) )
			AND ( ( ''''    IS NULL OR ''''  ='''')  OR A.ITEM_ID IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT('''' ,'','')) )
			AND ( ( ''''    IS NULL OR ''''  ='''')  OR A.LOT_ID IN (SELECT TOKEN FROM /*STRING_SPLIT_NEEDS_REGEXP_SUBSTR_CONNECT_BY*/STRING_SPLIT('''' ,'','')) )
			GROUP BY A.DIVISION_ID
					,A.ORIGIN_FROM_DIVISION_ID
					,A.FROM_SITE 
					,A.ITEM_ID
					,SUBSTR(A.LOT_ID, 1,9)
	) T1
) T2
WHERE T2.ROWNUM = 1'), 'Y', 'Y', 'crjung', TO_DATE('2021-07-27 11:24:47','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:26:13','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (85, '-', 'Shipment_Check_40', 'Shipment_Check_40', 'SELECT 
       BB.PLAN_START_YYYYMMDD
      ,BB.PROJECT_CODE 
      ,BB.ITEM_ID
	  ,(SELECT /* TODO: add WHERE ROWNUM <= 1 or FETCH FIRST 1 ROWS ONLY */ NICK_NAME   
          FROM SCP_MST_FINAL_ITEM B  
         WHERE BB.ITEM_ID = B.ITEM_ID AND NICK_NAME IS NOT NULL 
          ) AS NICK_NAME 
      ,BB.TO_SITE
	  ,BB.REQ_M0
	  ,BB.REQ_M1
	  ,BB.REQ_M2
	  ,BB.REQ_M3
	  ,BB.REQ_M4
	  ,BB.PLAN_M0
	  ,BB.PLAN_M1
	  ,BB.PLAN_M2
	  ,BB.PLAN_M3
	  ,BB.PLAN_M4
      ,(BB.REQ_M0-BB.PLAN_M0) AS ''GAP_M0''
	  ,(BB.REQ_M1-BB.PLAN_M1) AS ''GAP_M1''
      ,(BB.REQ_M2-BB.PLAN_M2) AS ''GAP_M2''
      ,(BB.REQ_M3-BB.PLAN_M3) AS ''GAP_M3''
      ,(BB.REQ_M4-BB.PLAN_M4) AS ''GAP_M4''
  FROM 
(SELECT  AA.PLAN_START_YYYYMMDD
        ,AA.PROJECT_CODE 
        ,AA.ITEM_ID
        ,AA.TO_SITE
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,0), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_REQ'' THEN QTY ELSE 0 END) AS ''REQ_M0''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,1), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_REQ'' THEN QTY ELSE 0 END) AS ''REQ_M1''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,2), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_REQ'' THEN QTY ELSE 0 END) AS ''REQ_M2''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,3), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_REQ'' THEN QTY ELSE 0 END) AS ''REQ_M3''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,4), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_REQ'' THEN QTY ELSE 0 END) AS ''REQ_M4''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,0), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_PLAN_AMEND'' THEN QTY ELSE 0 END) AS ''PLAN_M0''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,1), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_PLAN_AMEND'' THEN QTY ELSE 0 END) AS ''PLAN_M1''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,2), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_PLAN_AMEND'' THEN QTY ELSE 0 END) AS ''PLAN_M2''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,3), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_PLAN_AMEND'' THEN QTY ELSE 0 END) AS ''PLAN_M3''
        ,SUM(CASE WHEN SUBSTR(YYYYMMDD,1,6) = SUBSTR(TO_CHAR(LAST_DAY(:PARAM_PLAN_START_YYYYMMDD,4), ''YYYYMMDD''),1,6) AND MEASURE = ''SHIP_PLAN_AMEND'' THEN QTY ELSE 0 END) AS ''PLAN_M4''
   FROM LGCE_SCMPROD.SCP_ANL_SHIPMENT_PLAN_FG AA
  WHERE 1 = 1 
    AND AA.DIVISION_ID = ''40''
    AND AA.PLAN_TYPE = :PARAM_PLAN_TYPE
    AND AA.SEQ = :PARAM_PLAN_SEQ
    AND AA.QTY <> 0 
    AND AA.BIZ_TYPE = ''P''
    AND AA.PLAN_START_YYYYMMDD = :PARAM_PLAN_START_YYYYMMDD
  GROUP 
     BY  AA.PLAN_START_YYYYMMDD
        ,AA.PROJECT_CODE
        ,AA.ITEM_ID
        ,AA.TO_SITE
	 ) BB
 ', 'Y', 'Y', 'attackgo', TO_DATE('2022-01-07 20:19:34','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 11:02:37','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (86, '-', 'User Menu Access Count_Period', '사용자 일자별 메뉴접속 Count_기간', 'select 
       CASE a.MenuID WHEN ''Sales Site Project M'' THEN ''Sales Site Project Model''
	                 WHEN ''Customer Model Mappi'' THEN ''Customer Model Mapping''
					 ELSE a.MenuID END MENU_ID
	  ,a.UserID
      ,us.USER_NAME
	  , max( (case when dept.DEPT_NAME_KO is not null then dept.DEPT_NAME_KO else us.WORKING_NAME end ) ) DEPT_NAME_KO
	  ,TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') LOGIN_DATE
	  ,count(1) counts
      --,COUNT(1) OVER(ORDER BY a.UserID) sum_count
from TB_FX_MenuConnectLog a
      left outer join SCM_MST_SSO_USER_INFO us
	  on (a.UserID = us.USER_ID)
      left outer join SCM_MST_SSO_DEPT_INFO dept
	  on (us.DEPT_ID = dept.DEPT_ID)
 where 1=1
   and a.UserID = us.USER_ID
   and dept.DEPT_NAME_KO not like ''LG CNS%''
   and TO_CHAR(LocalTimeStamp, ''YYYYMMDD'') >= ''20180330''
   and a.menuid IS NOT NULL
   and LocalTimeStamp between TO_CHAR(:PARAM_FROMDATE, ''YYYYMMDD'') and TO_CHAR(:PARAM_TODATE, ''YYYYMMDD'')
group by a.MenuID
	  ,a.UserID
      ,us.USER_NAME
	  ,TO_CHAR(LocalTimeStamp, ''YYYYMMDD'')


', 'Y', 'Y', 'attackgo', TO_DATE('2022-01-11 17:48:24','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:21','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (87, '-', 'Shipment_Result_ERP_VS_OWMS', 'ERP_VS_OWMS SSP 출하실적비교', TO_CLOB('
SELECT 
 BB.DIVISION_ID
,BB.YYYYMMDD
,BB.ITEM_ID
,BB.FROM_SITE
,BB.ERP
,BB.OWMS
,BB.GAP

  FROM (
         SELECT 
                 AA.DIVISION_ID
                ,AA.YYYYMMDD
                ,AA.ITEM_ID
                ,AA.FROM_SITE
                ,SUM(CASE AA.TYPE WHEN ''ERP'' THEN AA.QTY ELSE 0  END) AS ''ERP''
                ,SUM(CASE AA.TYPE WHEN ''OWMS'' THEN AA.QTY ELSE 0 END) AS ''OWMS''
                ,SUM(CASE AA.TYPE WHEN ''ERP'' THEN AA.QTY ELSE 0  END) - SUM(CASE AA.TYPE WHEN ''OWMS'' THEN AA.QTY ELSE 0 END) AS ''GAP''
           FROM 
   (    SELECT  
         E.DIVISION_ID         AS DIVISION_ID
        , ''ERP''                AS TYPE
        ,E.CONFIRM_ID          AS CONFIRM_ID
        ,E.ORDER_NO            AS ERP_SO_NO 
        ,E.EXFACTORY_DATE      AS YYYYMMDD
        ,E.TRANSPORT_MODE      AS TRANSPORT_MODE
        ,E.INCOTERMS           AS INCOTERMS
        ,E.ETA_DATE            AS ETA_DATE
        ,E.ETD_DATE            AS ETD_DATE
        ,E.FROM_SCM_SITE_ID    AS FROM_SITE
        ,E.TO_SCM_SITE_ID      AS TO_SITE
        ,E.ITEM_ID             AS ITEM_ID
        ,SUM(E.EXFACTORY_QTY ) AS QTY 
        FROM SCM_DNM_EXFACTORY_RESULT E
            JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
                ON L.LOOKUP_TYPE = ''ERP_SSP_TYPE'' -- LOOKUP에 등록된 공정만 
            AND L.VALID_YN = ''Y''
            AND L.SEGMENT1    = E.SSP_TYPE
        JOIN SCM_MST_SITE S                     
            ON E.FROM_SCM_SITE_ID    = S.SCM_SITE_ID                 
           AND E.DIVISION_ID    = S.DIVISION_ID                 
           AND S.SITE_TYPE        = ''PLANT''                                      
        JOIN SCM_MST_ITEM_SN T                 
            ON E.ITEM_ID        = T.ITEM_ID                     
           AND E.DIVISION_ID    = T.DIVISION_ID                 
           AND S.COMPANY_ID        = T.COMPANY_ID                 
           AND T.ITEM_TYPE        NOT IN (''Q'',''R'')
        WHERE 1=1
        AND   NVL(E.EXFACTORY_STATUS,''D90'') NOT IN (''D90'' ,''D10'') -- D90: DO삭제 , D10:DO생성 
        AND   E.CONFIRM_ID LIKE ''C%''
        AND   E.EXFACTORY_DATE BETWEEN :PARAM_FROM_YYYYMMDD  AND :PARAM_TO_YYYYMMDD 
                
        GROUP BY E.DIVISION_ID 
        ,        E.CONFIRM_ID
        ,        E.ORDER_NO
        ,        E.EXFACTORY_DATE
        ,        E.TRANSPORT_MODE
        ,        E.INCOTERMS        
        ,         E.ETA_DATE        
        ,         E.ETD_DATE
        ,         E.FROM_SCM_SITE_ID    
        ,         E.TO_SCM_SITE_ID    
        ,         E.ITEM_ID
        -- )
    -- , RESULT_ERP_C_NON AS 
    -- (
UNION ALL 
        -- ERP 출하실적에서 CONFIRM_ID 없는 실적 
        SELECT  E.DIVISION_ID             AS DIVISION_ID
        ,        ''ERP''                      AS TYPE
        ,       ''-''                       AS CONFIRM_ID
        ,       E.ORDER_NO                  AS ERP_SO_NO 
        ,       E.EXFACTORY_DATE          AS YYYYMMDD
        ,       E.TRANSPORT_MODE          AS TRANSPORT_MODE
        ,       E.INCOTERMS                  AS INCOTERMS
        ,        E.ETA_DATE                  AS ETA_DATE
        ,        E.ETD_DATE                  AS ETD_DATE
        ,       E.FROM_SCM_SITE_ID        AS FROM_SITE                                                                    
        ,       NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)     AS TO_SITE   
        ,       E.ITEM_ID                 AS ITEM_ID
        ,       SUM(E.EXFACTORY_QTY )     AS QTY  
        FROM SCM_DNM_EXFACTORY_RESULT E
        JOIN SCM_MST_SITE S                     
            ON E.FROM_SCM_SITE_ID    = S.SCM_SITE_ID                 
           AND E.DIVISION_ID    = S.DIVISION_ID                 
           AND S.SITE_TYPE        = ''PLANT''                                      
        JOIN SCM_MST_ITEM_SN T                 
            ON E.ITEM_ID        = T.ITEM_ID                ') || TO_CLOB('     
           AND E.DIVISION_ID    = T.DIVISION_ID                 
           AND S.COMPANY_ID        = T.COMPANY_ID                 
           AND T.ITEM_TYPE        NOT IN (''Q'',''R'')
        JOIN  SCP_MST_FINAL_ITEM F -- SCP 대상 ITEM만 
            ON F.ITEM_ID = E.ITEM_ID 
            AND F.DIVISION_ID = E.DIVISION_ID
        JOIN   SCM_MST_SITE FS
            ON FS.SCM_SITE_ID = E.FROM_SCM_SITE_ID 
           AND FS.DIVISION_ID = E.DIVISION_ID 
           -- AND NVL(FS.OSP_YN,''N'') <> ''Y'' --- [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN <> ''Y'' 조건제외)
           -- 2020.09.18 김광희 책임 요청으로 주석처리
           -- 2021.04.15 김광희 책임 요청으로 주석해제
        JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
            ON L.LOOKUP_TYPE = ''ERP_ORDER_TYPE'' -- LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 
        AND L.VALID_YN = ''Y''
        AND L.SEGMENT1    = E.ORDER_TYPE_CODE     
        LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L3
                ON L3.LOOKUP_TYPE = ''SHIP_RESULT_TO_SITE_MAPPING'' --SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE 
            AND L3.SEGMENT1    = E.DIVISION_ID 
            AND L3.SEGMENT2    = E.SOLDTO_CODE
            AND L3.SEGMENT3    = E.SHIPTO_CODE                        
        WHERE 1=1
        AND   NVL(E.EXFACTORY_STATUS,''D90'') NOT IN (''D90'' ,''D10'') -- D90: DO삭제 , D10:DO생성 
        AND   NVL(E.CONFIRM_ID,'''') NOT LIKE  ''C%''
        AND   E.EXFACTORY_DATE BETWEEN  :PARAM_FROM_YYYYMMDD  AND :PARAM_TO_YYYYMMDD 
        AND   E.STORAGE_ID NOT IN (''6000'' ,''799A'') --상품창고제외 
        AND   E.STORAGE_ID NOT IN (SELECT SEGMENT1 
                                FROM SCM_ADM_LOOKUP_MASTER_DETAIL 
                                WHERE LOOKUP_TYPE = ''SSP_SHIP_RESULT_EXCEPT_STORAGE''
                                    AND VALID_YN = ''Y''
                                )    -- 사외 창고 제외 LOOKUP 관리
GROUP BY E.DIVISION_ID
        ,        E.ORDER_NO
        ,        E.FROM_SCM_SITE_ID                                                                           
        ,        NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID) 
        ,        E.ITEM_ID
        ,        E.EXFACTORY_DATE
        ,        E.TRANSPORT_MODE
        ,        E.INCOTERMS        
        ,         E.ETA_DATE        
        ,         E.ETD_DATE
        ,         E.FROM_SCM_SITE_ID    
        ,         E.TO_SCM_SITE_ID    
    UNION ALL 
        -- OWMS 출하실적/반품 [C20191205-000132]
    SELECT     R.DIVISION_ID      AS DIVISION_ID
        ,        ''OWMS''              AS TYPE
        ,      ''-''                AS CONFIRM_ID
        ,      ''-''                AS ERP_SO_NO
        ,      R.YYYYMMDD         AS YYYYMMDD
        ,      R.YYYYMMDD         AS TRANSPORT_MODE
        ,      ''-''                  AS INCOTERMS
        ,      NULL                  AS ETA_DATE
        ,      NULL                  AS ETD_DATE
        ,      R.FROM_SITE        AS FROM_SITE 
        ,      R.TO_SITE          AS TO_SITE 
        ,      R.ITEM_ID          AS ITEM_ID 
        ,      R.QTY              AS QTY 
        --,       R.SHIP_TYPE          AS SHIP_TYPE
FROM  SSP_DNM_SHIP_RESULT_OWMS_V R
        WHERE R.YYYYMMDD BETWEEN  :PARAM_FROM_YYYYMMDD  AND :PARAM_TO_YYYYMMDD 
) AA
WHERE 1 = 1 
 AND FROM_SITE NOT LIKE (''%-E'')
GROUP BY 
 AA.DIVISION_ID
,AA.YYYYMMDD
,AA.ITEM_ID
,AA.FROM_SITE) BB
WHERE 1 = 1 
 AND BB.GAP <> 0 
 AND BB.FROM_SITE NOT IN (SELECT SCM_SITE_ID
  FROM LGCE_SCMPROD.SCM_MST_SITE
  WHERE OPERATION_GROUP = ''P'' AND VALID_YN = ''Y''   AND OSP_YN = ''Y'')'), 'Y', 'Y', 'attackgo', TO_DATE('2022-01-12 10:50:14','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:21','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (88, '-', 'Shipment_Result_ERP_VS_OWMS_TEST', 'test', TO_CLOB('
SELECT
 BB.DIVISION_ID
,BB.YYYYMMDD
,BB.ITEM_ID
,BB.FROM_SITE
,BB.ERP
,BB.OWMS
,BB.GAP
, ROW_NUMBER() OVER (ORDER BY BB.DIVISION_ID,BB.YYYYMMDD,BB.ITEM_ID,BB.FROM_SITE) AS ROW_NUM
  FROM (
    SELECT 
                 AA.DIVISION_ID
                ,AA.YYYYMMDD
                ,AA.ITEM_ID
                ,AA.FROM_SITE
                ,SUM(CASE AA.TYPE WHEN ''ERP'' THEN AA.QTY ELSE 0  END) AS ''ERP''
                ,SUM(CASE AA.TYPE WHEN ''OWMS'' THEN AA.QTY ELSE 0 END) AS ''OWMS''
                ,SUM(CASE AA.TYPE WHEN ''ERP'' THEN AA.QTY ELSE 0  END) - SUM(CASE AA.TYPE WHEN ''OWMS'' THEN AA.QTY ELSE 0 END) AS ''GAP''
           FROM 
   (    SELECT  
         E.DIVISION_ID         AS DIVISION_ID
        , ''ERP''                AS TYPE
        ,E.CONFIRM_ID          AS CONFIRM_ID
        ,E.ORDER_NO            AS ERP_SO_NO 
        ,E.EXFACTORY_DATE      AS YYYYMMDD
        ,E.TRANSPORT_MODE      AS TRANSPORT_MODE
        ,E.INCOTERMS           AS INCOTERMS
        ,E.ETA_DATE            AS ETA_DATE
        ,E.ETD_DATE            AS ETD_DATE
        ,E.FROM_SCM_SITE_ID    AS FROM_SITE
        ,E.TO_SCM_SITE_ID      AS TO_SITE
        ,E.ITEM_ID             AS ITEM_ID
        ,SUM(E.EXFACTORY_QTY ) AS QTY 
        FROM SCM_DNM_EXFACTORY_RESULT E
            JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
                ON L.LOOKUP_TYPE = ''ERP_SSP_TYPE'' -- LOOKUP에 등록된 공정만 
            AND L.VALID_YN = ''Y''
            AND L.SEGMENT1    = E.SSP_TYPE
        JOIN SCM_MST_SITE S                     
            ON E.FROM_SCM_SITE_ID    = S.SCM_SITE_ID                 
           AND E.DIVISION_ID    = S.DIVISION_ID                 
           AND S.SITE_TYPE        = ''PLANT''                                      
        JOIN SCM_MST_ITEM_SN T                 
            ON E.ITEM_ID        = T.ITEM_ID                     
           AND E.DIVISION_ID    = T.DIVISION_ID                 
           AND S.COMPANY_ID        = T.COMPANY_ID                 
           AND T.ITEM_TYPE        NOT IN (''Q'',''R'')
        WHERE 1=1
        AND   NVL(E.EXFACTORY_STATUS,''D90'') NOT IN (''D90'' ,''D10'') -- D90: DO삭제 , D10:DO생성 
        AND   E.CONFIRM_ID LIKE ''C%''
        AND   E.EXFACTORY_DATE BETWEEN ''20220101''  AND ''20220112'' 
                
        GROUP BY E.DIVISION_ID 
        ,        E.CONFIRM_ID
        ,        E.ORDER_NO
        ,        E.EXFACTORY_DATE
        ,        E.TRANSPORT_MODE
        ,        E.INCOTERMS        
        ,         E.ETA_DATE        
        ,         E.ETD_DATE
        ,         E.FROM_SCM_SITE_ID    
        ,         E.TO_SCM_SITE_ID    
        ,         E.ITEM_ID
        -- )
    -- , RESULT_ERP_C_NON AS 
    -- (
UNION ALL 
        -- ERP 출하실적에서 CONFIRM_ID 없는 실적 
        SELECT  E.DIVISION_ID             AS DIVISION_ID
        ,        ''ERP''                      AS TYPE
        ,       ''-''                       AS CONFIRM_ID
        ,       E.ORDER_NO                  AS ERP_SO_NO 
        ,       E.EXFACTORY_DATE          AS YYYYMMDD
        ,       E.TRANSPORT_MODE          AS TRANSPORT_MODE
        ,       E.INCOTERMS                  AS INCOTERMS
        ,        E.ETA_DATE                  AS ETA_DATE
        ,        E.ETD_DATE                  AS ETD_DATE
        ,       E.FROM_SCM_SITE_ID        AS FROM_SITE                                                                    
        ,       NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)     AS TO_SITE   
        ,       E.ITEM_ID                 AS ITEM_ID
        ,       SUM(E.EXFACTORY_QTY )     AS QTY  
        FROM SCM_DNM_EXFACTORY_RESULT E
        JOIN SCM_MST_SITE S                     
            ON E.FROM_SCM_SITE_ID    = S.SCM_SITE_ID                 
           AND E.DIVISION_ID    = S.DIVISION_ID                 
           AND S.SITE_TYPE        = ''PLANT''                                      
        JOIN SCM_MST_ITEM_SN T     ') || TO_CLOB('            
            ON E.ITEM_ID        = T.ITEM_ID                     
           AND E.DIVISION_ID    = T.DIVISION_ID                 
           AND S.COMPANY_ID        = T.COMPANY_ID                 
           AND T.ITEM_TYPE        NOT IN (''Q'',''R'')
        JOIN  SCP_MST_FINAL_ITEM F -- SCP 대상 ITEM만 
            ON F.ITEM_ID = E.ITEM_ID 
            AND F.DIVISION_ID = E.DIVISION_ID
        JOIN   SCM_MST_SITE FS
            ON FS.SCM_SITE_ID = E.FROM_SCM_SITE_ID 
           AND FS.DIVISION_ID = E.DIVISION_ID 
           -- AND NVL(FS.OSP_YN,''N'') <> ''Y'' --- [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN <> ''Y'' 조건제외)
           -- 2020.09.18 김광희 책임 요청으로 주석처리
           -- 2021.04.15 김광희 책임 요청으로 주석해제
        JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L
            ON L.LOOKUP_TYPE = ''ERP_ORDER_TYPE'' -- LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 
        AND L.VALID_YN = ''Y''
        AND L.SEGMENT1    = E.ORDER_TYPE_CODE     
        LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL L3
                ON L3.LOOKUP_TYPE = ''SHIP_RESULT_TO_SITE_MAPPING'' --SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE 
            AND L3.SEGMENT1    = E.DIVISION_ID 
            AND L3.SEGMENT2    = E.SOLDTO_CODE
            AND L3.SEGMENT3    = E.SHIPTO_CODE                        
        WHERE 1=1
        AND   NVL(E.EXFACTORY_STATUS,''D90'') NOT IN (''D90'' ,''D10'') -- D90: DO삭제 , D10:DO생성 
        AND   NVL(E.CONFIRM_ID,'''') NOT LIKE  ''C%''
        AND   E.EXFACTORY_DATE BETWEEN  ''20220101''  AND ''20220112'' 
        AND   E.STORAGE_ID NOT IN (''6000'' ,''799A'') --상품창고제외 
        AND   E.STORAGE_ID NOT IN (SELECT SEGMENT1 
                                FROM SCM_ADM_LOOKUP_MASTER_DETAIL 
                                WHERE LOOKUP_TYPE = ''SSP_SHIP_RESULT_EXCEPT_STORAGE''
                                    AND VALID_YN = ''Y''
                                )    -- 사외 창고 제외 LOOKUP 관리
GROUP BY E.DIVISION_ID
        ,        E.ORDER_NO
        ,        E.FROM_SCM_SITE_ID                                                                           
        ,        NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID) 
        ,        E.ITEM_ID
        ,        E.EXFACTORY_DATE
        ,        E.TRANSPORT_MODE
        ,        E.INCOTERMS        
        ,         E.ETA_DATE        
        ,         E.ETD_DATE
        ,         E.FROM_SCM_SITE_ID    
        ,         E.TO_SCM_SITE_ID    
    UNION ALL 
        -- OWMS 출하실적/반품 [C20191205-000132]
    SELECT     R.DIVISION_ID      AS DIVISION_ID
        ,        ''OWMS''              AS TYPE
        ,      ''-''                AS CONFIRM_ID
        ,      ''-''                AS ERP_SO_NO
        ,      R.YYYYMMDD         AS YYYYMMDD
        ,      R.YYYYMMDD         AS TRANSPORT_MODE
        ,      ''-''                  AS INCOTERMS
        ,      NULL                  AS ETA_DATE
        ,      NULL                  AS ETD_DATE
        ,      R.FROM_SITE        AS FROM_SITE 
        ,      R.TO_SITE          AS TO_SITE 
        ,      R.ITEM_ID          AS ITEM_ID 
        ,      R.QTY              AS QTY 
        --,       R.SHIP_TYPE          AS SHIP_TYPE
FROM  SSP_DNM_SHIP_RESULT_OWMS_V R
        WHERE R.YYYYMMDD BETWEEN  ''20220101''  AND ''20220112'' 
) AA
WHERE 1 = 1 
 AND FROM_SITE NOT LIKE (''%-E'')
GROUP BY 
 AA.DIVISION_ID
,AA.YYYYMMDD
,AA.ITEM_ID
,AA.FROM_SITE) BB
WHERE 1 = 1 
 AND BB.GAP <> 0 
 AND BB.FROM_SITE NOT IN (SELECT SCM_SITE_ID
  FROM LGCE_SCMPROD.SCM_MST_SITE
  WHERE OPERATION_GROUP = ''P'' AND VALID_YN = ''Y''   AND OSP_YN = ''Y'')


'), 'Y', 'Y', 'kimyh8848', TO_DATE('2022-01-12 12:03:08','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 09:25:21','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (89, '-', 'Material Maker Check', '자재maker 확인', '
SELECT DISTINCT a.model_id, b.group_code2, a.type, a.child_item_id, a.item_name, a.level_2_name, a.item_class_name, a.child_qty, a.child_uom, a.maker, a.seq
FROM   (
		SELECT a.division_id, a.site_id, a.plant_id, a.model_id, b.nick_name, a.parent_item_id, a.child_item_id, b.item_name, b.item_type
             , c.level_2_name, c.level_3_code, b.item_class, b.item_class_name, a.child_qty, a.child_uom, b.maker,
               CASE WHEN c.level_2_code = ''RCA''   THEN ''Cathode Active Material''
			        WHEN c.level_3_code = ''MFLCU'' THEN ''Foil Copper''
					WHEN c.level_2_code = ''RAA''   THEN ''Anode Active Material''
					WHEN c.level_3_code = ''MFLAL'' THEN ''Foil Aluminum''
					WHEN c.level_2_code = ''RSE''   THEN ''Seperator''
					WHEN c.level_2_code in (''RETCY'', ''RETRA'', ''RETPM'') THEN ''Electrolyte''
					WHEN c.level_2_code = ''MIL''   THEN ''LEAD1''
					WHEN c.level_2_code = ''MAL''   THEN ''LEAD2''
					WHEN c.level_2_code = ''MPU''   THEN ''POUCH''
               ELSE ''ETC''
               END AS Type,
               CASE WHEN c.level_2_code = ''RCA''   THEN 1
			        WHEN c.level_3_code = ''MFLCU'' THEN 2
					WHEN c.level_2_code = ''RAA''   THEN 3
					WHEN c.level_3_code = ''MFLAL'' THEN 4
					WHEN c.level_2_code = ''RSE''   THEN 5
					WHEN c.level_2_code in (''RETCY'', ''RETRA'', ''RETPM'') THEN 6
					WHEN c.level_2_code = ''MIL''   THEN 7
					WHEN c.level_2_code = ''MAL''   THEN 8
					WHEN c.level_2_code = ''MPU''   THEN 9
               ELSE 99
               END AS seq
		FROM   scm_mst_bom_sn_V a, scm_item_m_sn b, SCM_MST_ITEM_CLASS_SN c
		WHERE  1=1
		AND    a.division_id   = b.division_id
		AND    a.site_id       = b.site_id
		AND    a.child_item_id = b.item_id
		AND    b.item_class    = c.class_id
		AND    b.item_type     = ''R''

		AND   (:PARAM_ITEM_ID = '''' OR A.MODEL_ID = :PARAM_ITEM_ID) 
		AND   (:PARAM_SITE_ID = '''' OR a.site_id = :PARAM_SITE_ID)

		AND    c.level_2_code IN (''RCA'', ''MFL'', ''RAA'', ''RSE'', ''MIL'' , ''MAL'', ''MPU'')
       ) a
       , SCP_MST_FINAL_ITEM b
WHERE  1=1
AND    A.model_id = B.ITEM_ID
', 'Y', 'Y', 'blueeos', TO_DATE('2022-02-15 11:10:34','YYYY-MM-DD HH24:MI:SS'), 'admin', TO_DATE('2026-06-21 08:44:42','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO SCM_MGR.SCM_ADM_DQ_LIST (DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT, VALID_YN, ADMIN_ONLY_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10) VALUES (90, '-', 'SITE_SHIPTO_SOLDTO', 'SALES SITE 의 모든 SHIPTO, SOLDTO 를 조회', 'SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.SITE_DESCRIPTION, B.SOLDTO_CODE, B.SHIPTO_CODE, A.VALID_YN AS SITE_VALID_YN, B.REP_YN, B.VALID_YN AS SOLDTO_SHIPTO_VALID_YN, C.PROJECT_CODE
FROM SCM_MST_SITE A
JOIN SCM_MST_SITE_CUSTOMER B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID
LEFT OUTER JOIN ( SELECT DISTINCT DIVISION_ID, SCM_SITE_ID, PROJECT_CODE
                    FROM SCM_MST_SITE_ITEM
                    ) C ON A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID
WHERE A.SITE_TYPE = ''SALES''

', 'Y', 'Y', 'hwi1993', TO_DATE('2022-03-04 15:38:42','YYYY-MM-DD HH24:MI:SS'), 'hwi1993', TO_DATE('2022-03-04 15:56:21','YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

COMMIT;
